{region "§14 Trace de blocage terrain (winch M1/M2 + translation M3)"}
// === 🕵️ 13. Trace de blocage terrain (ST_TraceWinch / ST_TraceTranslation) ===
// Pur recopie des traces publiées par PRG_04 (§8bis) et PRG_05 (§4bis). Aucun calcul métier ici.
GVL_Troubleshooting.Q_TraceWinchM1     := WinchM1Trace;
GVL_Troubleshooting.R_TraceWinchM2     := WinchM2Trace;
GVL_Troubleshooting.S_TraceTranslation := TranslationTrace;
GVL_Troubleshooting.T_Permits           := Permits;
{endregion}

// ═══════════════════════════════════════════════════════════════
// 🛗 §1 TREUIL M1 (Retenue) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ D'un coup d'œil : ce qui active/désactive la sortie M1.
//   - M1InterlockEnable      : gate finale (Enable ET pas de PowerCutOff)
//   - M1PowerCutOffSafetyInfo: défauts qui COUPENT la puissance
//   - M1SafeStopSafetyInfo   : défauts qui font SafeStop (rampe rapide)
//   - AscentPermit/DescendPermit : permis directionnels reconsommes par la barriere finale
//   - M1BlockedBySafetyInfo  : synthese (PowerCutOff OU SafeStop)
// Sources : PRG_04 (WinchM1FinalInterlockRequest / WinchM1Safety).

M1InterlockEnable := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.Enable
                      AND NOT PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerCutOff;

M1PowerCutOffSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM1Safety.PowerCutOff
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaA
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaB
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaC
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaD
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorMecaE
                        OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ThermalFault;

M1SafeStopSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM1Safety.SafeStop
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.Error
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorOperatorComm
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorEncoder
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorPhaseRotation
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorOppositeDir
                     OR PRG_04_Treuils_Benne.Data.WinchM1Safety.ErrorNoMovement;

M1BlockedBySafetyInfo := M1PowerCutOffSafetyInfo OR M1SafeStopSafetyInfo;

instWinchOutputInterlockM1(
    Enable                     := M1InterlockEnable,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged      := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerContactorEngaged,
    SafeStop                   := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.SafeStop,
    AscentPermit               := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.AscentPermit,
    DescendPermit              := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.DescendPermit,
    BrakeFeedback              := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.BrakeFeedback,
    FwdRevSpeedFeedbackOff     := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.FwdRevSpeedFeedbackOff,
    RequestedRelayFwd          := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedRelayFwd,
    RequestedRelayRev          := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedRelayRev,
    RequestedContactor1        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor1,
    RequestedContactor2        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor2,
    RequestedContactor3        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor3,
    RequestedContactor4        := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedContactor4,
    RequestedStep               := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.RequestedStep
);

M1RelayFwd        := instWinchOutputInterlockM1.RelayFwd;
M1RelayRev        := instWinchOutputInterlockM1.RelayRev;
M1SpeedContactor1 := instWinchOutputInterlockM1.Contactor1;
M1SpeedContactor2 := instWinchOutputInterlockM1.Contactor2;
M1SpeedContactor3 := instWinchOutputInterlockM1.Contactor3;
M1SpeedContactor4 := instWinchOutputInterlockM1.Contactor4;
// Pre-calcul frein M1 (regate en §2ter apres controle concordance M1/M2).
M1BrakeCmd        := M1RelayFwd OR M1RelayRev;
// Sorties physiques M1 + bus inter-PRG : ecrites en §2ter, apres le controle
// de concordance des vecteurs M1/M2 (une seule ecriture des DQ treuils).

// ═══════════════════════════════════════════════════════════════
// 🛗 §2 TREUIL M2 (Benne) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ Même lecture que M1 : gate finale, défauts PowerCutOff / SafeStop, synthèse.
// Sources : PRG_04 (WinchM2FinalInterlockRequest / WinchM2Safety / BucketState).

M2InterlockEnable := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.Enable
                      AND NOT PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerCutOff;

M2PowerCutOffSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM2Safety.PowerCutOff
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaA
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaB
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaC
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaD
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorMecaE
                        OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ThermalFault;

M2SafeStopSafetyInfo := PRG_04_Treuils_Benne.Data.WinchM2Safety.SafeStop
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.Error
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorOperatorComm
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorEncoder
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorPhaseRotation
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorOppositeDir
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.ErrorNoMovement
                     OR PRG_04_Treuils_Benne.Data.WinchM2Safety.SlackCable
                     OR PRG_04_Treuils_Benne.Data.BucketState.Error
                     OR PRG_04_Treuils_Benne.Data.BucketState.CoupledMotionBlockedByBucket;

M2BlockedBySafetyInfo := M2PowerCutOffSafetyInfo OR M2SafeStopSafetyInfo;

instWinchOutputInterlockM2(
    Enable                     := M2InterlockEnable,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged      := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerContactorEngaged,
    SafeStop                   := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.SafeStop,
    AscentPermit               := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.AscentPermit,
    DescendPermit              := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.DescendPermit,
    BrakeFeedback              := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.BrakeFeedback,
    FwdRevSpeedFeedbackOff     := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.FwdRevSpeedFeedbackOff,
    RequestedRelayFwd          := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedRelayFwd,
    RequestedRelayRev          := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedRelayRev,
    RequestedContactor1        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor1,
    RequestedContactor2        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor2,
    RequestedContactor3        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor3,
    RequestedContactor4        := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedContactor4,
    RequestedStep               := PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.RequestedStep
);

M2RelayFwd        := instWinchOutputInterlockM2.RelayFwd;
M2RelayRev        := instWinchOutputInterlockM2.RelayRev;
M2SpeedContactor1 := instWinchOutputInterlockM2.Contactor1;
M2SpeedContactor2 := instWinchOutputInterlockM2.Contactor2;
M2SpeedContactor3 := instWinchOutputInterlockM2.Contactor3;
M2SpeedContactor4 := instWinchOutputInterlockM2.Contactor4;
// Pre-calcul frein M2 (regate en §2ter apres controle concordance M1/M2).
M2BrakeCmd        := M2RelayFwd OR M2RelayRev;

// ═══════════════════════════════════════════════════════════════
// 🔒 §2ter CONCORDANCE SORTIES TREUILS M1/M2
// ═══════════════════════════════════════════════════════════════
// Les 2 barrieres finales (instWinchOutputInterlockM1/M2) resolvent chacune leur
// commande via des tempos INDEPENDANTES : rien ne garantit des vecteurs identiques
// le meme scan. En couple, un contacteur asymetrique = les 2 treuils tirent le
// cable de facon desynchronisee.
// 🛡️ L'ex-zeroage binaire INSTANTANE est remplace par instSyncContactorFinal :
//    reponse graduee, debounce 500 ms (tolere les transitoires de changement de
//    palier), et remontee decodee. La coupure effective (SafeStop niveau 1,
//    PowerCutOff niveau 2 via MecaE bit13) est appliquee par la chaine safety
//    (PRG_04) au scan suivant. Bypass = GVL_IHM.M1M2Sync.Bypass.Global.
// Concordance contacteurs M1/M2 : jamais armee pendant un homing machine (M2-M1 varie
// volontairement de ~15 m -> faux ContactorMismatch -> escalade MecaE bit13 / PowerCutOff).
WinchOutputCoupled := (PRG_04_Treuils_Benne.Data.SyncState.SyncActive
                       OR PRG_03_Modes_Cycle.Data.WinchBothIntent.Active)
                      AND NOT PRG_02_Acquisition.Data.MachineHoming.Active;

// Frein = OR des relais de sens GATES (jamais desserre sans un sens valide).
M1BrakeCmd := M1RelayFwd OR M1RelayRev;
M2BrakeCmd := M2RelayFwd OR M2RelayRev;

{region "🛡️ §2quater Garde anti-chatter dure sorties contacteurs M1/M2"}
// ═══════════════════════════════════════════════════════════════
// 🛡️ §2quater GARDE ANTI-CHATTER DURE — au plus près des sorties contacteurs
// ═══════════════════════════════════════════════════════════════
// Dernier rempart avant l'écriture hardware : contacteurs de SENS et de PALIER passent
// par un FB_ContactorProtector. À la retombée d'une commande, aucune ré-activation avant
// CST_ContactorMinInterval (400 ms). Les interlocks amont séquencent déjà à >= 500 ms
// -> transparent en exploitation ; n'agit qu'en cas de re-commande anormalement rapide
// (bug logique, bypass, glitch concordance §2ter).
// Enable=TRUE fixe : sécurité positive assurée par le FB (Cmd=FALSE si non autorisé).
//
// ⚠️ PAS sur le FREIN : il doit pouvoir re-desserrer IMMÉDIATEMENT quand un mouvement est
//    (re)commandé. Un plancher retarderait le desserrage -> couple moteur contre frein serré
//    = contrainte méca + usure (frein serré alors que le treuil est commandé). Le frein suit déjà les relais de sens
//    filtrés (M1BrakeCmd := M1RelayFwd OR M1RelayRev), eux planchés à 1 s par le DeadTime
//    interlock -> il ne peut pas mitrailler plus vite que les relais.
instM1FwdProtector(Enable := TRUE, Request := M1RelayFwd, Cfg_MinInterval := CST_ContactorMinInterval);
instM1RevProtector(Enable := TRUE, Request := M1RelayRev, Cfg_MinInterval := CST_ContactorMinInterval);
instM1Sc1Protector(Enable := TRUE, Request := M1SpeedContactor1, Cfg_MinInterval := CST_ContactorMinInterval);
instM1Sc2Protector(Enable := TRUE, Request := M1SpeedContactor2, Cfg_MinInterval := CST_ContactorMinInterval);
instM1Sc3Protector(Enable := TRUE, Request := M1SpeedContactor3, Cfg_MinInterval := CST_ContactorMinInterval);
instM1Sc4Protector(Enable := TRUE, Request := M1SpeedContactor4, Cfg_MinInterval := CST_ContactorMinInterval);
M1RelayFwd        := instM1FwdProtector.Cmd;
M1RelayRev        := instM1RevProtector.Cmd;
M1SpeedContactor1 := instM1Sc1Protector.Cmd;
M1SpeedContactor2 := instM1Sc2Protector.Cmd;
M1SpeedContactor3 := instM1Sc3Protector.Cmd;
M1SpeedContactor4 := instM1Sc4Protector.Cmd;

instM2FwdProtector(Enable := TRUE, Request := M2RelayFwd, Cfg_MinInterval := CST_ContactorMinInterval);
instM2RevProtector(Enable := TRUE, Request := M2RelayRev, Cfg_MinInterval := CST_ContactorMinInterval);
instM2Sc1Protector(Enable := TRUE, Request := M2SpeedContactor1, Cfg_MinInterval := CST_ContactorMinInterval);
instM2Sc2Protector(Enable := TRUE, Request := M2SpeedContactor2, Cfg_MinInterval := CST_ContactorMinInterval);
instM2Sc3Protector(Enable := TRUE, Request := M2SpeedContactor3, Cfg_MinInterval := CST_ContactorMinInterval);
instM2Sc4Protector(Enable := TRUE, Request := M2SpeedContactor4, Cfg_MinInterval := CST_ContactorMinInterval);
M2RelayFwd        := instM2FwdProtector.Cmd;
M2RelayRev        := instM2RevProtector.Cmd;
M2SpeedContactor1 := instM2Sc1Protector.Cmd;
M2SpeedContactor2 := instM2Sc2Protector.Cmd;
M2SpeedContactor3 := instM2Sc3Protector.Cmd;
M2SpeedContactor4 := instM2Sc4Protector.Cmd;

// Frein recalculé APRÈS filtrage des relais de sens (pas de protecteur propre, cf. supra).
M1BrakeCmd := M1RelayFwd OR M1RelayRev;
M2BrakeCmd := M2RelayFwd OR M2RelayRev;

// Desserrage freins M1/M2 uniquement en maintenance niveau 2.
// Branche parallèle strictement bornée : MAINT_N2, chaîne AU fermée et puissance
// engagée. Le desserrage seul est volontaire pour permettre une descente par
// gravité ; les relais de sens, paliers, frein M3 et la chaîne nominale ne sont
// pas modifiés. L'AU physique coupe l'énergie en amont.
// Le bouton couplé est prioritaire sur les deux boutons individuels ; l'OR est
// réalisé sur les commandes finales de frein, jamais sur les demandes amont.
PowerCutOffReq := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerCutOff
               OR PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerCutOff
               OR PRG_05_Translation.Data.TranslationFinalInterlockRequest.PowerCutOff;
MaintenanceN2BrakeForceM1 := (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N2)
    AND PRG_02_Acquisition.HwIn.Machine.EmergencyChainClosed_DI
    AND PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI
    AND (GVL_IHM.MaintenanceN2.Cmd.BtnBothBrakeRelease
         OR GVL_IHM.MaintenanceN2.Cmd.BtnM1BrakeRelease);
MaintenanceN2BrakeForceM2 := (PRG_03_Modes_Cycle.Data.Auth.Mode = E_Mode.MAINT_N2)
    AND PRG_02_Acquisition.HwIn.Machine.EmergencyChainClosed_DI
    AND PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI
    AND (GVL_IHM.MaintenanceN2.Cmd.BtnBothBrakeRelease
         OR GVL_IHM.MaintenanceN2.Cmd.BtnM2BrakeRelease);
M1BrakeCmd := M1BrakeCmd OR MaintenanceN2BrakeForceM1;
M2BrakeCmd := M2BrakeCmd OR MaintenanceN2BrakeForceM2;
{endregion}

{region "🔀 §2quinquies Concordance contacteurs M1/M2"}
// Compare les vecteurs PHYSIQUES finaux M1/M2 (post §2quater). Reponse graduee via
// FB_SyncContactor : niveau 1 (debounce 500 ms) -> Data.ContactorMismatch -> SafeStop
// des 2 treuils (PRG_04, scan N+1) ; niveau 2 (persistance CST_SyncEscalationTime) ->
// Data.ContactorMismatchEscalated -> latch MecaE escalade -> PowerCutOff.
// Bypass : groupe synchro treuils OU l'un des 2 bypass groupe treuil (l'operateur
// qui bypasse un treuil en MES neutralise aussi la concordance).
instSyncContactorFinal(
    Enable        := TRUE,
    Reset         := PRG_07_Supervision.FaultMachineReset_IHM,
    SyncEnable    := WinchOutputCoupled,
    RelayFwdM1    := M1RelayFwd,        RelayFwdM2    := M2RelayFwd,
    RelayRevM1    := M1RelayRev,        RelayRevM2    := M2RelayRev,
    Contactor1_M1 := M1SpeedContactor1, Contactor1_M2 := M2SpeedContactor1,
    Contactor2_M1 := M1SpeedContactor2, Contactor2_M2 := M2SpeedContactor2,
    Contactor3_M1 := M1SpeedContactor3, Contactor3_M2 := M2SpeedContactor3,
    Contactor4_M1 := M1SpeedContactor4, Contactor4_M2 := M2SpeedContactor4,
    BypassGlobal  := GVL_IHM.M1M2Sync.Bypass.Global
                     OR GVL_IHM.M1TreuilRetenue.Bypass.Global
                     OR GVL_IHM.M2TreuilBenne.Bypass.Global
                     OR GVL_IHM.M1TreuilRetenue.Bypass.ContactorFeedback
                     OR GVL_IHM.M2TreuilBenne.Bypass.ContactorFeedback
                     OR GVL_IHM.M1TreuilRetenue.Bypass.Safety
                     OR GVL_IHM.M2TreuilBenne.Bypass.Safety
                     OR GVL_IHM.M1TreuilRetenue.Bypass.Process
                     OR GVL_IHM.M2TreuilBenne.Bypass.Process,
    DescentStep45Permit := PRG_04_Treuils_Benne.Data.AutoDiveM1Step4M2Step5Active,
    SpeedStepTable  := _WinchSpeedStepTable
);
Data.ContactorMismatch          := instSyncContactorFinal.ContactorMismatch;
Data.ContactorMismatchEscalated := instSyncContactorFinal.ContactorMismatchEscalated;
Data.SyncContactorDiag          := instSyncContactorFinal.Diag;
{endregion}

// ── Sorties physiques M1 (apres controle concordance §2ter) ──
M1_RelayAscent_RQ            := M1RelayFwd;
M1_RelayDescent_RQ           := M1RelayRev;
M1_SpeedContactor_1_DQ       := M1SpeedContactor1;
M1_SpeedContactor_2_DQ       := M1SpeedContactor2;
M1_SpeedContactor_3_DQ       := M1SpeedContactor3;
M1_SpeedContactor_4_DQ       := M1SpeedContactor4;
M1_BrakeRelease_RQ           := M1BrakeCmd;

// ── Sorties physiques M2 (apres controle concordance §2ter) ──
M2_RelayAscent_Close_RQ      := M2RelayFwd;
M2_RelayDescent_Open_RQ      := M2RelayRev;
M2_SpeedContactor_1_DQ       := M2SpeedContactor1;
M2_SpeedContactor_2_DQ       := M2SpeedContactor2;
M2_SpeedContactor_3_DQ       := M2SpeedContactor3;
M2_SpeedContactor_4_DQ       := M2SpeedContactor4;
M2_BrakeRelease_RQ           := M2BrakeCmd;

// ── Bus inter-PRG M1 (image reelle des sorties, apres §2ter) ──
Data.M1RelayFwd            := M1RelayFwd;
Data.M1RelayRev            := M1RelayRev;
Data.M1SpeedContactor1     := M1SpeedContactor1;
Data.M1SpeedContactor2     := M1SpeedContactor2;
Data.M1SpeedContactor3     := M1SpeedContactor3;
Data.M1SpeedContactor4     := M1SpeedContactor4;
Data.M1BrakeCmd            := M1BrakeCmd;

// ── Bus inter-PRG M2 (image reelle des sorties, apres §2ter) ──
Data.M2RelayFwd            := M2RelayFwd;
Data.M2RelayRev            := M2RelayRev;
Data.M2SpeedContactor1     := M2SpeedContactor1;
Data.M2SpeedContactor2     := M2SpeedContactor2;
Data.M2SpeedContactor3     := M2SpeedContactor3;
Data.M2SpeedContactor4     := M2SpeedContactor4;
Data.M2BrakeCmd            := M2BrakeCmd;

// ═══════════════════════════════════════════════════════════════
// ↔️ §3 TRANSLATION M3 (variateur AC600) — conditions + interlock + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ Même lecture : gate finale, défauts PowerCutOff / SafeStop, synthèse.
// Sources : PRG_05 (TranslationFinalInterlockRequest / TranslationSafety).

M3InterlockEnable := PRG_05_Translation.Data.TranslationFinalInterlockRequest.Enable
                      AND NOT PRG_05_Translation.Data.TranslationFinalInterlockRequest.PowerCutOff;

M3PowerCutOffSafetyInfo := PRG_05_Translation.Data.TranslationSafety.PowerCutOff
                        OR PRG_05_Translation.Data.TranslationSafety.ErrorMecaA
                        OR PRG_05_Translation.Data.TranslationSafety.ErrorMecaB
                        OR PRG_05_Translation.Data.TranslationSafety.ErrorBrakeThermal;

M3SafeStopSafetyInfo := PRG_05_Translation.Data.TranslationSafety.SafeStop
                     OR PRG_05_Translation.Data.TranslationSafety.Error
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorOperatorComm
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorDriveComm
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorPhaseRotation
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorLimitSwitch
                     OR PRG_05_Translation.Data.TranslationSafety.ErrorSensorIncoherent;

M3BlockedBySafetyInfo := M3PowerCutOffSafetyInfo OR M3SafeStopSafetyInfo;

// Coupure directionnelle ultime sur le FDC physique Tremie. Cette barriere lit
// le DI qualifie du meme scan et ne depend ni du decodeur de position, ni du G7,
// ni du step courant. Le recul vers P1/Maintenance reste autorise.
M3_TremieHardStopActive := PRG_02_Acquisition.HwIn.Translation.M3_PosTremie_DI
                           AND PRG_05_Translation.Data.TranslationFinalInterlockRequest.ReqTremieSemantic;

instTranslationOutputInterlockM3(
    Enable                     := M3InterlockEnable,
    Reset                      := PRG_07_Supervision.FaultMachineReset_IHM,
    PowerContactorEngaged      := PRG_05_Translation.Data.TranslationFinalInterlockRequest.PowerContactorEngaged,
    SafeStop                   := PRG_05_Translation.Data.TranslationFinalInterlockRequest.SafeStop,
    EffectivePermitM3_Tremie   := PRG_05_Translation.Data.TranslationFinalInterlockRequest.EffectivePermitM3_Tremie
                                  AND NOT PRG_02_Acquisition.HwIn.Translation.M3_PosTremie_DI,
    EffectivePermitM3_Maintenance := PRG_05_Translation.Data.TranslationFinalInterlockRequest.EffectivePermitM3_Maintenance,
    BrakeReleaseRequest        := PRG_05_Translation.Data.TranslationFinalInterlockRequest.BrakeReleaseRequest
                                  AND NOT M3_TremieHardStopActive,
    BrakeCommandOpenConfirmed  := PRG_05_Translation.Data.TranslationFinalInterlockRequest.BrakeCommandOpenConfirmed,
    RequestedDriveControlWord  := SEL(M3_TremieHardStopActive,
                                      PRG_05_Translation.Data.TranslationFinalInterlockRequest.RequestedDriveControlWord,
                                      WORD#0),
    RequestedDriveFreqHz       := SEL(M3_TremieHardStopActive,
                                      PRG_05_Translation.Data.TranslationFinalInterlockRequest.RequestedDriveFreqHz,
                                      0.0)
);

TranslationBrakeCmd := instTranslationOutputInterlockM3.BrakeCmd;
// Pas de garde anti-chatter sur le frein M3 : re-desserrage immédiat requis (cf. §2quater).

// ── Sorties physiques M3 ──
M3_BrakeRelease_RQ           := TranslationBrakeCmd;
M3_CommandWord               := instTranslationOutputInterlockM3.DriveControlWord;
M3_SetpointFrequencyHz       := instTranslationOutputInterlockM3.DriveFreqCmdWord;

// ── Bus inter-PRG M3 ──
Data.TranslationBrakeCmd   := TranslationBrakeCmd;

// ═══════════════════════════════════════════════════════════════
// 🪝 §4 KOBOLD (capteur fond) — commande + sortie
// ═══════════════════════════════════════════════════════════════
// Source : PRG_04 (KoboldContactorCmdArbitrated).
KoboldContactorCmd := PRG_04_Treuils_Benne.Data.KoboldContactorCmdArbitrated;
M1_M2_KoboldMeasureEnable_RQ := KoboldContactorCmd;

// ═══════════════════════════════════════════════════════════════
// 🛡️ §5 AU / MAINTIEN PUISSANCE — coupure + réarmement + sorties
// ═══════════════════════════════════════════════════════════════
// 👁️ D'un coup d'œil : ce qui coupe la puissance (PowerCutOffReq) et ce qui
//    maintient/réarme (instSafetyEmergencyManagement) → sorties physiques.
// Sources : PRG_04/05 (PowerCutOff), GVL_IHM (ArmRequest / BtnEmergencyCutOff),
//           PRG_02 (EmergencyChainClosed / PowerContactorEngaged).

// PowerCutOffReq = agrégation OU strict des demandes de coupure des trois procédés (M5, A-04).
PowerCutOffReq := PRG_04_Treuils_Benne.Data.WinchM1FinalInterlockRequest.PowerCutOff
               OR PRG_04_Treuils_Benne.Data.WinchM2FinalInterlockRequest.PowerCutOff
               OR PRG_05_Translation.Data.TranslationFinalInterlockRequest.PowerCutOff;

instSafetyEmergencyManagement(
    Enable := TRUE,
    Reset := PRG_07_Supervision.FaultMachineReset_IHM,
    ArmRequest := GVL_IHM.Emergency.Cmd.BtnEmergencyArming,
    EmergencyChainClosed := PRG_02_Acquisition.HwIn.Machine.EmergencyChainClosed_DI,
    PowerContactorEngaged := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    PowerCutOffRequest := PowerCutOffReq,
    BtnEmergencyCutOff := GVL_IHM.Emergency.Cmd.BtnEmergencyCutOff,
    // 🛠️ Bypass ingenierie MES (RETAIN, jamais IHM) — trace timing chaine/contacteur
    BypassArmingPreconditions := GVL_BypassRetain.BypassAuArmingPreconditions,
    BypassRedundancyTest := GVL_BypassRetain.BypassAuRedundancyTest,
    // Bypass canal A uniquement par la variable d'ingénierie RETAIN, jamais par l'IHM.
    BypassRedundancyTestA := GVL_BypassRetain.BypassAuRedundancyTestA,
    BypassRedundancyTestB := GVL_BypassRetain.BypassAuRedundancyTestB,
    BypassPowerCutOff := GVL_BypassRetain.BypassAuPowerCutOff
);

// ── Ordres AU (logique) — sorties structurées Status : ST_Safety_Emergency_Status + Cmd : ST_Safety_Emergency_Cmd ──
// 🛡️ Garde anti-chatter sur les 2 contacteurs CHAIN OK (PowerKeepAlive A/B) : chaque
//    ré-enclenchement est espacé d'au moins Cfg_MinInterval. Intervalle court (100 ms) :
//    inférieur à la durée du test de redondance (CST_TestDuration 200 ms) pour ne pas bloquer
//    RESTORE_A/B, mais suffisant pour tuer un mitraillage. La retombée reste instantanée.
instKeepAliveAProtector(
    Enable          := TRUE,
    Request         := instSafetyEmergencyManagement.Cmd.MaintainA_Cmd,
    Cfg_MinInterval := T#100ms
);
instKeepAliveBProtector(
    Enable          := TRUE,
    Request         := instSafetyEmergencyManagement.Cmd.MaintainB_Cmd,
    Cfg_MinInterval := T#100ms
);
PowerKeepAliveACmd := instKeepAliveAProtector.Cmd;
PowerKeepAliveBCmd := instKeepAliveBProtector.Cmd;
// 🛡️ Garde anti-chatter generique sur l'impulsion contacteur AU : une impulsion passe
//    integralement, puis aucune nouvelle avant 5s (redondant avec la garde interne du FB AU,
//    au plus pres de la sortie physique). Un cyclage rapide du contacteur casse le materiel.
instArmContactorProtector(
    Enable          := TRUE,
    Request         := instSafetyEmergencyManagement.Cmd.ArmPulse_Cmd,
    Cfg_MinInterval := T#5s
);
EmergencyArmingCmd := instArmContactorProtector.Cmd;

// ── Sorties physiques AU ──
PowerKeepAlive_A_RQ          := PowerKeepAliveACmd;
PowerKeepAlive_B_RQ          := PowerKeepAliveBCmd;
EmergencyArming_RQ           := EmergencyArmingCmd;

// ── Bus inter-PRG AU ──
Data.PowerKeepAliveACmd    := PowerKeepAliveACmd;
Data.PowerKeepAliveBCmd    := PowerKeepAliveBCmd;
Data.EmergencyArmingCmd    := EmergencyArmingCmd;
Data.TestCutActive         := instSafetyEmergencyManagement.Cmd.TestCutActive;
Data.PowerCutOffRequest    := PowerCutOffReq;

// ── Diagnostics chaîne AU (DUT structurés State/Diag, source unique) ──
EmergencyState := instSafetyEmergencyManagement.Status.State;
EmergencyDiag := instSafetyEmergencyManagement.Status.Diag;
EmergencyReady := instSafetyEmergencyManagement.Status.Ready;
EmergencyDone := instSafetyEmergencyManagement.Status.Done;
EmergencyFault := instSafetyEmergencyManagement.Status.Fault;
EmergencyOperatorMessage := instSafetyEmergencyManagement.Status.OperatorMessage;
PowerCutOffActive := PowerCutOffReq;

{region "§1 Horloge, heartbeat et reset machine"}
// === 🧩 §1 HORLOGE, HEARTBEAT & RESET MACHINE ===
// Trois fonctions de tête : clignotant global, heartbeat IHM (surveillance lien),
// et acquittement machine (porte d'entrée des reset).

// ---------- §1a. Horloge clignotante ----------
instBlink1Hz(
    ENABLE   := TRUE,
    TIMEHIGH := _BlinkTimeOn,
    TIMELOW  := _BlinkTimeOff
);
GVL_Global.BlinkClock := instBlink1Hz.OUT;

// ---------- §1b. Heartbeat IHM (front simulé) ----------
// 💓 Front heartbeat simulé par le clignotant PLC 1 Hz quand le bypass
// IhmHeartbeat est actif (défaut sécurisé), pour ne jamais latcher un timeout
// artificiel. Repasser le bypass à FALSE côté IHM active la vraie surveillance.
instDiagIhmHeartbeat(
    Enable          := TRUE,
    TglHeartbeatIhm := SEL(GVL_IHM.Network.Bypass.IhmHeartbeat, GVL_IHM.Commun.TglHeartbeatIhm, GVL_Global.BlinkClock)
);

// ---------- §1c. Acquittement global machine (reset) ----------
// 🚨 Acquittement global machine : une impulsion est émise dès que l'opérateur appuie
// sur l'un des boutons de reset IHM (défaut global, treuil M1, treuil M2, ou benne).
// Ce signal est consommé par tous les FB du domaine sécurité/métier pour réarmer
// les défauts (Reset sur front). C'est LA porte d'entrée unique de l'acquittement.
FaultMachineReset_IHM := GVL_IHM.Modes.Cmd.BtnFaultReset
                    OR GVL_IHM.M1TreuilRetenue.Cmd.BtnReset
                    OR GVL_IHM.M2TreuilBenne.Cmd.BtnReset
                    OR GVL_IHM.M2TreuilBenne.Bucket.Cmd.BtnReset
                    OR GVL_IHM.CycleSemiAuto.Cmd.BtnReset; // T -> alimente aussi PRG_03.instCycleSemiAuto.Reset (retour, scan suivant)


{endregion}

{region "§2 Persistance, bypass et simulation"}
// === 🌉 §2 PERSISTANCE, RESTAURATION & BYPASS ===
// Quatre responsabilités distinctes : persistance des configs, restauration boot des
// bypass, synchronisation bidirectionnelle IHM↔RETAIN, et pilotage des bypass par simulation.

// ---------- §2a. Persistance des configs (bridges) ----------
// Chaque FB_CfgPersistBridge_* synchronise UNE structure de config entre GVL_IHM (Hmi)
// et GVL_PERSISTENT (Persist) sur le flag `Initialized` :
//   - au 1er cycle (Hmi.Initialized=FALSE) : Hmi := Persist (restaure la config sauvegardée)
//     et JustRestored := TRUE sur ce seul cycle ;
//   - ensuite : Persist := Hmi (la config IHM est sauvegardée en continu).
// Le flag commun GVL_IHM.Commun.ConfigRestoredFromPersistent est levé dès qu'au moins
// un bridge a restauré au boot, pour signaler à l'IHM qu'une config persistante a été rappelée.

instCfgPersistBridgeWinchM1(Hmi := GVL_IHM.M1TreuilRetenue.Cfg, Persist := _WinchM1CfgPersist);
IF instCfgPersistBridgeWinchM1.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeWinchM2(Hmi := GVL_IHM.M2TreuilBenne.Cfg, Persist := _WinchM2CfgPersist);
IF instCfgPersistBridgeWinchM2.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

// M1 = MAITRE pour la position capteur haut : M1 et M2 montent lies au meme capteur,
// on force donc M2 = M1 en continu (IHM + persistant). Regler CfgTopSensorPos_M cote M1
// sur l'IHM ; le champ M2 suit automatiquement et le homing M2 (qui lit
// _WinchM2CfgPersist.CfgTopSensorPos_M) prend la meme valeur. Aucun champ persistant neuf.
GVL_IHM.M2TreuilBenne.Cfg.CfgTopSensorPos_M := GVL_IHM.M1TreuilRetenue.Cfg.CfgTopSensorPos_M;
_WinchM2CfgPersist.CfgTopSensorPos_M       := GVL_IHM.M1TreuilRetenue.Cfg.CfgTopSensorPos_M;

instCfgPersistBridgeSync(Hmi := GVL_IHM.M1M2Sync.Cfg, Persist := _SyncCfgPersist);
IF instCfgPersistBridgeSync.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeTranslation(Hmi := GVL_IHM.M3Translation.Cfg, Persist := _TranslationCfgPersist);
IF instCfgPersistBridgeTranslation.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeJoystick(Hmi := GVL_IHM.JOY1Joystick.Cfg, Persist := _JoystickCfgPersist);
IF instCfgPersistBridgeJoystick.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeEncoder(Hmi := GVL_IHM.Commun.EncoderCfg, Persist := _EncoderCfgPersist);
IF instCfgPersistBridgeEncoder.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeBucket(Hmi := GVL_IHM.M2TreuilBenne.Bucket.Cfg, Persist := _BucketCfgPersist);
IF instCfgPersistBridgeBucket.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeCommun(Hmi := GVL_IHM.Commun.Cfg, Persist := _CommunCfgPersist);
IF instCfgPersistBridgeCommun.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

// Une consigne hors borne est corrigée avant persistance et avant affichage IHM.
// Les profondeurs étant négatives, MAX retient la limite la moins profonde.
CycleDepthLowerBound_M := MAX(_CommunCfgPersist.LimitLegalDepthMinAllowed_M,
                              MAX(_WinchM1CfgPersist.CfgCableLimitDescent_M,
                                  _WinchM2CfgPersist.CfgCableLimitDescent_M));
IF GVL_IHM.CycleSemiAuto.Cfg.SetDepth_M < CycleDepthLowerBound_M THEN
    GVL_IHM.CycleSemiAuto.Cfg.SetDepth_M := CycleDepthLowerBound_M;
END_IF;
GVL_IHM.CycleSemiAuto.Cfg.ExtractionStartOpening_Pct := LIMIT(0, GVL_IHM.CycleSemiAuto.Cfg.ExtractionStartOpening_Pct, 50);
instCfgPersistBridgeCycle(Hmi := GVL_IHM.CycleSemiAuto.Cfg, Persist := _CycleCfgPersist);
GVL_IHM.CycleSemiAuto.Cfg.DrainTime_S := LIMIT(1, GVL_IHM.CycleSemiAuto.Cfg.DrainTime_S, 3600);
IF instCfgPersistBridgeCycle.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

instCfgPersistBridgeCycleMachineHoming(Hmi := GVL_IHM.CycleMachineHoming.Cfg, Persist := _CycleMachineHomingCfgPersist);
IF instCfgPersistBridgeCycleMachineHoming.JustRestored THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;

// Consigne variateur M3 (SetFreq_Hz) : pas de bridge Cfg dédié (c'est une Cmd, pas une
// Cfg) → initialisation manuelle au 1er cycle à partir du persist RETAIN _TranslationSetFreq_Hz.
// Le flag Cmd.Initialized distingue le 1er passage (restaure) des suivants (survit).
IF NOT GVL_IHM.M3Translation.Cmd.Initialized THEN
    GVL_IHM.M3Translation.Cmd.SetFreq_Hz := _TranslationSetFreq_Hz;
    GVL_IHM.M3Translation.Cmd.Initialized := TRUE;
    GVL_IHM.Commun.ConfigRestoredFromPersistent := TRUE;
END_IF;
// Recopie continue (après restauration) : toute consigne changée en session survit au
// prochain boot/reset chaud, pas seulement le défaut d'usine.
_TranslationSetFreq_Hz := GVL_IHM.M3Translation.Cmd.SetFreq_Hz;

// Acquittement du bandeau « config restaurée » par l'opérateur (front) → efface le flag.
instAckConfigRestored(CLK := GVL_IHM.Commun.BtnAckConfigRestored);
IF instAckConfigRestored.Q THEN
    GVL_IHM.Commun.ConfigRestoredFromPersistent := FALSE;
END_IF;

// ---------- §2b. Restauration boot des bypass (RETAIN → IHM) ----------
// 🎚️ Restauration boot des BYPASS IHM depuis le RETAIN (BypassXxxGlobal) :
// au 1er cycle (Bypass.Initialized=FALSE), si un bypass global RETAIN est actif, on le
// rejoue sur l'IHM, puis on marque Initialized pour ne pas réécraser les actions suivantes
// de l'opérateur. Même pattern pour chaque domaine (Translation / M1 / M2 / Sync / Commun).
IF NOT GVL_IHM.M3Translation.Bypass.Initialized THEN
    IF BypassTranslationGlobal THEN
        GVL_IHM.M3Translation.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.M3Translation.Bypass.Initialized := TRUE;
END_IF;

IF NOT GVL_IHM.M1TreuilRetenue.Bypass.Initialized THEN
    IF BypassWinchM1Global THEN
        GVL_IHM.M1TreuilRetenue.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.M1TreuilRetenue.Bypass.Initialized := TRUE;
END_IF;

IF NOT GVL_IHM.M2TreuilBenne.Bypass.Initialized THEN
    IF BypassWinchM2Global THEN
        GVL_IHM.M2TreuilBenne.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.M2TreuilBenne.Bypass.Initialized := TRUE;
END_IF;

// Restauration boot du bypass synchro (RETAIN), même pattern que les autres domaines.
IF NOT GVL_IHM.M1M2Sync.Bypass.Initialized THEN
    IF BypassSyncGlobal THEN
        GVL_IHM.M1M2Sync.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.M1M2Sync.Bypass.Initialized := TRUE;
END_IF;

IF NOT GVL_IHM.Commun.Bypass.Initialized THEN
    IF BypassCommunGlobal THEN
        GVL_IHM.Commun.Bypass.Global := TRUE;
    END_IF;
    IF BypassLimitLegal THEN
        GVL_IHM.Commun.Bypass.LimitLegal := TRUE;
    END_IF;
    IF BypassTopLimitSwitch THEN
        GVL_IHM.Commun.Bypass.TopLimitSwitch := TRUE;
    END_IF;
    IF BypassTopLimitSoftware THEN
        GVL_IHM.Commun.Bypass.TopLimitSoftware := TRUE;
    END_IF;
    IF BypassCableLimitSwitch THEN
        GVL_IHM.Commun.Bypass.CableLimitSwitch := TRUE;
    END_IF;
    IF BypassSlackCable THEN
        GVL_IHM.Commun.Bypass.SlackCable := TRUE;
    END_IF;
    GVL_IHM.Commun.Bypass.Initialized := TRUE;
END_IF;

// Restauration boot du bypass reseau global (RETAIN), meme pattern que les autres domaines.
// GVL_IHM.Network.Bypass.Global neutralise les diagnostics bus + 5 modules E/S dans
// PRG_02_Acquisition (VH_0008ER, CANopen, EtherCAT). Sans ce relais, BypassNetworkGlobal
// etait orphelin (jamais rejoue vers l'IHM).
IF NOT GVL_IHM.Network.Bypass.Initialized THEN
    IF BypassNetworkGlobal THEN
        GVL_IHM.Network.Bypass.Global := TRUE;
    END_IF;
    GVL_IHM.Network.Bypass.Initialized := TRUE;
END_IF;

// ---------- §2c. Synchronisation bidirectionnelle IHM ↔ RETAIN ----------
// 🔄 SYNC BIDIRECTIONNEL (dernier-écrit-gagne), factorisé dans FB_MirrorBypassRetain
// (CODE/A_COMMUN) : si l'IHM a changé → RETAIN ; sinon → IHM := RETAIN.
instMirrorBypassTranslation(Hmi := GVL_IHM.M3Translation.Bypass.Global, RetainVal := BypassTranslationGlobal, Prev := PrevTranslationBypass);
instMirrorBypassM1(Hmi := GVL_IHM.M1TreuilRetenue.Bypass.Global, RetainVal := BypassWinchM1Global, Prev := PrevM1Bypass);
instMirrorBypassM2(Hmi := GVL_IHM.M2TreuilBenne.Bypass.Global, RetainVal := BypassWinchM2Global, Prev := PrevM2Bypass);
instMirrorBypassSync(Hmi := GVL_IHM.M1M2Sync.Bypass.Global, RetainVal := BypassSyncGlobal, Prev := PrevSyncBypass);
instMirrorBypassCommun(Hmi := GVL_IHM.Commun.Bypass.Global, RetainVal := BypassCommunGlobal, Prev := PrevCommunBypass);
instMirrorBypassLimitLegal(Hmi := GVL_IHM.Commun.Bypass.LimitLegal, RetainVal := BypassLimitLegal, Prev := PrevLimitLegal);
instMirrorBypassTopLimitSwitch(Hmi := GVL_IHM.Commun.Bypass.TopLimitSwitch, RetainVal := BypassTopLimitSwitch, Prev := PrevTopLimitSwitch);
instMirrorBypassTopLimitSoftware(Hmi := GVL_IHM.Commun.Bypass.TopLimitSoftware, RetainVal := BypassTopLimitSoftware, Prev := PrevTopLimitSoftware);
instMirrorBypassCableLimitSwitch(Hmi := GVL_IHM.Commun.Bypass.CableLimitSwitch, RetainVal := BypassCableLimitSwitch, Prev := PrevCableLimitSwitch);
instMirrorBypassSlackCable(Hmi := GVL_IHM.Commun.Bypass.SlackCable, RetainVal := BypassSlackCable, Prev := PrevSlackCable);
instMirrorBypassNetwork(Hmi := GVL_IHM.Network.Bypass.Global, RetainVal := BypassNetworkGlobal, Prev := PrevNetworkBypass);

// ---------- §2d. Pilotage des bypass par simulation ----------
// 🧪 PILOTAGE BYPASS IHM PAR SIMULATION (front montant/descendant)
// La simulation emprunte le chemin IHM : le bypass banc ne devient effectif
// que lorsque les trois conditions sont réunies. Sans ce gate, la valeur par
// défaut TRUE de SimulationBypassActive pouvait armer BypassProcess en MAINT_N2
// sur une machine réelle (ou avant l'activation du domaine treuil simulé).
SimulationBypassEffective := GVL_Simulation.SimulationModeActive
                             AND GVL_Simulation.SimWinchActive
                             AND GVL_Simulation.SimulationBypassActive;
SimBypassRise(CLK := SimulationBypassEffective);
SimBypassFall(CLK := SimulationBypassEffective);

IF SimBypassRise.Q THEN
    // 🧪 Bypass sim étendu aux tests Meca (Meca A-E via Safety ; NoMovement/
    // OppositeDir via Process) pour travailler sans faux blocage en banc.
    // Les trois limites banc demandées sont écrites depuis leur producteur unique.
    // Elles restent strictement inertes hors SimulationBypassEffective.
    GVL_IHM.M1TreuilRetenue.Bypass.Safety  := TRUE;
    GVL_IHM.M1TreuilRetenue.Bypass.Process := TRUE;
    GVL_IHM.M2TreuilBenne.Bypass.Safety    := TRUE;
    GVL_IHM.M2TreuilBenne.Bypass.Process   := TRUE;
    GVL_IHM.Commun.Bypass.TopLimitSwitch   := TRUE;
    GVL_IHM.Commun.Bypass.TopLimitSoftware := TRUE;
    GVL_IHM.Commun.Bypass.CableLimitSwitch := TRUE;
END_IF;
IF SimBypassFall.Q THEN
    GVL_IHM.Commun.Bypass.TopLimitSwitch   := FALSE;
    GVL_IHM.Commun.Bypass.TopLimitSoftware := FALSE;
    GVL_IHM.Commun.Bypass.CableLimitSwitch := FALSE;
    GVL_IHM.Commun.Bypass.LimitLegal       := FALSE;
    GVL_IHM.M1TreuilRetenue.Bypass.Safety  := FALSE;
    GVL_IHM.M1TreuilRetenue.Bypass.Process := FALSE;
    GVL_IHM.M2TreuilBenne.Bypass.Safety    := FALSE;
    GVL_IHM.M2TreuilBenne.Bypass.Process   := FALSE;
END_IF;

{endregion}

{region "§3 Projections IHM et mapping"}
// === 📊 §3 PROJECTIONS IHM ET MAPPING ===
// Ensemble des recopies GVL_IHM ← sources inter-PRG. Chaque sous-région est un domaine
// IHM cohérent (faits machine, heartbeat, preflight, bypass, état, réseau, cycle, bandeau).

// ---------- §3a. Faits machine communs (lecture seule) ----------
GVL_IHM.Commun.LimitLegalReached         := _CommunCfgPersist.LimitLegalEnabled
    AND ((PRG_02_Acquisition.Data.EncoderM1.Measurement.CablePosM <= _CommunCfgPersist.LimitLegalDepthMinAllowed_M)
      OR (PRG_02_Acquisition.Data.EncoderM2.Measurement.CablePosM <= _CommunCfgPersist.LimitLegalDepthMinAllowed_M));
GVL_IHM.Commun.TopPositionSensorActive   := NOT PRG_02_Acquisition.HwIn.Winch.M1M2_TopPositionFree_DI;
GVL_IHM.Commun.HydraulicThermalFault     := NOT PRG_02_Acquisition.HwIn.Machine.HydraulicThermalOk_DI;
GVL_IHM.Commun.BrakeThermalFault         := NOT PRG_02_Acquisition.HwIn.Machine.M1_M2_M3_BrakeThermalOk_DI;
GVL_IHM.Commun.PhaseRotationFault        := NOT PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI;

// ---------- §3b. Heartbeat IHM↔PLC ----------
GVL_IHM.Commun.HeartbeatIhmOk            := instDiagIhmHeartbeat.HeartbeatIhmOk;
GVL_IHM.Commun.HeartbeatIhmTimeout       := instDiagIhmHeartbeat.HeartbeatIhmTimeout;
GVL_IHM.Commun.HeartbeatIhmElapsed       := instDiagIhmHeartbeat.TimeSinceIhmEdge;
GVL_IHM.Commun.TglHeartbeatPlc           := instDiagIhmHeartbeat.TglHeartbeatPlc;

// ---------- §3c. Preflight machine à l'arrêt ----------
instPreflight(
    Execute                   := GVL_IHM.Commun.Preflight.BtnRun,
    MachineIsStill            := (PRG_04_Treuils_Benne.Data.WinchM1State.StepNumber = 0)
                                 AND (PRG_04_Treuils_Benne.Data.WinchM2State.StepNumber = 0)
                                 AND (PRG_05_Translation.Data.TranslationState.FBState = E_State.READY),
    M1BrakeApplied            := NOT PRG_02_Acquisition.HwIn.Winch.M1_BrakeIsOpen_DI,
    M2BrakeApplied            := NOT PRG_02_Acquisition.HwIn.Winch.M2_BrakeIsOpen_DI,
    M3BrakeApplied            := TRUE, // Pas de retour frein M3 direct
    M1ContactorsReleased      := PRG_02_Acquisition.HwIn.Winch.M1_ContactorsReleased_DI,
    M2ContactorsReleased      := PRG_02_Acquisition.HwIn.Winch.M2_ContactorsReleased_DI,
    M1ThermalOk               := PRG_02_Acquisition.HwIn.Winch.M1_ThermalOk_DI,
    M2ThermalOk               := PRG_02_Acquisition.HwIn.Winch.M2_ThermalOk_DI,
    BrakeThermalOk            := PRG_02_Acquisition.HwIn.Machine.M1_M2_M3_BrakeThermalOk_DI,
    PhaseRotationOk           := PRG_02_Acquisition.HwIn.Machine.PhaseRotationOk_DI,
    SlackCableTensioned       := PRG_02_Acquisition.HwIn.Winch.M2_TensionedCable_DI,
    M3SensorWordIncoherent    := PRG_05_Translation.Data.M3_SensorWordIncoherent,
    EmergencyChainClosed      := PRG_02_Acquisition.HwIn.Machine.EmergencyChainClosed_DI,
    PowerContactorEngaged     := PRG_02_Acquisition.HwIn.Machine.PowerContactorEngaged_DI,
    EncoderM1Operational      := PRG_02_Acquisition.Data.Network.EncoderM1.Operational,
    EncoderM2Operational      := PRG_02_Acquisition.Data.Network.EncoderM2.Operational,
    HomedM1                   := PRG_04_Treuils_Benne.Data.WinchM1State.Encoder.Homed,
    HomedM2                   := PRG_04_Treuils_Benne.Data.WinchM2State.Encoder.Homed,
    M1PositionInBounds        := NOT PRG_02_Acquisition.Data.EncoderM1.Measurement.EncoderIncoherent,
    M2PositionInBounds        := NOT PRG_02_Acquisition.Data.EncoderM2.Measurement.EncoderIncoherent
);
GVL_IHM.Commun.Preflight.PreflightOk      := instPreflight.PreflightOk;
GVL_IHM.Commun.Preflight.PreflightDone    := instPreflight.PreflightDone;
GVL_IHM.Commun.Preflight.PreflightBusy    := instPreflight.PreflightBusy;
GVL_IHM.Commun.Preflight.PreflightErrorId := instPreflight.PreflightErrorId;

// ---------- §3c-bis. Diagnostic passif symétrie M1/M2 (FB_Winch_Symmetry) ----------
// ⚖️ Observateur STRICT (AF-10 §7.3bis) : aucune écriture de commande, de
// sécurité ou de mouvement. Sources : états publics M1/M2 (PRG_04 Data), encodeurs
// (PRG_02), synchro (PRG_04). Config & données persistantes : GVL_PERSISTENT.
instWinchSymmetry(
    Reset           := GVL_IHM.Commun.WinchSymmetry.BtnReset,
    M1CommandActive := PRG_04_Treuils_Benne.Data.WinchM1State.Busy,
    M2CommandActive := PRG_04_Treuils_Benne.Data.WinchM2State.Busy,
    M1Direction     := SEL(PRG_04_Treuils_Benne.Data.WinchM1State.CommandedAscent, SEL(PRG_04_Treuils_Benne.Data.WinchM1State.CommandedDescend, 0, -1), 1),
    M2Direction     := SEL(PRG_04_Treuils_Benne.Data.WinchM2State.CommandedAscent, SEL(PRG_04_Treuils_Benne.Data.WinchM2State.CommandedDescend, 0, -1), 1),
    M1BrakeCmd      := PRG_04_Treuils_Benne.Data.WinchM1State.BrakeCmd,
    M2BrakeCmd      := PRG_04_Treuils_Benne.Data.WinchM2State.BrakeCmd,
    M1BrakeApplied  := NOT PRG_04_Treuils_Benne.Data.WinchM1State.BrakeCommandOpenConfirmed,
    M2BrakeApplied  := NOT PRG_04_Treuils_Benne.Data.WinchM2State.BrakeCommandOpenConfirmed,
    M1Position_M    := PRG_04_Treuils_Benne.Data.WinchM1State.Position_M,
    M2Position_M    := PRG_04_Treuils_Benne.Data.WinchM2State.Position_M,
    M1Speed_Mps     := PRG_04_Treuils_Benne.Data.WinchM1State.MeasuredSpeed_Mps,
    M2Speed_Mps     := PRG_04_Treuils_Benne.Data.WinchM2State.MeasuredSpeed_Mps,
    SyncDeviation_M := ABS(PRG_04_Treuils_Benne.Data.WinchSyncSignedDeltaPosM),
    Config          := _WinchSymmetryCfgPersist,
    Data            := _WinchSymmetryDataPersist
);
// Publication IHM (ST_WinchSymmetryHMI via GVL_IHM.Commun.WinchSymmetry) — lecture seule.
GVL_IHM.Commun.WinchSymmetry.SymmetryOk        := instWinchSymmetry.SymmetryOk;
GVL_IHM.Commun.WinchSymmetry.SymmetryValid     := instWinchSymmetry.SymmetryValid;
GVL_IHM.Commun.WinchSymmetry.DeltaStartDelay_Ms       := _WinchSymmetryDataPersist.DeltaStartDelay_Ms;
GVL_IHM.Commun.WinchSymmetry.DeltaBrakeReleaseTime_Ms := _WinchSymmetryDataPersist.DeltaBrakeReleaseTime_Ms;
GVL_IHM.Commun.WinchSymmetry.DeltaBrakeApplyTime_Ms   := _WinchSymmetryDataPersist.DeltaBrakeApplyTime_Ms;
GVL_IHM.Commun.WinchSymmetry.DeltaStopDistance_M      := UDINT_TO_REAL(_WinchSymmetryDataPersist.DeltaStopDistance_Mm) / 1000.0;
GVL_IHM.Commun.WinchSymmetry.DeltaStopTime_Ms         := _WinchSymmetryDataPersist.DeltaStopTime_Ms;
GVL_IHM.Commun.WinchSymmetry.MaxSyncDeviation_M       := _WinchSymmetryDataPersist.MaxSyncDeviation_M;

// ---------- §3d. Bypass simulation (retours simulés vers IHM) ----------
GVL_IHM.M1TreuilRetenue.Bypass.ContactorFeedback := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive;
GVL_IHM.M2TreuilBenne.Bypass.ContactorFeedback   := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimWinchActive;
GVL_IHM.M3Translation.Bypass.ContactorFeedback   := GVL_Simulation.SimulationModeActive AND GVL_Simulation.SimTranslationActive;
// Ces deux indicateurs ne décrivent PAS le domaine simulation : ils publient
// l'état des bypasss réellement consommés par FB_Safety_Winch.
GVL_IHM.Commun.SimSlackCableBypassActive         := GVL_IHM.Commun.Bypass.SlackCable;
GVL_IHM.Commun.SimTopSensorBypassActive          := GVL_IHM.Commun.Bypass.TopLimitSwitch;
GVL_IHM.Commun.WinchInputSourceChanged           := PRG_02_Acquisition.Data.InputSource.WinchInputSourceChanged;

// ---------- §3e. Structures d'état & safety (recopies directes des bus) ----------
GVL_IHM.M1TreuilRetenue.State := PRG_04_Treuils_Benne.Data.WinchM1State;
GVL_IHM.M2TreuilBenne.State := PRG_04_Treuils_Benne.Data.WinchM2State;
GVL_IHM.M1TreuilRetenue.Safety := PRG_04_Treuils_Benne.Data.WinchM1Safety;
GVL_IHM.M2TreuilBenne.Safety := PRG_04_Treuils_Benne.Data.WinchM2Safety;
GVL_IHM.M1M2Sync.State := PRG_04_Treuils_Benne.Data.SyncState;
GVL_IHM.M2TreuilBenne.Bucket.State := PRG_04_Treuils_Benne.Data.BucketState;
GVL_IHM.M3Translation.State := PRG_05_Translation.Data.TranslationState;

// ---------- §3e-bis. Gel affichage position pendant transaction preset codeur (anti-clignotement, voir VAR) ----------
M1HomingDisplaySettle(IN := NOT GVL_IHM.M1TreuilRetenue.State.Encoder.HomingBusy, PT := T#2s);
M2HomingDisplaySettle(IN := NOT GVL_IHM.M2TreuilBenne.State.Encoder.HomingBusy, PT := T#2s);
M1PosDisplayFrozen := GVL_IHM.M1TreuilRetenue.State.Encoder.HomingBusy OR NOT M1HomingDisplaySettle.Q;
M2PosDisplayFrozen := GVL_IHM.M2TreuilBenne.State.Encoder.HomingBusy OR NOT M2HomingDisplaySettle.Q;

IF M1PosDisplayFrozen THEN
    GVL_IHM.M1TreuilRetenue.State.Position_M := M1PosHmiHeld_M;
ELSE
    M1PosHmiHeld_M := GVL_IHM.M1TreuilRetenue.State.Position_M;
END_IF;

IF M2PosDisplayFrozen THEN
    GVL_IHM.M2TreuilBenne.State.Position_M                 := M2PosHmiHeld_M;
    GVL_IHM.M2TreuilBenne.Bucket.State.M2PositionCorrected := M2PosCorrectedHmiHeld_M;
ELSE
    M2PosHmiHeld_M          := GVL_IHM.M2TreuilBenne.State.Position_M;
    M2PosCorrectedHmiHeld_M := GVL_IHM.M2TreuilBenne.Bucket.State.M2PositionCorrected;
END_IF;
GVL_IHM.M3Translation.Safety := PRG_05_Translation.Data.TranslationSafety;

GVL_IHM.Modes.State.CurrentMode := PRG_03_Modes_Cycle.Data.Auth.Mode;
// — Chaîne AU / sécurité : sortie de Modes.State vers GVL_IHM.Emergency —
// Point de vue IHM : Cmd = boutons (produits par l'IHM), State = état AU
// (champs plats) + cmd FB AU (MaintainA/B_Cmd, ArmPulse_Cmd) + Diag interne.
GVL_IHM.Emergency.State.ChainOk     := PRG_06_Outputs.EmergencyState.ChainOk;
GVL_IHM.Emergency.State.ContactorOk := PRG_06_Outputs.EmergencyState.ContactorOk;
GVL_IHM.Emergency.State.Step        := PRG_06_Outputs.EmergencyState.Step;
GVL_IHM.Emergency.State.Armable     := PRG_06_Outputs.EmergencyState.Armable;
GVL_IHM.Emergency.State.ArmingBusy  := PRG_06_Outputs.EmergencyState.ArmingBusy;
GVL_IHM.Emergency.State.MaintainA_Cmd := PRG_06_Outputs.PowerKeepAliveACmd;
GVL_IHM.Emergency.State.MaintainB_Cmd := PRG_06_Outputs.PowerKeepAliveBCmd;
GVL_IHM.Emergency.State.ArmPulse_Cmd  := PRG_06_Outputs.EmergencyArmingCmd;

// =======================================================================
// 👁️ IOHW — miroir lecture seule pour visualisation IHM
// -----------------------------------------------------------------------
// Producteur unique de l'image IHM : PRG_07 recopie les images déjà produites
// par PRG_02/PRG_06. Aucun champ GVL_IHM.IoHw n'est consommé comme commande.
// Les deux voies réservées/non documentées restent visibles explicitement.
// =======================================================================
// Image arbitrée (réel hors simulation, SimBench lorsque le domaine Translation est actif).
// Le miroir IHM/Trace doit observer exactement la même image que PRG_05.
GVL_IHM.IoHw.In.Hardware := PRG_02_Acquisition.HwIn;
GVL_IHM.IoHw.In.Network := PRG_02_Acquisition.Data.Network;
GVL_IHM.IoHw.In.InputModules := PRG_02_Acquisition.Data.InputModules;
GVL_IHM.IoHw.In.DataValid := PRG_02_Acquisition.Data.DataValid;
GVL_IHM.IoHw.In.COD1_AccValue := COD1_AccValue;
GVL_IHM.IoHw.In.COD2_AccValue := COD2_AccValue;
GVL_IHM.IoHw.In.JoyAna3Raw := joyANA3;
GVL_IHM.IoHw.In.JoyAna4Raw := joyANA4;
GVL_IHM.IoHw.In.Vh0800EndBit05Reserved := FALSE;

GVL_IHM.IoHw.Out.Logical := PRG_06_Outputs.Data;
GVL_IHM.IoHw.Out.M1_RelayAscent_RQ := M1_RelayAscent_RQ;
GVL_IHM.IoHw.Out.M1_RelayDescent_RQ := M1_RelayDescent_RQ;
GVL_IHM.IoHw.Out.M2_RelayAscent_Close_RQ := M2_RelayAscent_Close_RQ;
GVL_IHM.IoHw.Out.M2_RelayDescent_Open_RQ := M2_RelayDescent_Open_RQ;
GVL_IHM.IoHw.Out.M1_SpeedContactor_1_DQ := M1_SpeedContactor_1_DQ;
GVL_IHM.IoHw.Out.M1_SpeedContactor_2_DQ := M1_SpeedContactor_2_DQ;
GVL_IHM.IoHw.Out.M1_SpeedContactor_3_DQ := M1_SpeedContactor_3_DQ;
GVL_IHM.IoHw.Out.M1_SpeedContactor_4_DQ := M1_SpeedContactor_4_DQ;
GVL_IHM.IoHw.Out.M2_SpeedContactor_1_DQ := M2_SpeedContactor_1_DQ;
GVL_IHM.IoHw.Out.M2_SpeedContactor_2_DQ := M2_SpeedContactor_2_DQ;
GVL_IHM.IoHw.Out.M2_SpeedContactor_3_DQ := M2_SpeedContactor_3_DQ;
GVL_IHM.IoHw.Out.M2_SpeedContactor_4_DQ := M2_SpeedContactor_4_DQ;
GVL_IHM.IoHw.Out.M1_BrakeRelease_RQ := M1_BrakeRelease_RQ;
GVL_IHM.IoHw.Out.M2_BrakeRelease_RQ := M2_BrakeRelease_RQ;
GVL_IHM.IoHw.Out.M3_BrakeRelease_RQ := M3_BrakeRelease_RQ;
GVL_IHM.IoHw.Out.M1_M2_KoboldMeasureEnable_RQ := M1_M2_KoboldMeasureEnable_RQ;
GVL_IHM.IoHw.Out.EmergencyArming_RQ := EmergencyArming_RQ;
GVL_IHM.IoHw.Out.PowerKeepAlive_A_RQ := PowerKeepAlive_A_RQ;
GVL_IHM.IoHw.Out.PowerKeepAlive_B_RQ := PowerKeepAlive_B_RQ;
GVL_IHM.IoHw.Out.COD1_PresettTrigCmd := COD1_PresettTrigCmd;
GVL_IHM.IoHw.Out.COD1_CodeSeqTrigCmd := COD1_CodeSeqTrigCmd;
GVL_IHM.IoHw.Out.COD1_PresetValue := COD1_PresetValue;
GVL_IHM.IoHw.Out.COD2_PresettTrigCmd := COD2_PresettTrigCmd;
GVL_IHM.IoHw.Out.COD2_CodeSeqTrigCmd := COD2_CodeSeqTrigCmd;
GVL_IHM.IoHw.Out.COD2_PresetValue := COD2_PresetValue;
GVL_IHM.IoHw.Out.M3_CommandWord := M3_CommandWord;
GVL_IHM.IoHw.Out.M3_SetpointFrequencyHz := M3_SetpointFrequencyHz;
GVL_IHM.Emergency.State.Diag := PRG_06_Outputs.EmergencyDiag;
// États publics FB AU (Ready/Done/Fault/OperatorMessage) — miroir Status du FB
// (produits par PRG_06). Busy non exposé : redondant avec ArmingBusy (déjà câblé).
GVL_IHM.Emergency.State.Ready := PRG_06_Outputs.EmergencyReady;
GVL_IHM.Emergency.State.Done := PRG_06_Outputs.EmergencyDone;
GVL_IHM.Emergency.State.Fault := PRG_06_Outputs.EmergencyFault;
GVL_IHM.Emergency.State.OperatorMessage := PRG_06_Outputs.EmergencyOperatorMessage;
// OR avec les défauts d'arbitrage de mode (refus Semi-Auto, bascule de mode refusée) —
// publiés par PRG_03 : sans eux ces refus restaient silencieux pour l'opérateur.
GVL_IHM.Modes.State.AnyFaultActive := PRG_06_Outputs.EmergencyDiag.Error
                                      OR PRG_02_Acquisition.Data.InputModules.Fault
                                      OR PRG_03_Modes_Cycle.Data.ModesFault.Error
                                      OR PRG_03_Modes_Cycle.Data.ModesFault.Latched
                                      OR GVL_IHM.M1TreuilRetenue.Safety.Error
                                      OR GVL_IHM.M2TreuilBenne.Safety.Error
                                      OR GVL_IHM.M3Translation.Safety.Error
                                      OR GVL_IHM.M1M2Sync.State.Error
                                      OR GVL_IHM.M2TreuilBenne.Bucket.State.Error
                                      OR GVL_IHM.CycleSemiAuto.State.Error
                                      OR GVL_IHM.JOY1Joystick.State.Error;
// Miroir IHM des états de maintenance (AF-05 §4bis, producteur FB_Modes via PRG_03)
GVL_IHM.Modes.State.ModeChangePendingBlocked := PRG_03_Modes_Cycle.Data.Auth.ModeChangePendingBlocked;
GVL_IHM.Modes.State.ModeChangeBlockReason := PRG_03_Modes_Cycle.Data.Auth.ModeChangeBlockReason;
GVL_IHM.Modes.State.M1ContactorsReleased := PRG_03_Modes_Cycle.Data.Auth.M1ContactorsReleased;
GVL_IHM.Modes.State.M1BrakeApplied := PRG_03_Modes_Cycle.Data.Auth.M1BrakeApplied;
GVL_IHM.Modes.State.M1SpeedLow := PRG_03_Modes_Cycle.Data.Auth.M1SpeedLow;
GVL_IHM.Modes.State.M2ContactorsReleased := PRG_03_Modes_Cycle.Data.Auth.M2ContactorsReleased;
GVL_IHM.Modes.State.M2BrakeApplied := PRG_03_Modes_Cycle.Data.Auth.M2BrakeApplied;
GVL_IHM.Modes.State.M2SpeedLow := PRG_03_Modes_Cycle.Data.Auth.M2SpeedLow;
GVL_IHM.Modes.State.HomingRequiredM1 := PRG_03_Modes_Cycle.Data.Auth.HomingRequiredM1;
GVL_IHM.Modes.State.HomingRequiredM2 := PRG_03_Modes_Cycle.Data.Auth.HomingRequiredM2;
// Etat publie du cycle de referencement machine (visu IHM) - recopie whole-struct.
GVL_IHM.CycleMachineHoming.State := PRG_02_Acquisition.Data.MachineHoming;

// ---------- §3f. État joystick & réseau (diagnostic bus) ----------
GVL_IHM.JOY1Joystick.State.RawX := PRG_02_Acquisition.HwIn.Operator.JoyXRaw_ANA1;
GVL_IHM.JOY1Joystick.State.RawY := PRG_02_Acquisition.HwIn.Operator.JoyYRaw_ANA2;
GVL_IHM.JOY1Joystick.State.RawButton := PRG_02_Acquisition.HwIn.Operator.JoyBtnRaw;
GVL_IHM.JOY1Joystick.State.AxisCmdX := PRG_02_Acquisition.Data.Joystick.AxisX;
GVL_IHM.JOY1Joystick.State.AxisCmdY := PRG_02_Acquisition.Data.Joystick.AxisY;
GVL_IHM.JOY1Joystick.State.NeutralXAct := PRG_02_Acquisition.Data.Joystick.NeutralXAct;
GVL_IHM.JOY1Joystick.State.NeutralYAct := PRG_02_Acquisition.Data.Joystick.NeutralYAct;
GVL_IHM.JOY1Joystick.State.DeadmanArmed := PRG_02_Acquisition.Data.Joystick.DeadmanArmed;
