GVL_IHM.Permits.EffectivePermitBucket_Open := PRG_04_Treuils_Benne.Data.EffectivePermitBucket_Open;
GVL_IHM.Permits.EffectivePermitBucket_Close := PRG_04_Treuils_Benne.Data.EffectivePermitBucket_Close;

instTroubleshootingView(
    Enable               := TRUE,
    HwIn                 := PRG_02_Acquisition.HwIn,
    HwReal               := PRG_02_Acquisition.HwReal,
    InputModuleFault     := PRG_02_Acquisition.Data.InputModules.Fault,
    LocalDigitalIoOk     := PRG_02_Acquisition.Data.InputModules.LocalDigitalIoOk,
    Vh0800EndOk          := PRG_02_Acquisition.Data.InputModules.Vh0800EndOk,
    Vh0808EtpOk          := PRG_02_Acquisition.Data.InputModules.Vh0808EtpOk,
    Auth                 := PRG_03_Modes_Cycle.Data.Auth,
    M1LogicRequestSpeedCmd_Pct := PRG_04_Treuils_Benne.Data.M1LogicRequestSpeedCmd_Pct,
    M1LogicRequestDirection := SEL(PRG_04_Treuils_Benne.Data.WinchM1State.CommandedAscent, SEL(PRG_04_Treuils_Benne.Data.WinchM1State.CommandedDescend, 0, -1), 1),
    M2LogicRequestSpeedCmd_Pct := PRG_04_Treuils_Benne.Data.M2LogicRequestSpeedCmd_Pct,
    M2LogicRequestDirection := SEL(PRG_04_Treuils_Benne.Data.WinchM2State.CommandedAscent, SEL(PRG_04_Treuils_Benne.Data.WinchM2State.CommandedDescend, 0, -1), 1),
    WinchBothMotionDirection := SEL(PRG_03_Modes_Cycle.Data.WinchBothIntent.ReqAscent, SEL(PRG_03_Modes_Cycle.Data.WinchBothIntent.ReqDescend, 0, -1), 1),
    WinchBothMotionActive := PRG_04_Treuils_Benne.WinchBothMotionActive,
    CycleAutoBusy := PRG_03_Modes_Cycle.Data.SequenceState.Lifecycle.Busy,
    CycleM1SpeedTgt_Pct := CycleM1SpeedTgt_Pct,
    CycleM2SpeedTgt_Pct := CycleM2SpeedTgt_Pct,
    CycleBucketOpen := PRG_03_Modes_Cycle.Data.ReqProgram.ReqBucket.ReqOpen,
    CycleTargetPosition := PRG_03_Modes_Cycle.Data.ReqProgram.ReqTranslation.PositionTgt,
    SimulationModeActive := GVL_Simulation.SimulationModeActive,
    SimWinchActive       := GVL_Simulation.SimWinchActive,
    SimTranslationActive := GVL_Simulation.SimTranslationActive,
    SimOperatorActive    := GVL_Simulation.SimOperatorActive,
    SimSafetyActive      := GVL_Simulation.SimSafetyActive,
    WinchM1              := GVL_IHM.M1TreuilRetenue,
    WinchM2              := GVL_IHM.M2TreuilBenne,
    Sync                 := GVL_IHM.M1M2Sync,
    Translation          := GVL_IHM.M3Translation,
    Commun               := GVL_IHM.Commun,
    Network              := GVL_IHM.Network,
    JoystickHMI          := GVL_IHM.JOY1Joystick,
    Permits              := GVL_IHM.Permits,
    EmergencyState       := PRG_06_Outputs.EmergencyState,
    EmergencyDiag        := PRG_06_Outputs.EmergencyDiag,
    PowerCutOffActive    := PRG_06_Outputs.PowerCutOffActive,
    ArmingPulseActive    := PRG_06_Outputs.Data.EmergencyArmingCmd,
    MaintainAActive      := PRG_06_Outputs.Data.PowerKeepAliveACmd,
    MaintainBActive      := PRG_06_Outputs.Data.PowerKeepAliveBCmd,
    CycleReady           := PRG_03_Modes_Cycle.Data.SequenceState.Ready,
    CycleDone            := PRG_03_Modes_Cycle.Data.SequenceState.Lifecycle.Done,
    CycleError           := PRG_03_Modes_Cycle.Data.SequenceState.Fault.Error,
    CycleErrorId         := PRG_03_Modes_Cycle.Data.SequenceState.Fault.ErrorId,
    CycleFaultLatched    := PRG_03_Modes_Cycle.Data.SequenceState.Fault.Latched,
    CycleFaultLatchedId  := PRG_03_Modes_Cycle.Data.SequenceState.Fault.LatchedId,
    CycleChecksInhibited := PRG_03_Modes_Cycle.Data.SequenceState.CycleChecksInhibited,
    CycleIgnoredCheckId  := PRG_03_Modes_Cycle.Data.SequenceState.IgnoredCycleCheckId,
    CycleForceStepPrepared := PRG_03_Modes_Cycle.Data.SequenceState.ForceStepPrepared,
    CycleForceStepResult := PRG_03_Modes_Cycle.Data.SequenceState.ForceStepResult,
    CycleStep            := PRG_03_Modes_Cycle.Data.SequenceState.Step,
    CycleStepStr         := PRG_03_Modes_Cycle.Data.SequenceState.StepStr,
    CycleStepAtError     := PRG_03_Modes_Cycle.Data.SequenceState.StepAtFault,
    CycleWaitingForOperator := PRG_03_Modes_Cycle.Data.SequenceState.WaitingForOperator,
    CycleWaitingForProcess := PRG_03_Modes_Cycle.Data.SequenceState.WaitingForProcess,
    CycleOperatorActionId := PRG_03_Modes_Cycle.Data.SequenceState.OperatorActionId,
    CycleOperatorAction := PRG_03_Modes_Cycle.Data.SequenceState.OperatorAction,
    CycleExpectedAxis := PRG_03_Modes_Cycle.Data.SequenceState.ExpectedAxis,
    CycleExpectedDirection := PRG_03_Modes_Cycle.Data.SequenceState.ExpectedDirection,
    CycleStartRequest    := GVL_IHM.CycleSemiAuto.Cmd.BtnStart,
    CycleAbortRequest    := GVL_IHM.CycleSemiAuto.Cmd.BtnAbort,
    CycleTargetDepth_M   := GVL_IHM.CycleSemiAuto.Cfg.SetDepth_M,
    CycleKoboldBottomTouch := PRG_02_Acquisition.HwIn.Machine.M1_M2_KoboldBottomTouch_DI,
    CycleSpeedMismatchActive := PRG_03_Modes_Cycle.Data.SequenceState.SpeedMismatchActive,
    CycleLimitLegalReached := GVL_IHM.Commun.LimitLegalReached,
    CycleWinchSyncError  := PRG_04_Treuils_Benne.Data.WinchSyncError,
    JoystickDeadmanArmed := PRG_02_Acquisition.Data.Joystick.DeadmanArmed,
    JoystickAtNeutral    := PRG_02_Acquisition.Data.Joystick.AtNeutralXY,
    HomedM1              := PRG_02_Acquisition.Data.EncoderM1.Homed,
    HomedM2              := PRG_02_Acquisition.Data.EncoderM2.Homed,
    CfgTopLimitM         := _CommunCfgPersist.CfgCableLimitAscent_M,
    WinchM1Trace         := PRG_04_Treuils_Benne.Data.TraceM1,
    WinchM2Trace         := PRG_04_Treuils_Benne.Data.TraceM2,
    TranslationTrace     := PRG_05_Translation.Data.TranslationTrace
);

{endregion}

IF NOT Enable THEN
    Cmd := FALSE;
    Ready := FALSE;
    Allowed := FALSE;
    InhibitActive := FALSE;
    ActivationLatched := FALSE;
    TonInterval(IN := FALSE);
ELSE
    Ready := TRUE;
    ReqFall(CLK := Request);

    // Intervalle : arme a la retombee d'une activation, tient Cfg_MinInterval
    IF ReqFall.Q THEN
        InhibitActive := TRUE;
    END_IF;
    TonInterval(IN := InhibitActive, PT := Cfg_MinInterval);
    IF TonInterval.Q THEN
        InhibitActive := FALSE;
    END_IF;

    // Une demande passe integralement (non decoupee) tant qu'elle est maintenue, mais ne
    // peut (re)demarrer que hors intervalle. Test de niveau : robuste si Request est deja
    // TRUE au demarrage (pas de front observe).
    IF Request AND NOT InhibitActive THEN
        ActivationLatched := TRUE;
    END_IF;
    IF NOT Request THEN
        ActivationLatched := FALSE;
    END_IF;

    Allowed := NOT InhibitActive;
    Cmd := ActivationLatched;
END_IF;

// === IMPLEMENTATION ===

{region "§1 Fronts de commande"}
// 🔄 Fronts
EnableRising(CLK := Enable);
ResetEdge(CLK := Reset);
ArmReqEdge(CLK := ArmRequest);
{endregion}

{region "§2 Gate Enable (neutralisation fail-safe)"}
// 🛑 GATE — neutralisation si désactivé : réinitialise l'état interne de la séquence.
// Les sorties physiques sont forcées à FALSE par la projection fail-safe (§10) ; le socle
// défaut reste appelé (§9) pour maintenir le latch non acquitté.
IF NOT Enable THEN
    ArmingSeqStep := CST_STEP_IDLE;
    ForceTestA := FALSE;
    ForceTestB := FALSE;
    StartupFail := FALSE;
    StartupCheckDone := FALSE;
    StartupCheckOK := FALSE;
    RedundancyTestFailed := FALSE;
    EmergencyArmingFailed := FALSE;
    EmergencyArmingLockoutActive := FALSE;
    Armable := FALSE;
    ArmingBusy := FALSE;
    LastAbortStep := CST_STEP_IDLE;
    LastAbortCause := INT_TO_WORD(CST_ABORT_NONE);
    // Neutralisation = coupure surveillance, pas un defaut : Cause et Ack repartent propres
    RedundancyTestFailedCause := FALSE;
    RedundancyTestFailedAck := TRUE;
    EmergencyArmingFailedCause := FALSE;
    EmergencyArmingFailedAck := TRUE;
    TonTestA(IN := FALSE);
    TonRestoreA(IN := FALSE);
    TonTestB(IN := FALSE);
    TonRestoreB(IN := FALSE);
    TonArmingPulse(IN := FALSE);
    TonArmingConfirm(IN := FALSE);
    TonArmingLockout(IN := FALSE);
    TonRedundancyDisplay(IN := FALSE);
    TonArmingFailedDisplay(IN := FALSE);
END_IF;
{endregion}

{region "§3 Autotest demarrage"}
// 🏁 AUTOTEST DÉMARRAGE (§5.4 AF01) — vérifications synchrones 1 cycle au 1er Enable=TRUE
IF Enable THEN
    IF EnableRising.Q THEN
        StartupCheckDone := FALSE;
    END_IF;

    IF NOT StartupCheckDone THEN
        // Exécute les 4 contrôles en 1 cycle
        StartupCheckOK := EmergencyChainClosed          // 1. Boucle AU fermée
                          AND NOT PowerContactorEngaged // 2. Contacteur au repos
                          AND (ArmingSeqStep = CST_STEP_IDLE); // 4. Pas de séquence résiduelle
        StartupCheckDone := TRUE;
        StartupFail := NOT StartupCheckOK;
        // StartupFail est laté via le socle FB_FaultCore (§9) : il reste jusqu'au front Reset.
    END_IF;
END_IF;
{endregion}

{region "§4 Acquittement defauts"}
// 🔍 ACQUITTEMENT DES DÉFAUTS (pattern Cause/Ack — §3.4bis AF01, §9 STD)
// ⚠️ Reset acquitte l'affichage (Ack:=TRUE) ET vide la cause d'auto-test redondance figée.
// Conforme AF-01 §7.4 (« échec auto-test voies → diagnostiquer, puis ACQUITTER, puis réarmer » :
// acquitter est une action distincte du réarmement) et §9 STD (le Reset n'est jamais conditionné).
// Le réarmement réel de la chaîne AU se fait par bouton matériel externe, hors PLC ; la redondance
// électrique reste un étage hardware indépendant (Partie 01). Si l'auto-test PLC rejoue plus tard
// et qu'une voie est réellement collée, il re-détecte et re-latch la cause.
IF Enable THEN
    IF ResetEdge.Q THEN
        RedundancyTestFailedCause := FALSE;
        RedundancyTestFailedAck := TRUE;
        EmergencyArmingFailedCause := FALSE;
        EmergencyArmingFailedAck := TRUE;
        EmergencyArmingLockoutActive := FALSE;
        StartupFail := FALSE;
        PreArmDelayActive := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§5 Sequence rearmement AU"}
// Coupure métier effective : c'est la SEULE forme sous laquelle PowerCutOffRequest agit
// dans ce FB (abort séquence, gate Armable, chute Maintain, blocage ArmPulse).
//  - BypassPowerCutOff : bypass MES dédié « le PLC ne fait jamais chuter l'AU ».
//  - BypassArmingPreconditions : bypass MES large (arme malgré tout) — inclut la coupure.
//  - BypassRedundancyTest : n'a AUCUN effet ici (il ne touche que l'auto-test A/B).
//  - BtnEmergencyCutOff (coup-de-poing / IHM) reste traité à part et reste TOUJOURS dur.
CutOffActive := PowerCutOffRequest AND NOT BypassPowerCutOff AND NOT BypassArmingPreconditions;

// 🔀 Bypass auto-test redondance, granulaire par canal : le bypass global BypassRedundancyTest
//    vaut A + B. Un canal bypassé n'est pas forcé/vérifié et son latch RedundancyTestFailed est
//    sauté ; l'autre canal garde son test croisé et son abort CST_ABORT_REDUNDANCY_x normaux.
BypassTestA := BypassRedundancyTest OR BypassRedundancyTestA;
BypassTestB := BypassRedundancyTest OR BypassRedundancyTestB;

IF Enable THEN
    // 🛑 Coupure immédiate de toute séquence en cours
    IF ArmingSeqStep <> CST_STEP_IDLE THEN
        IF BtnEmergencyCutOff THEN
            // Avortement volontaire : pas d'alarme d'échec
            LastAbortStep := ArmingSeqStep;
            LastAbortCause := INT_TO_WORD(CST_ABORT_CUT_IHM);
            ArmingSeqStep := CST_STEP_IDLE;
        ELSIF CutOffActive THEN
            // Avortement sécurité d'urgence : coupure métier (PAS un défaut d'armement).
            // Lockout 5s + interlock (Armable/Maintain* bloqués par CutOffActive).
            // Ne pose PAS EmergencyArmingFailedCause : pas de fausse alarme "échec armement".
            EmergencyArmingLockoutActive := TRUE;
            LastAbortStep := ArmingSeqStep;
            LastAbortCause := INT_TO_WORD(CST_ABORT_POWER_CUTOFF);
            ArmingSeqStep := CST_STEP_IDLE;
        ELSIF (ArmingSeqStep = CST_STEP_PULSE OR ArmingSeqStep = CST_STEP_CONFIRM)
              AND NOT EmergencyChainClosed
              AND NOT BypassArmingPreconditions THEN
            // Chute boucle matérielle : alarme d'échec + verrouillage 5s.
            // ⛔ Levé UNIQUEMENT sous BypassArmingPreconditions. BypassRedundancyTest ne
            //    touche PAS cet abort : EmergencyChainClosed=FALSE peut aussi être un vrai
            //    coup-de-poing physique (même DI) — on ne pulse jamais le contacteur dans
            //    ce cas. Pour armer chaîne réellement ouverte : + BypassArmingPreconditions.
            EmergencyArmingFailedCause := TRUE;
            EmergencyArmingLockoutActive := TRUE;
            LastAbortStep := ArmingSeqStep;
            LastAbortCause := INT_TO_WORD(CST_ABORT_CHAIN_DROP);
            ArmingSeqStep := CST_STEP_IDLE;
        END_IF;
    END_IF;

    // 🚦 PRÉCONDITIONS D'ARMEMENT — source unique (Armable = State.Armable).
    // ⚠️ Armable_NoBlock SANS `NOT RedundancyTestFailedCause` : la cause de redondance est
    //    latée mais la séquence d'armement la re-teste (§5 étape 1/3) : l'armement reste donc
    //    réellement possible (et sûr) tant que les autres préconditions sont réunies. Afficher
    //    le bouton « Armable » sur cette cause seule bloquait le réarmement après acquittement
    //    (Reset ne purge pas la Cause, cf. §4) alors que l'armement était permis.
    // Armable ne dépend PAS de EmergencyChainClosed : c'est la séquence d'armement qui
    //   referme la chaîne (PowerKeepAlive en série dans la boucle). Un armement gaté sur
    //   « chaîne fermée » serait impossible chaîne ouverte alors que c'est exactement l'état
    //   à récupérer. NOT BtnEmergencyCutOff / NOT CutOffActive couvrent les cas où la
    //   chaîne est ouverte pour une vraie raison (coup-de-poing, coupure métier).
    Armable_ChainOk := NOT BtnEmergencyCutOff AND NOT CutOffActive;
    Armable_Idle := (ArmingSeqStep = CST_STEP_IDLE);
    Armable_NoBlock := NOT EmergencyArmingLockoutActive AND NOT PowerContactorEngaged;
    // 🛠️ BypassArmingPreconditions (MES trace) : lève ChainOk + NoBlock ; la séquence doit
    //    toujours partir du repos (Armable_Idle conservé). ⛔ NON SECURISE.
    // NOT ArmPulseInhibitActive inclus ici : Status.State.Armable reflète alors la vérité
    //   « on peut appuyer maintenant » — FALSE pendant les 5 s de garde dure post-séquence
    //   (même après un armement réussi), TRUE de nouveau à l'échéance. Source unique pour l'IHM.
    Armable := (BypassArmingPreconditions OR (Armable_ChainOk AND Armable_NoBlock))
               AND Armable_Idle AND NOT ArmPulseInhibitActive;
    // CASE à étiquettes littérales : 0..6 = CST_STEP_* (GVL_Safety_Emergency).
    // La CI STruCpp exige ces littéraux pour les étiquettes CASE.
    CASE ArmingSeqStep OF
        0: // CST_STEP_IDLE
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonTestA(IN := FALSE, PT := CST_TestDuration);
            TonRestoreA(IN := FALSE, PT := CST_RestoreSettle);
            TonTestB(IN := FALSE, PT := CST_TestDuration);
            TonRestoreB(IN := FALSE, PT := CST_KeepAliveHold);
            TonArmingPulse(IN := FALSE, PT := CST_ArmingPulseDuration);
            TonArmingConfirm(IN := FALSE, PT := CST_ArmingConfirmTimeout);

            // ⛔ Ne JAMAIS démarrer la séquence si une coupure métier est active : sinon
            //    ArmingSeqStep passe non-IDLE 1 scan -> Maintain_ChainOk TRUE -> PowerKeepAlive
            //    (contacteur CHAIN OK) colle puis lâche à l'abandon -> mitraillage. On ne
            //    démarre que si la cause est levée. Non contournable par les bypass MES.
            // ⏱️ Délai pré-armement (CST_PreArmDelay) : l'appui est mémorisé mais on TEMPORISE
            //    avant de passer non-IDLE, pour que PowerKeepAlive (contacteur CHAIN OK) ne
            //    claque pas dans le même cycle que le reste -> contacteurs espacés, audibles un
            //    par un. Pendant ce délai on reste en IDLE : aucun maintien asserté.
            IF ArmReqEdge.Q AND Armable AND NOT ArmPulseInhibitActive AND NOT BtnEmergencyCutOff
               AND NOT CutOffActive THEN
                PreArmDelayActive := TRUE;
            END_IF;
            IF BtnEmergencyCutOff OR CutOffActive THEN
                PreArmDelayActive := FALSE; // coupure pendant le délai -> on annule
            END_IF;
            TonPreArm(IN := PreArmDelayActive, PT := CST_PreArmDelay);
            IF PreArmDelayActive AND TonPreArm.Q THEN
                PreArmDelayActive := FALSE;
                RedundancyTestFailedCause := FALSE;
                EmergencyArmingFailedCause := FALSE;
                // 🛠️ Bypass MES trace : saute tout ou partie de l'auto-test A/B.
                //  - A+B bypassés : direct RESTORE_B (maintien PowerKeepAlive A+B établi
                //    CST_KeepAliveHold) AVANT la demande contacteur -> CHAIN OK puis gros
                //    contacteur 1 s après, pas de claquement simultané.
                //  - A seul bypassé : on démarre au test canal B (TEST_B).
                //  - Aucun bypass : test croisé complet, canal A d'abord (TEST_A).
                IF BypassTestA AND BypassTestB THEN
                    ArmingSeqStep := CST_STEP_RESTORE_B;
                ELSIF BypassTestA THEN
                    ArmingSeqStep := CST_STEP_TEST_B;
                ELSE
                    ArmingSeqStep := CST_STEP_TEST_A;
                END_IF;
            END_IF;

        1: // CST_STEP_TEST_A
            ForceTestA := TRUE;
            ForceTestB := FALSE;
            TonTestA(IN := TRUE, PT := CST_TestDuration);

            IF TonTestA.Q THEN
                ForceTestA := FALSE;
                IF EmergencyChainClosed AND NOT BypassArmingPreconditions THEN
                    RedundancyTestFailedCause := TRUE;
                    LastAbortStep := CST_STEP_TEST_A;
                    LastAbortCause := INT_TO_WORD(CST_ABORT_REDUNDANCY_A);
                    ArmingSeqStep := CST_STEP_IDLE;
                ELSE
                    ArmingSeqStep := CST_STEP_RESTORE_A;
                END_IF;
            END_IF;

        2: // CST_STEP_RESTORE_A
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonRestoreA(IN := TRUE, PT := CST_RestoreSettle);

            IF TonRestoreA.Q THEN
                IF EmergencyChainClosed OR BypassArmingPreconditions THEN
                    // 🔀 Canal B bypassé (MES trace) : on saute TEST_B, direct RESTORE_B.
                    IF BypassTestB THEN
                        ArmingSeqStep := CST_STEP_RESTORE_B;
                    ELSE
                        ArmingSeqStep := CST_STEP_TEST_B;
                    END_IF;
                ELSE
                    LastAbortStep := CST_STEP_RESTORE_A;
                    LastAbortCause := INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_A);
                    ArmingSeqStep := CST_STEP_IDLE;
                END_IF;
            END_IF;

        3: // CST_STEP_TEST_B
            ForceTestA := FALSE;
            ForceTestB := TRUE;
            TonTestB(IN := TRUE, PT := CST_TestDuration);

            IF TonTestB.Q THEN
                ForceTestB := FALSE;
                IF EmergencyChainClosed AND NOT BypassArmingPreconditions THEN
                    RedundancyTestFailedCause := TRUE;
                    LastAbortStep := CST_STEP_TEST_B;
                    LastAbortCause := INT_TO_WORD(CST_ABORT_REDUNDANCY_B);
                    ArmingSeqStep := CST_STEP_IDLE;
                ELSE
                    ArmingSeqStep := CST_STEP_RESTORE_B;
                END_IF;
            END_IF;

        4: // CST_STEP_RESTORE_B
            // 🟰 Point d'entrée des chemins bypass (BypassTestA+B direct, BypassTestB depuis
            //    RESTORE_A) : les deux canaux PowerKeepAlive
            //    sont (ré)établis et TENUS CST_KeepAliveHold avant la demande contacteur de
            //    puissance -> CHAIN OK s'entend d'abord, le gros contacteur 1 s après.
            //    La boucle DOIT s'être refermée pour passer au pulse (sauf BypassArmingPreconditions).
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonRestoreB(IN := TRUE, PT := CST_KeepAliveHold);

            IF TonRestoreB.Q THEN
                IF EmergencyChainClosed OR BypassArmingPreconditions THEN
                    ArmingSeqStep := CST_STEP_PULSE;
                ELSE
                    LastAbortStep := CST_STEP_RESTORE_B;
                    LastAbortCause := INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_B);
                    ArmingSeqStep := CST_STEP_IDLE;
                END_IF;
            END_IF;

        5: // CST_STEP_PULSE
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonArmingPulse(IN := TRUE, PT := CST_ArmingPulseDuration);

            IF TonArmingPulse.Q THEN
                ArmingSeqStep := CST_STEP_CONFIRM;
            END_IF;

        6: // CST_STEP_CONFIRM
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            TonArmingConfirm(IN := TRUE, PT := CST_ArmingConfirmTimeout);

            // 🛠️ CONFIRM exige le VRAI retour contacteur. Seul BypassArmingPreconditions le
            //    fausse (banc sans contacteur). BypassRedundancyTest n'a PAS d'effet ici :
            //    le contacteur de puissance n'est pas la redondance A/B. ⛔ NON SECURISE.
            IF PowerContactorEngaged OR BypassArmingPreconditions THEN
                EmergencyArmingLockoutActive := FALSE;
                WasArmed := TRUE; // séquence aboutie -> maintien PowerKeepAlive (même sans retour contacteur, cas bypass MES)
                ArmingSeqStep := CST_STEP_IDLE;
            ELSIF TonArmingConfirm.Q THEN
                EmergencyArmingFailedCause := TRUE;
                EmergencyArmingLockoutActive := TRUE;
                LastAbortStep := CST_STEP_CONFIRM;
                LastAbortCause := INT_TO_WORD(CST_ABORT_TIMEOUT_CONTACTOR);
                ArmingSeqStep := CST_STEP_IDLE;
            END_IF;

        ELSE
            ForceTestA := FALSE;
            ForceTestB := FALSE;
            EmergencyArmingFailedCause := TRUE;
            EmergencyArmingLockoutActive := TRUE;
            LastAbortStep := ArmingSeqStep;
            LastAbortCause := INT_TO_WORD(CST_ABORT_INVALID_STEP);
            ArmingSeqStep := CST_STEP_IDLE;
    END_CASE;

    // ⏱️ Séquence de verrouillage temporel (5s)
    TonArmingLockout(IN := EmergencyArmingLockoutActive, PT := CST_ArmingLockout);
    IF TonArmingLockout.Q THEN
        EmergencyArmingLockoutActive := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§6 Gestion cause et acquittement"}
// PATTERN CAUSE/ACK — détection ré-apparition + acquittement (§3.4bis AF01, §9 STD)
// L'interlock sécurité (ci-dessous, arbitrage Cmd/Armable) utilise TOUJOURS la Cause brute,
// jamais l'Ack : l'acquittement opérateur n'ouvre jamais un interlock de sécurité.
IF Enable THEN
    RedundancyCauseEdge(CLK := RedundancyTestFailedCause);
    IF RedundancyCauseEdge.Q THEN
        RedundancyTestFailedAck := FALSE; // nouvelle occurrence -> ré-alarme, ré-acquittement requis
    END_IF;

    ArmingFailedCauseEdge(CLK := EmergencyArmingFailedCause);
    IF ArmingFailedCauseEdge.Q THEN
        EmergencyArmingFailedAck := FALSE;
    END_IF;
END_IF;
{endregion}

{region "§7 Etats publics (interlock sur Cause brute)"}
// 🚦 ÉTATS PUBLICS — interlock sur Cause brute (jamais sur l'Ack)
IF Enable THEN
    ArmingBusy := (ArmingSeqStep <> CST_STEP_IDLE) OR EmergencyArmingLockoutActive;
END_IF;
{endregion}

{region "§8 Affichage defauts IHM"}
// 📤 AFFICHAGE IHM — debounce anti-clignotement (Cause lissée) OR NOT Ack (§9 STD)
// ⚠️ Uniquement pour l'affichage : l'action de sécurité ci-dessus (§5/§6) reste instantanée
// sur la Cause brute, jamais retardée par ce debounce.
IF Enable THEN
    TonRedundancyDisplay(IN := RedundancyTestFailedCause, PT := CST_FaultDisplayDebounce);
    RedundancyTestFailed := TonRedundancyDisplay.Q OR NOT RedundancyTestFailedAck;

    TonArmingFailedDisplay(IN := EmergencyArmingFailedCause, PT := CST_FaultDisplayDebounce);
    EmergencyArmingFailed := TonArmingFailedDisplay.Q OR NOT EmergencyArmingFailedAck;
END_IF;
{endregion}

{region "§9 Synthese defaut via socle FB_FaultCore"}
// 📤 SYNTHÈSE DES ERREURS — socle standard FB_FaultCore (vue live + vue latchée).
//    Chaque cause est exprimée EN CLAIR (ST_FaultCause) ; le socle en déduit ST_Fault.
//    StartupFail est une cause indépendante (index 3, Latching=TRUE) : latée jusqu'au front Reset.
//    Mapping bits (préservé pour FB_Hmi_BannerFormatter / PRG_07) :
//      bit0 = RedundancyTestFailed, bit1 = EmergencyArmingFailed, bit3 = StartupFail.
instCauses[0].Active := RedundancyTestFailed; instCauses[0].Latching := TRUE;
instCauses[0].Texte := 'Defaut redondance contacteurs AU';
instCauses[1].Active := EmergencyArmingFailed; instCauses[1].Latching := TRUE;
instCauses[1].Texte := 'Echec rearmement contacteur AU (timeout)';
instCauses[2].Active := FALSE; instCauses[2].Latching := FALSE;
instCauses[2].Texte := '';
instCauses[3].Active := StartupFail; instCauses[3].Latching := TRUE;
instCauses[3].Texte := 'Echec autotest demarrage AU';

// Appel du socle TOUJOURS (même Enable=FALSE) : le Reset reste effectif et le latch non
// acquitté reste publié (fail-safe, pas d'effacement silencieux sur bascule Enable OFF→ON).
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Status.Fault := instFault.Fault; // source de verite = socle
{endregion}

{region "§10 Projection sorties physiques et bus"}
// ⚡ Sorties physiques — Enable gate fail-safe + interlock Cause brute.
// 🛡️ Maintien conditionné sur (chaîne fermée OU séquence en cours) : hors séquence, une
// boucle AU ouverte (coup-de-poing) coupe le maintien (fail-safe). Pendant la séquence, la
// chaîne est volontairement ouverte par ForceTestA/B -> le maintien reste autorisé (restauration).
// Latch « AU armée » : PowerKeepAlive maintenu à travers un appui AU pur (chaîne
//   physiquement ouverte par le coup-de-poing) tant qu'aucune raison MÉTIER ne demande la
//   coupure. Relâchement AU → chaîne se referme instantanément (contacts PLC restés fermés),
//   pas de réarmement. Retombe sur : coupure métier, coupure IHM, Enable OFF, défaut
//   redondance. Non RETAIN : démarrage à froid = non armé.
IF EnableRising.Q THEN
    WasArmed := FALSE;
END_IF;
IF PowerContactorEngaged THEN
    WasArmed := TRUE;
END_IF;
// ⛔ CutOffActive = coupure métier effective (cf. §5). Sous BypassPowerCutOff ou
//    BypassArmingPreconditions, PowerCutOffRequest ne lâche PAS le maintien.
//    BtnEmergencyCutOff (coup-de-poing / IHM), Enable OFF et défaut redondance
//    restent des retombées dures. BypassRedundancyTest n'a aucun effet ici.
IF (CutOffActive OR BtnEmergencyCutOff OR NOT Enable OR RedundancyTestFailedCause) THEN
    WasArmed := FALSE;
    PreArmDelayActive := FALSE; // coupure/Enable OFF pendant le délai pré-armement -> annule
END_IF;

Maintain_ChainOk := (EmergencyChainClosed OR (ArmingSeqStep <> CST_STEP_IDLE) OR WasArmed);
Maintain_NoCutOff := NOT CutOffActive AND NOT BtnEmergencyCutOff;
MaintainA_NoFault := NOT ForceTestA AND NOT RedundancyTestFailedCause;
MaintainB_NoFault := NOT ForceTestB AND NOT RedundancyTestFailedCause;
MaintainA_NoBlock := Maintain_NoCutOff AND MaintainA_NoFault;
MaintainB_NoBlock := Maintain_NoCutOff AND MaintainB_NoFault;
Cmd.MaintainA_Cmd := Enable AND Maintain_ChainOk AND MaintainA_NoBlock;
Cmd.MaintainB_Cmd := Enable AND Maintain_ChainOk AND MaintainB_NoBlock;
// 🛡️ Garde DURE anti-chatter : dès qu'une séquence d'armement DÉMARRE (IDLE -> non-IDLE),
//    aucune nouvelle tentative avant CST_ArmingLockout. Bloque aussi bien le test redondance
//    (ForceTestA/B ouvre PowerKeepAlive A puis B) que l'impulsion contacteur. Inconditionnel :
//    succès, échec, bypass ingénierie MES. Un cyclage rapide du contacteur casse le matériel.
SeqRunStartEdge(CLK := (ArmingSeqStep <> CST_STEP_IDLE));
IF SeqRunStartEdge.Q THEN
    ArmPulseInhibitActive := TRUE;
END_IF;
IF NOT Enable OR EnableRising.Q THEN
    ArmPulseInhibitActive := FALSE;
END_IF;
TonArmPulseInhibit(IN := ArmPulseInhibitActive, PT := CST_ArmingLockout);
IF TonArmPulseInhibit.Q THEN
    ArmPulseInhibitActive := FALSE;
END_IF;

// ⚠️ PAS de `NOT ArmPulseInhibitActive` ici : cette garde est armée dès le départ de
//    séquence (SeqRunStartEdge sur <> IDLE) et tiendrait 5 s -> elle étoufferait l'étape
//    PULSE elle-même (contradiction : PULSE n'existe qu'après un départ qui a armé la garde).
//    L'anti-réessai 5 s est appliqué en amont (garde départ IDLE) et en aval
//    (FB_ContactorProtector Cfg_MinInterval sur la sortie physique, PRG_06).
Cmd.ArmPulse_Cmd  := Enable AND (ArmingSeqStep = CST_STEP_PULSE)
                     AND NOT BtnEmergencyCutOff
                     AND NOT CutOffActive;
// 🧪 TestCutActive : signale à la simulation qu'un canal est coupé pour le test de
// redondance A/B (ForceTestA/B). La simulation ouvre alors la boucle AU (SimChainOk=FALSE)
// pour que le test valide la chute de chaîne — sans dépendre de PowerCutOff_A/B (cercle cassé).
Cmd.TestCutActive := Enable AND (ForceTestA OR ForceTestB);

// 🚦 Bus d'état public
Status.State.ChainOk     := Enable AND EmergencyChainClosed;
Status.State.ContactorOk := Enable AND PowerContactorEngaged;
Status.State.Step        := ArmingSeqStep;
Status.State.Armable     := Armable;
Status.State.ArmingBusy  := ArmingBusy;

// 🛡️ Bus diagnostic public (vue live du socle)
Status.Diag.Error                := Status.Fault.Error;
Status.Diag.ErrorId              := Status.Fault.ErrorId;
Status.Diag.RedundancyTestFailed := RedundancyTestFailed;
Status.Diag.ArmFailed            := EmergencyArmingFailed;
Status.Diag.WasArmed             := WasArmed;
Status.Diag.LockoutActive        := EmergencyArmingLockoutActive;
Status.Diag.LastAbortStep        := LastAbortStep;
Status.Diag.LastAbortCause       := LastAbortCause;
{endregion}

{region "§11 Etats publics IEC + message operateur"}
// 📤 ÉTATS PUBLICS IEC
Status.Ready := Enable AND NOT StartupFail;
Status.Done  := PowerContactorEngaged;

// 💬 MESSAGE OPÉRATEUR — un message explicite par état et par problème de la chaîne AU.
// Priorité : problème de sécurité > état de séquence. Fusionné côté IHM dans les messages
// opérateurs (FB_Hmi_BannerFormatter lit Diag.ErrorId / scalaires).
IF NOT Enable THEN
    Status.OperatorMessage := 'AU neutralisee (Enable=FALSE)';
ELSIF (BypassArmingPreconditions OR BypassRedundancyTest OR BypassRedundancyTestA
       OR BypassRedundancyTestB OR BypassPowerCutOff) THEN
    Status.OperatorMessage := 'AU: BYPASS INGENIERIE MES ACTIF - NON SECURISE - retirer avant exploitation';
ELSIF StartupFail THEN
    Status.OperatorMessage := 'AU: autotest demarrage echoue - verifier boucle/contacteur puis Reset';
ELSIF RedundancyTestFailed THEN
    Status.OperatorMessage := 'AU: defaut redondance contacteurs - verifier puis Reset';
ELSIF EmergencyArmingFailed THEN
    // Échec d'armement — non bloquant (alarme seule). Message court décodé sur LastAbortCause.
    IF LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_CONTACTOR) THEN
        Status.OperatorMessage := 'AU echec: contacteur non confirme';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_REDUNDANCY_A) THEN
        Status.OperatorMessage := 'AU echec: voie A collee';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_REDUNDANCY_B) THEN
        Status.OperatorMessage := 'AU echec: voie B collee';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_A) THEN
        Status.OperatorMessage := 'AU echec: chaine non refermee (voie A)';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_B) THEN
        Status.OperatorMessage := 'AU echec: chaine non refermee (voie B)';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_CHAIN_DROP) THEN
        Status.OperatorMessage := 'AU echec: chaine ouverte pendant pulse';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_POWER_CUTOFF) THEN
        Status.OperatorMessage := 'AU echec: coupure metier en sequence';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_CUT_IHM) THEN
        Status.OperatorMessage := 'AU echec: coupure IHM en sequence';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_INVALID_STEP) THEN
        Status.OperatorMessage := 'AU echec: etape invalide - Reset';
    ELSE
        Status.OperatorMessage := 'AU echec armement - relancer';
    END_IF;
ELSIF PowerCutOffRequest THEN
    Status.OperatorMessage := 'AU: coupure securite metier active - lever la cause puis rearmer';
ELSIF BtnEmergencyCutOff THEN
    Status.OperatorMessage := 'AU: coupure urgence IHM active - relacher puis rearmer';
ELSIF NOT EmergencyChainClosed THEN
    Status.OperatorMessage := 'AU: boucle urgence ouverte - verifier coup-de-poing';
ELSIF EmergencyArmingLockoutActive THEN
    Status.OperatorMessage := 'AU: verrouillage 5s actif - attendre puis rearmer';
ELSE
    // 📌 Étiquettes en LITTÉRAUX numériques (pattern PresetSeqStep / FB_Encoder_Abs) :
    //    le jumeau CI STruCpp ne génère pas d'étiquettes CASE constexpr depuis des constantes
    //    GVL (IECVar non-constexpr) ; CODESYS accepte les deux formes. La correspondance
    //    symbolique vit ici : 0..6 = CST_STEP_* (GVL_Safety_Emergency).
    CASE ArmingSeqStep OF
        0: // IDLE (= CST_STEP_IDLE)
            IF ArmPulseInhibitActive THEN
                Status.OperatorMessage := 'AU: temporisation 5s en cours - patienter';
            ELSIF PreArmDelayActive THEN
                Status.OperatorMessage := 'AU: appui pris en compte - etablissement chaine';
            ELSE
                Status.OperatorMessage := 'AU: repos - pret a rearmer';
            END_IF;
        1: // TEST_A (= CST_STEP_TEST_A)
            Status.OperatorMessage := 'AU: autotest canal A en cours';
        2: // RESTORE_A (= CST_STEP_RESTORE_A)
            Status.OperatorMessage := 'AU: restauration canal A';
        3: // TEST_B (= CST_STEP_TEST_B)
            Status.OperatorMessage := 'AU: autotest canal B en cours';
        4: // RESTORE_B (= CST_STEP_RESTORE_B)
            Status.OperatorMessage := 'AU: restauration canal B';
        5: // PULSE (= CST_STEP_PULSE)
            Status.OperatorMessage := 'AU: impulsion rearmement contacteur';
        6: // CONFIRM (= CST_STEP_CONFIRM)
            Status.OperatorMessage := 'AU: attente confirmation contacteur';
    END_CASE;
END_IF;
{endregion}

{region "§1 Gate neutralisation"}
// 🛑 1. GATE
IF NOT Enable OR BypassGlobal THEN
    ContactorMismatch := FALSE;
    ContactorMismatchEscalated := FALSE;
    CommandsCoherent := FALSE;
    DescentStep45Matched := FALSE;
    MismatchActive := FALSE;
    BothCommanded := FALSE;
    DescentStep4M1 := FALSE;
    DescentStep5M2 := FALSE;
    MismatchTimer(IN := FALSE);
    EscalationTimer(IN := FALSE);
    Diag.RelayFwdMismatch := FALSE;
    Diag.RelayRevMismatch := FALSE;
    Diag.Step1Mismatch := FALSE;
    Diag.Step2Mismatch := FALSE;
    Diag.Step3Mismatch := FALSE;
    Diag.Step4Mismatch := FALSE;
    Diag.MismatchLevel := 0;
    RETURN;
END_IF;
{endregion}

{region "§2 Detection discordance + diagnostic decode"}
// 🔍 2. COHÉRENCE DES COMMANDES SÉCURITÉ — verifie que les commandes envoyees
// aux deux treuils sont identiques (sens et contacteurs).
// Concordance ACTIVE des que les 2 treuils sont commandes (relais ou contacteur)
// OU en mode synchronisme (SyncEnable).
BothCommanded := (RelayFwdM1 OR RelayRevM1 OR Contactor1_M1 OR Contactor2_M1
                  OR Contactor3_M1 OR Contactor4_M1)
             AND (RelayFwdM2 OR RelayRevM2 OR Contactor1_M2 OR Contactor2_M2
                  OR Contactor3_M2 OR Contactor4_M2);

// Diagnostic decode : quel(s) contacteur(s) diverge(nt) (bits nommes, plusieurs possibles).
Diag.RelayFwdMismatch := (BothCommanded OR SyncEnable) AND (RelayFwdM1 <> RelayFwdM2);
Diag.RelayRevMismatch := (BothCommanded OR SyncEnable) AND (RelayRevM1 <> RelayRevM2);
Diag.Step1Mismatch    := (BothCommanded OR SyncEnable) AND (Contactor1_M1 <> Contactor1_M2);
Diag.Step2Mismatch    := (BothCommanded OR SyncEnable) AND (Contactor2_M1 <> Contactor2_M2);
Diag.Step3Mismatch    := (BothCommanded OR SyncEnable) AND (Contactor3_M1 <> Contactor3_M2);
Diag.Step4Mismatch    := (BothCommanded OR SyncEnable) AND (Contactor4_M1 <> Contactor4_M2);

DescentStep4M1 := RelayRevM1 AND NOT RelayFwdM1
                  AND (Contactor1_M1 = SpeedStepTable.P4R1)
                  AND (Contactor2_M1 = SpeedStepTable.P4R2)
                  AND (Contactor3_M1 = SpeedStepTable.P4R3)
                  AND (Contactor4_M1 = SpeedStepTable.P4R4);
DescentStep5M2 := RelayRevM2 AND NOT RelayFwdM2
                  AND (Contactor1_M2 = SpeedStepTable.P5R1)
                  AND (Contactor2_M2 = SpeedStepTable.P5R2)
                  AND (Contactor3_M2 = SpeedStepTable.P5R3)
                  AND (Contactor4_M2 = SpeedStepTable.P5R4);
DescentStep45Matched := DescentStep45Permit
                        AND NOT RelayFwdM2
                        AND NOT RelayFwdM1
                        AND DescentStep4M1
                        AND DescentStep5M2;

IF DescentStep45Matched THEN
    Diag.Step1Mismatch := FALSE;
    Diag.Step2Mismatch := FALSE;
    Diag.Step3Mismatch := FALSE;
    Diag.Step4Mismatch := FALSE;
END_IF;

MismatchActive := Diag.RelayFwdMismatch OR Diag.RelayRevMismatch
    OR Diag.Step1Mismatch OR Diag.Step2Mismatch
    OR Diag.Step3Mismatch OR Diag.Step4Mismatch;
CommandsCoherent := NOT MismatchActive;

// Niveau 1 : discordance confirmee apres MismatchDebounce.
MismatchTimer(IN := MismatchActive, PT := MismatchDebounce);
ContactorMismatch := MismatchTimer.Q;

// Niveau 2 : la discordance confirmee tient au-dela de CST_SyncEscalationTime.
EscalationTimer(IN := ContactorMismatch, PT := CST_SyncEscalationTime);
ContactorMismatchEscalated := EscalationTimer.Q;

// Niveau publie.
IF ContactorMismatchEscalated THEN
    Diag.MismatchLevel := 2;
ELSIF ContactorMismatch THEN
    Diag.MismatchLevel := 1;
ELSE
    Diag.MismatchLevel := 0;
END_IF;
{endregion}

// ── 1. FRONT RESET AVANT GATE ───────────────────────────────────────────
ResetEdge(CLK := Reset);

IF NOT Enable OR NOT PowerContactorEngaged THEN
    BrakeTimeout(IN := FALSE, PT := T#500ms);
    DriveControlWord := 0;
    DriveFreqCmd_Hz := 0.0;
    DriveFreqCmdWord := 0;
    BrakeCmd := FALSE;
    BrakeTimeoutElapsed := T#0ms;
    Ready := FALSE;
    Reason := E_TranslationFinalInterlockReason.NONE;
    RETURN;
END_IF;

MovementRequested := (RequestedDriveControlWord = 1) OR (RequestedDriveControlWord = 2);
PermitFinalBlocked := ((RequestedDriveControlWord = 1) AND NOT EffectivePermitM3_Tremie)
                   OR ((RequestedDriveControlWord = 2) AND NOT EffectivePermitM3_Maintenance);

// ── 2. Watchdog : exclusivement après ordre effectif de desserrage ──────
BrakeTimeout(
    IN := BrakeReleaseRequest AND NOT BrakeCommandOpenConfirmed AND NOT RestartInhibit,
    PT := T#500ms
);
BrakeTimeoutElapsed := BrakeTimeout.ET;

IF BrakeTimeout.Q THEN
    BrakeTimeoutCause := TRUE;
ELSIF BrakeCommandOpenConfirmed THEN
    BrakeTimeoutCause := FALSE;
END_IF;

BrakeTimeoutCauseEdge(CLK := BrakeTimeoutCause);
IF BrakeTimeoutCauseEdge.Q THEN
    BrakeTimeoutAck := FALSE;
    RestartInhibit := TRUE;
    ResetRequired := TRUE;
    NeutralRequestSeen := FALSE;
    Reason := E_TranslationFinalInterlockReason.BRAKE_COMMAND_NOT_CONFIRMED;
END_IF;

IF ResetEdge.Q THEN
    BrakeTimeoutAck := TRUE;
    ResetRequired := FALSE;
END_IF;

instCauses[0].Active   := BrakeTimeoutCause OR NOT BrakeTimeoutAck;
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Timeout confirmation ouverture frein translation';

instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

// ── 3. Réarmement anti-redémarrage automatique ──────────────────────────
IF RestartInhibit AND NOT Fault.Error AND NOT ResetRequired AND NOT ResetEdge.Q THEN
    IF RequestedDriveControlWord = 0 THEN
        NeutralRequestSeen := TRUE;
    ELSIF NeutralRequestSeen AND MovementRequested THEN
        RestartInhibit := FALSE;
        NeutralRequestSeen := FALSE;
    END_IF;
END_IF;

// ── 4. Décision finale : zéro couple utile sans confirmation frein ──────
DriveControlWord := 0;
DriveFreqCmd_Hz := 0.0;
DriveFreqCmdWord := 0;

BrakeCmd := BrakeReleaseRequest AND NOT Fault.Error AND NOT RestartInhibit;
Ready := NOT Fault.Error AND NOT RestartInhibit;

IF Fault.Error THEN
    BrakeCmd := FALSE;
ELSIF RequestedDriveControlWord = 7 THEN
    DriveControlWord := 7;
ELSIF RestartInhibit THEN
    Reason := E_TranslationFinalInterlockReason.RESTART_INHIBITED;
ELSIF MovementRequested AND NOT PermitFinalBlocked THEN
    IF BrakeReleaseRequest AND BrakeCommandOpenConfirmed THEN
        DriveControlWord := RequestedDriveControlWord;
        DriveFreqCmd_Hz := MAX(0.0, RequestedDriveFreqHz);
    END_IF;
END_IF;

// ── 5. Mise à l'échelle finale REAL Hz -> WORD registre PDO 0x3100 ──────
DriveFreqCmdWord := REAL_TO_WORD(LIMIT(0.0, DriveFreqCmd_Hz, DriveFreqWordMaxHz) * DriveFreqWordScale);

// ── 1. FRONT RESET AVANT GATE ───────────────────────────────────────────
// Le front est échantillonné même pendant Enable/AU faux : un Reset maintenu
// pendant une gate ne devient jamais un faux acquittement au retour.
ResetEdge(CLK := Reset);

// ── 2. GATE : neutralisation sûre ───────────────────────────────────────
// ErrorId, RestartInhibit et ResetRequired ne sont jamais effacés par une perte
// Enable/AU : celle-ci coupe uniquement les sorties. Le retour exige toujours un
// acquittement conscient puis une nouvelle demande opérateur.
IF NOT Enable OR NOT PowerContactorEngaged THEN
    BrakeTimeout(IN := FALSE, PT := T#500ms);
    StepDelay(IN := FALSE, PT := CST_StepRampFloorDelay);
    RestartDelay(IN := FALSE, PT := T#500ms);
    DeadTime(IN := FALSE);
    DeadTimePending := FALSE;
    DeadTimeElapsed := T#0ms;
    // 🔒 Transitoires §3bis neutralisés à la gate (latches de sûreté conservés ci-dessous).
    SenseHoldActive := FALSE; SenseHoldDone := FALSE;
    SenseHoldTimer(IN := FALSE); SenseHoldFeedbackTimer(IN := FALSE);
    SenseHoldElapsed := T#0ms;
    ContactorStuck := ContactorStuckLatched;
    ReleaseOrderActive := FALSE; ReleaseOrderDone := FALSE;
    ReleaseOrderTimer(IN := FALSE, PT := ReleaseOrderDelay);
    ReleaseOrderElapsed := T#0ms;
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    BrakeCmd := FALSE; AuthorizedStep := 0;
    BrakeTimeoutElapsed := T#0ms; RestartDelayElapsed := T#0ms; StepDelayElapsed := T#0ms;
    Ready := FALSE; Busy := FALSE; Done := FALSE;
    Error := (ErrorId <> 16#0000);
    State := E_WinchFinalInterlockState.DISABLED;
    RestartRequired := TRUE;
    // 🔒 Sorties de diagnostic et latches de sûreté VOLONTAIREMENT conservés hors Enable (AC3 / §9) :
    // - ErrorId & RestartInhibit : latches défaut et anti-redémarrage auto (doivent survivre à la perte d'Enable, acquittement conscient requis)
    // - StateAtError & Reason : snapshot d'état et cause de blocage préservés pour diagnostic IHM
    RETURN;
END_IF;

RequestedStepClamped := LIMIT(0, RequestedStep, 5);
// 🛡️ SafeStop : coupure dure à la barrière finale (défense en profondeur).
// SafeStop est consommé en §5 : quand TRUE, RelayFwd/Rev, contacteurs et frein
// sont coupés indépendamment de FB_Winch. Enable reste actif (≠ neutralisation) ;
// SafeStop n'est pas un défaut (pas de FAULT, pas de latch, pas de Reset requis).
MotorRequest := (RequestedStepClamped > 0) AND (RequestedRelayFwd XOR RequestedRelayRev);
// Defense en profondeur : le meme permis directionnel que celui applique en amont
// doit encore autoriser la sortie finale. Aucun latch ni defaut n'est cree ici :
// la demande est simplement neutralisee tant que le permis est FALSE.
PermitFinalBlocked := (RequestedRelayFwd AND NOT AscentPermit)
                   OR (RequestedRelayRev AND NOT DescendPermit);

// ── 2bis. Arbitrage Error/ErrorId AVANT §3/§5 ────────────────────────────
// ErrorId bit0 (défaut frein) est mis à jour en FIN de scan (§6bis, après BrakeCmd) —
// la valeur lue ici est donc celle de la fin du scan PRÉCÉDENT (retard d'un scan sur une
// nouvelle occurrence, ~10ms, négligeable face au budget 500ms du watchdog). Voir bandeau.
Error := (ErrorId <> 16#0000);
ErrorEdge(CLK := Error);
IF ErrorEdge.Q THEN
    StateAtError := State;
END_IF;

// ── 3. Réarmement anti-redémarrage automatique ──────────────────────────
// Après timeout : cause disparue + front Reset, puis demande moteur à zéro,
// puis nouvelle demande distincte. La retombée + T#500ms sera ensuite refaite.
IF RestartInhibit AND NOT Error AND NOT ResetRequired AND NOT ResetEdge.Q THEN
    IF NOT MotorRequest THEN
        NeutralRequestSeen := TRUE;
        RestartRequired := TRUE;
    ELSIF NeutralRequestSeen AND MotorRequest THEN
        RestartInhibit := FALSE;
        NeutralRequestSeen := FALSE;
        RestartRequired := TRUE;
        Reason := E_WinchFinalInterlockReason.NONE;
    END_IF;
END_IF;

// ── 4. Mémorisation de l'arrêt : temporisation d'anti-redémarrage chaud ──────────
// La temporisation RestartDelay (500ms) s'arme à l'arrêt du mouvement (NOT MotorRequest) et
// s'écoule pendant la pause à l'arrêt (au lieu de repartir de zéro à chaque nouvel appui) —
// permet un redémarrage instantané si la pause dépasse 500ms. Le décompte ne démarre/continue que
// si le moteur n'est plus demandé ET que le frein est physiquement confirmé fermé
// (NOT BrakeFeedback = bobine retombée, mâchoires serrées). Garde le comportement "purge pendant
// la pause" (RestartRequired ne s'arme qu'à NOT MotorRequest, indépendant de la tempo).
IF NOT MotorRequest THEN
    RestartRequired := TRUE;
END_IF;
RestartDelay(IN := RestartRequired AND NOT MotorRequest AND NOT BrakeFeedback AND NOT RestartInhibit, PT := T#500ms);
RestartDelayElapsed := RestartDelay.ET;
IF RestartDelay.Q THEN
    RestartRequired := FALSE;
END_IF;

// ── 4bis. Temps mort directionnel (TC-P10-021/022) ─────────────────────────────
// Distinct du RestartDelay (anti-court-cycle uniforme) : temps mort de redémarrage
// après arrêt, dépendant du sens de la nouvelle demande. Même sens → DeadTimeSameDir ;
// inversion → DeadTimeOppositeDir. Neutre↔sens = immédiat (pas de temps mort à l'armement).
// Le décompte se fait pendant la pause ET pendant l'attente après nouvelle demande
// (purge pendant la pause, comme RestartDelay). PT = DeadTimeOppositeDir (le plus long) ;
// à la nouvelle demande, on vérifie si le temps mort requis pour le sens réel est déjà
// écoulé (cas même sens, plus court).
IF MotorRequest THEN
    IF RequestedRelayFwd THEN
        LastDirection := 1;
    ELSE
        LastDirection := -1;
    END_IF;
END_IF;

IF NOT MotorRequest THEN
    DeadTimePending := TRUE;
END_IF;

DeadTime(IN := DeadTimePending AND NOT BrakeFeedback AND NOT RestartInhibit, PT := DeadTimeOppositeDir);
DeadTimeElapsed := DeadTime.ET;
IF DeadTime.Q THEN
    DeadTimePending := FALSE;
END_IF;

IF MotorRequest AND DeadTimePending THEN
    IF RequestedRelayFwd THEN
        NewDirection := 1;
    ELSE
        NewDirection := -1;
    END_IF;
    IF NewDirection = LastDirection THEN
        RequiredDeadTime := DeadTimeSameDir;
    ELSE
        RequiredDeadTime := DeadTimeOppositeDir;
    END_IF;
    IF DeadTime.ET >= RequiredDeadTime THEN
        DeadTimePending := FALSE;
    END_IF;
END_IF;

// ── 4ter. Maintien borné du contacteur de sens (§3bis) — AC6/AC7/AC8 ─────────
// Règle §3bis : quand RequestedStep retombe à 0 mais RequestedRelayFwd/Rev reste
// TRUE (demande transitoire de chute de palier portée par FB_Winch), la barrière NE
// force PLUS RelayFwd/Rev à FALSE immédiatement — elle TIENT le contacteur de sens
// (jamais relâché avant les contacteurs de vitesse) jusqu'à :
//   - FwdRevSpeedFeedbackOff confirmé, debounced par DropConfirmDelay (AC7 : pas
//     d'ouverture du sens sur retour simple voie seul) ; OU
//   - T_max (MaxSenseHoldTime) écoulé -> chute du sens FORCÉE + latch ContactorStuck.
// Le maintien indéfini du stator sous tension est INTERDIT (AC7). Les coupures dures
// (NOT Enable / PowerContactorEngaged=FALSE / Error / RestartInhibit) ne passent
// JAMAIS par ce maintien (AC9) : elles coupent RelayFwd/Rev immédiatement.
SenseHoldRequested := (RequestedStepClamped = 0) AND (RequestedRelayFwd OR RequestedRelayRev)
                      AND NOT Error AND NOT RestartInhibit AND NOT ContactorStuckLatched;

IF NOT Enable OR NOT PowerContactorEngaged THEN
    // 🔒 Gate dur : pas de maintien possible (les sorties sont déjà coupées §2).
    SenseHoldActive := FALSE; SenseHoldDone := FALSE;
    SenseHoldTimer(IN := FALSE, PT := MaxSenseHoldTime);
    SenseHoldFeedbackTimer(IN := FALSE, PT := DropConfirmDelay);
ELSIF Error OR RestartInhibit THEN
    // Coupure par défaut : le maintien ne survit pas à un défaut (AC9).
    SenseHoldActive := FALSE; SenseHoldDone := FALSE;
    SenseHoldTimer(IN := FALSE); SenseHoldFeedbackTimer(IN := FALSE);
ELSE
    IF MotorRequest THEN
        SenseHoldDone := FALSE;
        SenseHoldActive := FALSE;               // vraie nouvelle demande interrompt le maintien transitoire
    END_IF;
    IF NOT (RequestedRelayFwd OR RequestedRelayRev) THEN
        SenseHoldDone := FALSE;
        SenseHoldActive := FALSE;               // retour au neutre complet : plus rien a tenir
    END_IF;
    IF SenseHoldRequested AND NOT SenseHoldActive AND NOT SenseHoldDone THEN
        SenseHoldActive := TRUE;              // entrée en maintien §3bis
        SenseHoldTimer(IN := FALSE, PT := MaxSenseHoldTime);        // T_max arme au scan suivant
        SenseHoldFeedbackTimer(IN := FALSE, PT := DropConfirmDelay);
    ELSIF SenseHoldActive THEN
        SenseHoldFeedbackTimer(IN := FwdRevSpeedFeedbackOff, PT := DropConfirmDelay);
        SenseHoldTimer(IN := NOT FwdRevSpeedFeedbackOff, PT := MaxSenseHoldTime);
        IF SenseHoldFeedbackTimer.Q THEN
            // Retombée contacteurs CONFIRMÉE -> chute normale du sens (one-shot).
            SenseHoldActive := FALSE; SenseHoldDone := TRUE;
        ELSIF SenseHoldTimer.Q THEN
            // T_max sans confirmation -> chute du sens FORCÉE + latch à acquitter (AC7).
            SenseHoldActive := FALSE;
            ContactorStuckLatched := TRUE;
        END_IF;
    ELSE
        SenseHoldTimer(IN := FALSE); SenseHoldFeedbackTimer(IN := FALSE);
    END_IF;
END_IF;
SenseHoldElapsed := SenseHoldTimer.ET;
ContactorStuck := ContactorStuckLatched;

// ── 4quater. Ordre de relâchement contacteurs (vitesse avant direction) ──
// Quand le mouvement s'arrête (NOT MotorRequest ou SafeStop), les contacteurs
// de VITESSE (Contactor1-4) sont relâchés immédiatement, puis le contacteur de
// DIRECTION (RelayFwd/Rev) après ReleaseOrderDelay (>= 100ms). Protège le moteur :
// on ne coupe jamais la direction pendant que la vitesse est encore engagée.
// Les coupures dures (NOT Enable / PowerContactorEngaged / Error / RestartInhibit)
// restent immédiates (AC9) — l'ordre ne s'applique qu'à l'arrêt commandé.
// Le maintien transitoire §3bis (SenseHold) garde la priorité : quand il est actif,
// c'est lui qui tient la direction (jusqu'à confirmation retombée), pas cet ordre.
IF MotorRequest AND NOT SafeStop THEN
    // Nouvelle demande de mouvement : l'ordre de relâchement est réarmé.
    ReleaseOrderActive := FALSE;
    ReleaseOrderDone := FALSE;
    ReleaseOrderTimer(IN := FALSE, PT := ReleaseOrderDelay);
ELSIF (NOT MotorRequest OR SafeStop) AND NOT ReleaseOrderActive AND NOT ReleaseOrderDone
      AND (RequestedRelayFwd OR RequestedRelayRev) AND NOT SenseHoldActive THEN
    // Arrêt commandé : entrée en ordre de relâchement (vitesse relâchée, direction tenue).
    ReleaseOrderActive := TRUE;
END_IF;

// ── 5. Autorisation moteur ────────────────────────────────────────────────
RelayFwd := FALSE; RelayRev := FALSE;
Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
Busy := FALSE; Done := FALSE; Ready := NOT Error AND NOT ContactorStuckLatched;

IF Error THEN
    StepDelay(IN := FALSE, PT := CST_StepRampFloorDelay);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.FAULT;
ELSIF RestartInhibit THEN
    StepDelay(IN := FALSE, PT := CST_StepRampFloorDelay);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    Reason := E_WinchFinalInterlockReason.RESTART_INHIBITED;
    State := E_WinchFinalInterlockState.FAULT;
ELSIF ContactorStuckLatched THEN
    // AC7 : T_max §3bis dépassé sans confirmation retombée -> chute du sens FORCÉE.
    // RelayFwd/Rev et BrakeCmd (= RelayFwd OR RelayRev) retombent à FALSE ci-dessus.
    // Latch à acquittement conscient (ResetEdge) — jamais de redémarrage auto.
    StepDelay(IN := FALSE, PT := CST_StepRampFloorDelay);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    Reason := E_WinchFinalInterlockReason.SENSE_DROP_TIMEOUT;
    State := E_WinchFinalInterlockState.FAULT;
ELSIF ReleaseOrderActive AND NOT PermitFinalBlocked THEN
    // Ordre de relâchement : vitesse relâchée immédiatement, direction tenue
    // jusqu'à ReleaseOrderDelay, puis direction relâchée (AC1/AC2).
    StepDelay(IN := FALSE, PT := CST_StepRampFloorDelay);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    IF RequestedRelayFwd THEN RelayFwd := TRUE; END_IF;
    IF RequestedRelayRev THEN RelayRev := TRUE; END_IF;
    ReleaseOrderTimer(IN := TRUE, PT := ReleaseOrderDelay);
    ReleaseOrderElapsed := ReleaseOrderTimer.ET;
    IF ReleaseOrderTimer.Q THEN
        ReleaseOrderActive := FALSE;
        ReleaseOrderDone := TRUE;
        RelayFwd := FALSE; RelayRev := FALSE;
    END_IF;
    State := E_WinchFinalInterlockState.READY;
    Busy := TRUE;
ELSIF SafeStop OR PermitFinalBlocked THEN
    // 🛡️ SafeStop ou permis directionnel refusé : coupure dure indépendante de FB_Winch.
    // SafeStop n'est PAS un défaut : pas de FAULT, pas de latch, pas de Reset requis.
    // Les sorties sont coupées tant que l'une des causes est TRUE ; retour nominal dès sa retombée.
    // BrakeCmd (= RelayFwd OR RelayRev, §6) retombe à FALSE automatiquement.
    StepDelay(IN := FALSE, PT := CST_StepRampFloorDelay);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    State := E_WinchFinalInterlockState.READY;
ELSIF SenseHoldActive THEN
    // §3bis : RequestedStep retombé à 0 mais sens encore commandé -> on TIENT le
    // contacteur de sens jusqu'à FwdRevSpeedFeedbackOff (debounced DropConfirmDelay)
    // OU T_max. AuthorizedStep=0 (aucun contacteur de vitesse), seul le sens est tenu.
    StepDelay(IN := FALSE, PT := CST_StepRampFloorDelay);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    IF RequestedRelayFwd THEN RelayFwd := TRUE; END_IF;
    IF RequestedRelayRev THEN RelayRev := TRUE; END_IF;
    State := E_WinchFinalInterlockState.WAIT_SENSE_DROP_CONFIRM;
    Busy := TRUE;
ELSIF NOT MotorRequest THEN
    // Toute annulation de demande annule la temporisation de hausse en cours.
    StepDelay(IN := FALSE, PT := CST_StepRampFloorDelay);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.READY;
ELSIF RestartRequired OR DeadTimePending THEN
    StepDelay(IN := FALSE, PT := CST_StepRampFloorDelay);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := 0;
    AuthorizedStep := 0;
    State := E_WinchFinalInterlockState.WAIT_RESTART_DELAY;
    Busy := TRUE;
ELSE
    // ⚡ Progression de palier : la cadence NOMINALE est faite par le métier
    // (FB_WinchStepShaper). La barrière finale ajoute un PLANCHER DUR indépendant :
    // AuthorizedStep ne monte jamais de plus de +1 cran / CST_StepRampFloorDelay,
    // quelle que soit la consigne amont. Descente immédiate. 1er cran immédiat
    // (frein + sens). Si le shaper déraille (rampe à 0 -> palier 5 instantané),
    // l'interlock ramène quand même la montée en crans (défense en profondeur).
    // NOT StepDelay.Q : un TON garde .Q TRUE tant que IN est TRUE (pas d'impulsion).
    // Sans ce terme, une fois PT ecoule le +1 ci-dessous s'appliquerait a CHAQUE scan
    // (1 -> 5 en quelques scans, contacteurs relaches d'un coup). Ici le timer se re-arme
    // apres chaque cran -> les contacteurs de vitesse s'enclenchent EN CASCADE, 1 / PT.
    StepDelay(IN := (RequestedStepClamped > AuthorizedStep) AND (AuthorizedStep > 0) AND NOT StepDelay.Q,
              PT := CST_StepRampFloorDelay);
    StepDelayElapsed := StepDelay.ET;
    StepDelayTarget := RequestedStepClamped;

    IF RequestedStepClamped = 0 THEN
        AuthorizedStep := 0;
    ELSIF RequestedStepClamped < AuthorizedStep THEN
        AuthorizedStep := RequestedStepClamped;        // descente : immédiate
    ELSIF AuthorizedStep = 0 THEN
        AuthorizedStep := 1;                           // 1er cran immédiat
    ELSIF StepDelay.Q THEN
        AuthorizedStep := AuthorizedStep + 1;          // +1 cran par CST_StepRampFloorDelay
    END_IF;

    IF (AuthorizedStep > 0) OR (RequestedStepClamped > 0) THEN
        RelayFwd := RequestedRelayFwd;
        RelayRev := RequestedRelayRev;
        // Contacteurs de vitesse MASQUÉS par AuthorizedStep (table cumulative :
        // P1={} P2={K1} P3={K1,K2} P4={K1,K2,K3} P5={K1,K2,K3,K4}). La barrière ne
        // laisse jamais fermer plus de contacteurs que son propre palier autorisé.
        Contactor1 := RequestedContactor1 AND (AuthorizedStep >= 2);
        Contactor2 := RequestedContactor2 AND (AuthorizedStep >= 3);
        Contactor3 := RequestedContactor3 AND (AuthorizedStep >= 4);
        Contactor4 := RequestedContactor4 AND (AuthorizedStep >= 5);
    END_IF;

    IF NOT BrakeFeedback THEN
        State := E_WinchFinalInterlockState.WAIT_BRAKE_COMMAND_CONFIRMATION;
        Busy := TRUE;
    ELSE
        State := E_WinchFinalInterlockState.READY;
    END_IF;
END_IF;

// ── 6. Commande frein — couplage direct ────────────────────────────────
// BrakeCmd suit STRUCTURELLEMENT RelayFwd/RelayRev, calculé APRÈS leur
// finalisation ci-dessus (§5) : il hérite donc automatiquement de toutes leurs
// conditions de sécurité (Error, RestartInhibit, RestartRequired, MotorRequest)
// sans avoir à les répéter. Aucun risque d'écart frein/mouvement possible : le
// frein ne PEUT pas être commandé ouvert sans qu'un des deux relais de sens le
// soit aussi, puisque c'est la même expression. PRG_06_Outputs recalcule la
// MÊME expression indépendamment sur les DQ finaux (M1RelayFwd OR M1RelayRev)
// pour piloter physiquement la bobine — ce BrakeCmd ici sert de miroir/diagnostic
// (State, IHM) mais n'est plus câblé sur la sortie physique (voir PRG_06 §2).
BrakeCmd := RelayFwd OR RelayRev;

// ── 6bis. Watchdog frein : uniquement sur la commande RÉELLEMENT FINALE ────
// Watchdog armé sur BrakeCmd (fin §5/§6), JAMAIS sur RequestedRelayFwd/Rev (demande amont pas
// encore autorisée par le state-machine §5 — RestartRequired peut la retenir jusqu'à T#1000ms,
// largement > le seuil 500ms ci-dessous, ce qui déclencherait un faux défaut à chaque redémarrage
// normal).
BrakeTimeout(IN := BrakeCmd AND NOT BrakeFeedback AND NOT RestartInhibit, PT := T#500ms);
BrakeTimeoutElapsed := BrakeTimeout.ET;
IF BrakeTimeout.Q THEN
    BrakeTimeoutCause := TRUE;
ELSIF BrakeFeedback THEN
    BrakeTimeoutCause := FALSE;   // cause réellement disparue (retour desserrage confirmé)
END_IF;
BrakeTimeoutCauseEdge(CLK := BrakeTimeoutCause);
IF BrakeTimeoutCauseEdge.Q THEN
    BrakeTimeoutAck := FALSE;    // nouvelle occurrence -> ré-alarme, ack remis à zéro
    RestartInhibit := TRUE;
    ResetRequired := TRUE;
    NeutralRequestSeen := FALSE;
    RestartRequired := TRUE;
    Reason := E_WinchFinalInterlockReason.BRAKE_COMMAND_NOT_CONFIRMED;
END_IF;
IF ResetEdge.Q THEN
    BrakeTimeoutAck := TRUE;     // toujours effectif, sans condition externe
    ResetRequired := FALSE;
    ContactorStuckLatched := FALSE;   // acquittement conscient du latch T_max §3bis (AC7)
END_IF;
IF BrakeTimeoutCause OR NOT BrakeTimeoutAck THEN
    ErrorId := ErrorId OR 16#0001;
ELSE
    ErrorId := ErrorId AND 16#FFFE;
END_IF;

// ── 6bis2. Publication Fault transverse (socle FB_FaultCore) ──────────────
// 🧩 Homogénéisation interface (AF-03 §3) : le défaut est exposé sous la forme
// standard Fault:ST_Fault (comme FB_TranslationOutputInterlock) au lieu du plat
// Error/ErrorId. La cause unique bit0 = timeout frein, strictement identique à la
// gate interne (ErrorId) ; Latching reproduit le latch existant restitué au front
// Reset (jamais de re-armement auto). La gate interne (Error/ErrorId) reste
// inchangée — la publication n'ajoute ni ne modifie aucune coupure.
instCauses[0].Active   := ((ErrorId AND 16#0001) <> 16#0000);
instCauses[0].Latching := TRUE;
instCauses[0].Texte    := 'Timeout confirmation ouverture frein treuil';
instFault(Enable := Enable, Reset := Reset, Causes := instCauses);
Fault := instFault.Fault;

// ── 6ter. Synchronisation defaut frein en fin de scan (TC-P10-012/013/020) ──
// ErrorId bit0 (defaut frein) est pose en §6bis, APRES la machine d'etat §5.
// Sans ce bloc, la synthese Error et l'etat FAULT accusaient un retard d'un scan
// (~10 ms) sur le watchdog frein. On resynchronise Error/State et on coupe les
// sorties le MEME scan que l'apparition du defaut : c'est un defaut FINAL, coupure
// immediate (jamais un maintien ordonne §3bis).
Error := (ErrorId <> 16#0000);
IF Error THEN
    RelayFwd := FALSE; RelayRev := FALSE;
    Contactor1 := FALSE; Contactor2 := FALSE; Contactor3 := FALSE; Contactor4 := FALSE;
    BrakeCmd := FALSE;
    AuthorizedStep := 0;
    Busy := FALSE; Done := FALSE; Ready := FALSE;
    State := E_WinchFinalInterlockState.FAULT;
END_IF;

{region "§1 Gate et demande"}
ExecuteEdge(CLK := Execute);
RequestPending := RequestPending OR ExecuteEdge.Q;
PreflightBusy := RequestPending AND NOT MachineIsStill;
IF NOT MachineIsStill THEN PreflightDone := FALSE; RETURN; END_IF;
IF NOT RequestPending THEN RETURN; END_IF;
{endregion}

{region "§2 Calcul verdict"}
PreflightErrorId := 0;
(* bit0..2 frein M1/M2/M3 serré; bit3..4 contacteurs M1/M2 retombés;
   bit5..6 thermique M1/M2 OK; bit7 thermique frein OK; bit8 phases OK;
   bit9 câble M2 tendu; bit10 mot M3 cohérent; bit11 contacteur sans chaîne;
   bit12..13 codeur M1/M2 opérationnel; bit14..15 homé et position bornée M1/M2. *)
IF NOT M1BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0001; END_IF;
IF NOT M2BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0002; END_IF;
IF NOT M3BrakeApplied THEN PreflightErrorId := PreflightErrorId OR 16#0004; END_IF;
IF NOT M1ContactorsReleased THEN PreflightErrorId := PreflightErrorId OR 16#0008; END_IF;
IF NOT M2ContactorsReleased THEN PreflightErrorId := PreflightErrorId OR 16#0010; END_IF;
IF NOT M1ThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0020; END_IF;
IF NOT M2ThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0040; END_IF;
IF NOT BrakeThermalOk THEN PreflightErrorId := PreflightErrorId OR 16#0080; END_IF;
IF NOT PhaseRotationOk THEN PreflightErrorId := PreflightErrorId OR 16#0100; END_IF;
IF NOT SlackCableTensioned THEN PreflightErrorId := PreflightErrorId OR 16#0200; END_IF;
IF M3SensorWordIncoherent THEN PreflightErrorId := PreflightErrorId OR 16#0400; END_IF;
IF PowerContactorEngaged AND NOT EmergencyChainClosed THEN PreflightErrorId := PreflightErrorId OR 16#0800; END_IF;
IF NOT EncoderM1Operational THEN PreflightErrorId := PreflightErrorId OR 16#1000; END_IF;
IF NOT EncoderM2Operational THEN PreflightErrorId := PreflightErrorId OR 16#2000; END_IF;
IF NOT HomedM1 OR NOT M1PositionInBounds THEN PreflightErrorId := PreflightErrorId OR 16#4000; END_IF;
IF NOT HomedM2 OR NOT M2PositionInBounds THEN PreflightErrorId := PreflightErrorId OR 16#8000; END_IF;
{endregion}

{region "§3 Sortie"}
PreflightOk := (PreflightErrorId = 0); PreflightDone := TRUE; RequestPending := FALSE;
{endregion}

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

JustRestored := FALSE;
IF NOT Hmi.Initialized THEN
    Hmi := Persist;
    Hmi.Initialized := TRUE;
    JustRestored := TRUE;
ELSE
    Persist := Hmi;
END_IF;

// === IMPLEMENTATION ===

{region "§1 Gate"}
// 🛑 Sans Enable, aucune valeur mémorisée ne peut déclarer l'IHM valide.
IF NOT Enable THEN
    HeartbeatIhmOk := FALSE;
    HeartbeatIhmTimeout := TRUE;
    TglHeartbeatPlc := FALSE;
    TimeSinceIhmEdge := T#0s;
    LastIhmToggle := TglHeartbeatIhm;
    IhmEdgeSeen := FALSE;
    IhmTimeoutTon(IN := FALSE, PT := IhmTimeout);
    PlcToggleTon(IN := FALSE, PT := PlcTogglePeriod);
    RETURN;
END_IF;
{endregion}

{region "§2 Front IHM"}
// 📥 Front par comparaison : l'IHM écrit un BOOL toggle, pas une impulsion courte.
IhmEdgeDetected := (TglHeartbeatIhm <> LastIhmToggle);
LastIhmToggle := TglHeartbeatIhm;
IF IhmEdgeDetected THEN
    IhmEdgeSeen := TRUE;
END_IF;
{endregion}

{region "§3 Timeout IHM"}
// ⏱️ Le timer repart à chaque front. Au boot, il atteint le timeout au bout de IhmTimeout.
// HeartbeatIhmOk reste TRUE tant que le timeout n'est pas expiré (boot propre sans alarme au scan 1).
IhmTimeoutTon(IN := NOT IhmEdgeDetected, PT := IhmTimeout);
TimeSinceIhmEdge := IhmTimeoutTon.ET;
HeartbeatIhmTimeout := IhmTimeoutTon.Q;
HeartbeatIhmOk := NOT HeartbeatIhmTimeout;
{endregion}

{region "§4 Clignotant PLC"}
// 💡 Clignotant PLC indépendant : information de vie pour l'IHM, jamais signal Signal Safety autonome.
PlcToggleTon(IN := NOT PlcToggleTon.Q, PT := PlcTogglePeriod);
IF PlcToggleTon.Q THEN
    TglHeartbeatPlc := NOT TglHeartbeatPlc;
END_IF;
{endregion}

IF NOT Enable THEN
    Banner.GlobalContextText     := '';
    Banner.SequenceProgressText  := '';
    Banner.SpecialConditionText  := '';
    Banner.OperatorActionText    := '';
    Banner.PositionM3Text        := '';
    Banner.AlarmBanner.HasAlarm  := FALSE;
    Banner.AlarmBanner.Text      := '';
    Banner.AlarmBanner.Index     := 0;
    Banner.AlarmBanner.Count     := 0;
    FOR i := 0 TO 49 DO
        Banner.AlarmBanner.AlarmArray[i] := '';
    END_FOR;
    TonAlarmBanner(IN := FALSE);
    TonBootInhibit(IN := FALSE);
    TofFaultLocalIo(IN := FALSE);
    TofFaultVh0800(IN := FALSE);
    TofFaultVh0808(IN := FALSE);
    TofFaultVh0008Er(IN := FALSE);
    TofFaultVh0008Er1(IN := FALSE);
    TofFaultCanBus(IN := FALSE);
    TofFaultJoy1(IN := FALSE);
    TofFaultEcatBus(IN := FALSE);
    TofFaultEncM1(IN := FALSE);
    TofFaultEncM2(IN := FALSE);
    TofFaultVarM3(IN := FALSE);
    RETURN;
END_IF;

// ⏱️ Garde au démarrage (inhibition 4s pendant init des bus et équipements)
TonBootInhibit(IN := Enable, PT := T#4s);

// 🌊 Filtrage anti-bagotement (TOF 1.5s sur perte de validité)
TofFaultLocalIo(IN := (NOT Network.InputModules.LocalDigitalIoOk) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultVh0800(IN := (NOT Network.InputModules.Vh0800EndOk) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultVh0808(IN := (NOT Network.InputModules.Vh0808EtpOk) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultVh0008Er(IN := (NOT Network.InputModules.Vh0008ErOk) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultVh0008Er1(IN := (NOT Network.InputModules.Vh0008Er1Ok) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultCanBus(IN := (NOT Network.BusCanOpen.Operational) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultJoy1(IN := (NOT Network.Joystick.Operational) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultEcatBus(IN := (NOT Network.BusEthercat.Operational) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultEncM1(IN := (NOT Network.EncoderM1.Operational) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultEncM2(IN := (NOT Network.EncoderM2.Operational) AND TonBootInhibit.Q, PT := T#1.5s);
TofFaultVarM3(IN := (NOT Network.VariateurM3.Operational) AND TonBootInhibit.Q, PT := T#1.5s);

LocalIoValid   := NOT TofFaultLocalIo.Q;
Vh0800Valid    := NOT TofFaultVh0800.Q;
Vh0808Valid    := NOT TofFaultVh0808.Q;
Vh0008ErValid  := NOT TofFaultVh0008Er.Q;
Vh0008Er1Valid := NOT TofFaultVh0008Er1.Q;
CanBusValid    := NOT TofFaultCanBus.Q;
Joy1Valid      := NOT TofFaultJoy1.Q;
EcatBusValid   := NOT TofFaultEcatBus.Q;
EncM1Valid     := NOT TofFaultEncM1.Q;
EncM2Valid     := NOT TofFaultEncM2.Q;
VarM3Valid     := NOT TofFaultVarM3.Q;

{region "§1 Contexte global"}
// ═══════════════════════════════════════════════════════════════
// 1. CONTEXTE GLOBAL — aucun numéro d'étape ici
// Format (AF-07 §5.1) : [RÉEL/SIMU] [MODE] [COUPLAGE]
// ═══════════════════════════════════════════════════════════════
IF SimulationModeActive THEN
    PrefixContext := '[SIMULATION] ';
ELSE
    PrefixContext := '[RÉEL] ';
END_IF;

CASE CurrentMode OF
    E_Mode.DISABLE:  ModeStr := '[DÉSACTIVÉ]';
    E_Mode.MAINT_N1: ModeStr := '[MAINT_N1]';
    E_Mode.MAINT_N2: ModeStr := '[MAINT_N2]';
    E_Mode.SEMI_AUTO: ModeStr := '[SEMI-AUTO]';
ELSE
    ModeStr := '[MODE INCONNU]';
END_CASE;

IF CurrentMode = E_Mode.SEMI_AUTO THEN
    CouplingStr := ' [CYCLE AUTO]';
ELSIF BothAxesCoupled THEN
    CouplingStr := ' [M1+M2 COUPLÉS]';
ELSIF WinchSelected = 1 THEN
    CouplingStr := ' [M1 SEUL]';
ELSIF WinchSelected = 2 THEN
    CouplingStr := ' [M2 SEUL]';
ELSE
    CouplingStr := ' [AUCUN AXE]';
END_IF;
Banner.GlobalContextText := CONCAT(CONCAT(PrefixContext, ModeStr), CouplingStr);
{endregion}

{region "§2 Progression"}
// ═══════════════════════════════════════════════════════════════
// 2. PROGRESSION — le numéro et l'étape restent exclusivement ici
// Format (AF-07 §5.1) : Macro: <Cycle> > Sous-cycle: <Étape>
// ═══════════════════════════════════════════════════════════════
// Guide homing machine : source unique = FB_CycleMachineHoming (1 texte par étape).
// Prioritaire tant que non valide (SEMI_AUTO est de toute façon interdit sans MachineHomed).
IF (MachineHomingStep > 0) AND (MachineHomingStep <> 60) THEN
    Banner.SequenceProgressText := CONCAT('Homing: ', MachineHomingInstruction);
ELSIF CurrentMode = E_Mode.SEMI_AUTO THEN
    // Détail de l'étape (FB_CycleSemiAuto.CycleStateStr) prioritaire ; label court en fallback.
    IF CycleStateStr <> '' THEN
        Banner.SequenceProgressText := CONCAT('Cycle: ', CycleStateStr);
    ELSE
        CASE CycleStep OF
            E_AutoCycleStep.AX0_REPOS: Banner.SequenceProgressText := 'Cycle: PRÉPARATION';
            E_AutoCycleStep.AX1_INIT: Banner.SequenceProgressText := 'Cycle: CONDITIONS INITIALES';
            E_AutoCycleStep.AX2_TRANSLATE_P1: Banner.SequenceProgressText := 'Cycle: TRANSLATION P1';
            E_AutoCycleStep.AX3_OPEN_BUCKET: Banner.SequenceProgressText := 'Cycle: OUVERTURE BENNE';
            E_AutoCycleStep.AX4_DESCEND_DIVING: Banner.SequenceProgressText := 'Cycle: PLONGÉE PALIER 4';
            E_AutoCycleStep.AX5_KOBOLD_INIT: Banner.SequenceProgressText := 'Cycle: INIT KOBOLD';
            E_AutoCycleStep.AX6_SEARCH_IMMERSION: Banner.SequenceProgressText := 'Cycle: RECHERCHE IMMERSION';
            E_AutoCycleStep.AX7_SEARCH_BOTTOM: Banner.SequenceProgressText := 'Cycle: RECHERCHE FOND';
            E_AutoCycleStep.AX8_BOTTOM_CONFIRMED: Banner.SequenceProgressText := 'Cycle: FOND CONFIRMÉ';
            E_AutoCycleStep.AX_DIVING_RETRY: Banner.SequenceProgressText := 'Cycle: REPRISE PLONGÉE';
            E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM: Banner.SequenceProgressText := 'Cycle: MONTEE SYNCHRONISEE - RETENDRE CABLES';
            E_AutoCycleStep.AX10_CLOSE_BUCKET: Banner.SequenceProgressText := 'Cycle: FERMETURE BENNE';
            E_AutoCycleStep.AX10_WAIT_ASCENT_START: Banner.SequenceProgressText := 'Cycle: STABILISATION AVANT MONTEE';
            E_AutoCycleStep.AX11_CTRL_ASCENT: Banner.SequenceProgressText := 'Cycle: MONTÉE CONTRÔLE';
            E_AutoCycleStep.AX12_LOADED_ASCENT: Banner.SequenceProgressText := 'Cycle: REMONTÉE CHARGÉE';
            E_AutoCycleStep.AX13_DRAIN_PAUSE: Banner.SequenceProgressText := 'Cycle: ÉGOUTTAGE';
            E_AutoCycleStep.AX14_TRANSLATE_DUMP: Banner.SequenceProgressText := 'Cycle: TRANSLATION TRÉMIE';
            E_AutoCycleStep.AX15A_DUMP_ARRIVE, E_AutoCycleStep.AX15B_DUMP_OPEN: Banner.SequenceProgressText := 'Cycle: VIDAGE BENNE';
            E_AutoCycleStep.AX15C_DUMP_REPOSITION: Banner.SequenceProgressText := 'Cycle: VIDAGE BENNE';
            E_AutoCycleStep.AX18_DONE_SYNC: Banner.SequenceProgressText := 'Cycle: TERMINÉ - ALLER P1';
            E_AutoCycleStep.AX_STAB: Banner.SequenceProgressText := 'Cycle: STABILISATION';
        ELSE
            Banner.SequenceProgressText := 'Cycle: ÉTAPE EN COURS';
        END_CASE;
    END_IF;
ELSIF CurrentMode = E_Mode.MAINT_N1 OR CurrentMode = E_Mode.MAINT_N2 THEN
    Banner.SequenceProgressText := 'Manuel: PILOTAGE DIRECT';
ELSE
    Banner.SequenceProgressText := 'Machine: ARRÊTÉE';
END_IF;
{endregion}

{region "§2bis Position M3"}
// État indépendant : ne participe pas aux arbitrages des quatre champs historiques
// ni au carrousel des défauts. Texte statut position M3 calculé par PRG_05 (T249-B) :
// jeton "at position" sur front capteur, sinon zone entre 2 capteurs (SensorsWord),
// + suffixe sens de déplacement. Niveau INFO, jamais alarme.
Banner.PositionM3Text := M3StatusText;
{endregion}

{region "§3 Condition spéciale"}
// ═══════════════════════════════════════════════════════════════
// 3. CONDITION SPÉCIALE — un seul indicateur bypass/dérogation
// Format (AF-07 §5.1) : ATTENTION: <Dérogation / Bridage / Alerte>
// 🧊 Warning → maintenu min (anti-clignotement), jamais critique.
// ⚠️ La simulation n'est PAS un bypass : elle n'apparaît que dans le
//    contexte global (champ 1), jamais ici.
// ═══════════════════════════════════════════════════════════════
AnyBypassActive := BypassGlobalActive
                OR BypassWinchM1Active
                OR BypassWinchM2Active
                OR BypassTranslation
                OR BypassSyncActive;
IF ModeChangePendingBlocked AND ModeChangeBlockReason <> '' THEN
    // Bascule de mode refusée : motif prioritaire (info opérateur, ex. "Chgt mode refuse : contacteur M1").
    SpecialConditionCandidate := ModeChangeBlockReason;
ELSIF CycleChecksInhibited THEN
    SpecialConditionCandidate := 'ESSAI CYCLE : CONTROLES INHIBES';
ELSIF AnyBypassActive THEN
    SpecialConditionCandidate := 'ATTENTION: Bypass actif';
ELSIF SyncDegradedActive THEN
    SpecialConditionCandidate := 'ATTENTION: Synchro bridée';
ELSIF LegalLimitReached THEN
    SpecialConditionCandidate := 'ATTENTION: Limite légale';
ELSIF M3AtTremieStable THEN
    // A la Tremie, le mode benne (WinchSel=2) reste dispo (exempte du verrou T249-A,
    // commit bb2bf240) -> priorite sur le message descente verrouillee ci-dessous, qui
    // etait le seul affiche a la Tremie et faisait croire a l'operateur que TOUT etait
    // bloque, y compris la benne (REX MES 2026-09-04).
    SpecialConditionCandidate := 'M3 a la Tremie : mode benne actif (ouverture/fermeture disponible)';
ELSIF WinchDescentLockedByM3 THEN
    // T249-A : verrou GENERAL en MAINT (pas seulement DumpAtTremie) — sans ce message
    // l'operateur ne comprend pas pourquoi la descente est refusee (REX MES 2026-09-04).
    SpecialConditionCandidate := 'Descente treuil verrouillee : chariot M3 pas a P1/Maintenance';
ELSE
    SpecialConditionCandidate := '';
END_IF;

AntiFlickSpecial(NewText := SpecialConditionCandidate, ForceInstant := FALSE, HoldTime := CST_BannerHoldTime);
Banner.SpecialConditionText := AntiFlickSpecial.Text;
{endregion}

{region "§4 Action opérateur"}
// ═══════════════════════════════════════════════════════════════
// 4. ACTION — cause fixe, sécurité d'abord, sans rotation
// Format (AF-07 §5.1) : [ORGANE] <Action physique> > <Fin>
// 🧊 Défauts (AU/puissance/SafeStop) + interlock DirectionBlocked
//    → affichés immédiatement (ForceInstant=TRUE) ; les autres états
//    → maintenus min (anti-clignotement).
// ═══════════════════════════════════════════════════════════════
IF CurrentMode = E_Mode.SEMI_AUTO THEN
    CurrentDirection := CycleRequestDirection;
ELSIF BothAxesCoupled THEN
    CurrentDirection := WinchBothMotionDirection;
ELSIF WinchSelected = 1 THEN
    CurrentDirection := M1LogicRequestDirection;
ELSIF WinchSelected = 2 THEN
    CurrentDirection := M2LogicRequestDirection;
ELSE
    CurrentDirection := 0;
END_IF;

DirectionBlocked := (CurrentDirection < 0 AND NOT DescendPermit)
                OR (CurrentDirection > 0 AND NOT AscentPermit);

// 🩹 Signaler la cause du dernier abandon de séquence AU (message cause+action),
// sans modifier le comportement de l'AU. Front descendant ArmingSeqStep (sequence en
// cours -> 0) = fin de sequence.
// 🐛 BUG A corrigé : l'ancien gating `NOT PowerContactorEngaged` supprimait le message
// d'abandon à l'étape 5 (PowerCutOff) car le contacteur venait d'être pulsé
// (PowerContactorEngaged=TRUE). On déclenche désormais sur la CAUSE (LastAbortCause <> 0),
// en excluant uniquement le SUCCÈS réel (séquence ayant atteint l'étape 6 de confirmation
// ET contacteur engagé au retour à IDLE) — un succès ne produit AUCUN message (AC4).
// Verrouillage : les causes SANS latch (CST_ABORT_POWER_CUTOFF, CST_ABORT_TIMEOUT_RESTORE_A/B)
// restauration) restent affichées jusqu'à Reset (ou nouvelle séquence) pour que
// l'opérateur voie l'échec. Les causes déjà latched (CST_ABORT_CHAIN_DROP/REDUNDANCY_A/B/
// TIMEOUT_CONTACTOR) et la coupe volontaire (CST_ABORT_CUT_IHM) ne sont pas verrouillées.
ArmingInProgress := (ArmingSeqStep <> 0);
LastAbortEdge(CLK := ArmingInProgress);
ResetEdge(CLK := Reset);
ArmStartEdge(CLK := ArmingInProgress);

// 🩹 Détection d'un SUCCÈS de séquence : la séquence a atteint l'étape 6 (confirmation).
// Ce drapeau est consommé par le test de LastAbortEdge ci-dessous AVANT d'être remis à
// zéro hors séquence (fin de bloc), pour distinguer un succès d'un abandon à l'étape 5.
IF ArmingSeqStep = 6 THEN
    SeqReachedConfirm := TRUE;
END_IF;

IF LastAbortEdge.Q AND (LastAbortCause <> 0) AND NOT (SeqReachedConfirm AND PowerContactorEngaged) THEN
    AbortMsgActive := TRUE;
    AbortMsgLatched := (LastAbortCause = INT_TO_WORD(CST_ABORT_POWER_CUTOFF)) OR (LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_A)) OR (LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_B));
    TonAbortHold(IN := FALSE);
END_IF;

// Effacement : Reset OU nouvelle séquence (évite le message périmé après réarmement réussi)
IF ResetEdge.Q OR ArmStartEdge.Q THEN
    AbortMsgActive := FALSE;
    AbortMsgLatched := FALSE;
    TonAbortHold(IN := FALSE);
END_IF;

// Remise à zéro du drapeau de confirmation hors séquence (après le test de LastAbortEdge
// ci-dessus, qui consomme sa valeur du scan précédent pour distinguer succès/abandon).
IF NOT ArmingInProgress THEN
    SeqReachedConfirm := FALSE;
END_IF;

// Maintien transitoire 5s UNIQUEMENT pour les causes non latched
IF AbortMsgActive AND NOT AbortMsgLatched THEN
    TonAbortHold(IN := TRUE, PT := CST_AbortHoldTime);
    IF TonAbortHold.Q THEN
        AbortMsgActive := FALSE;
        TonAbortHold(IN := FALSE);
    END_IF;
END_IF;
IF AbortMsgActive THEN
    IF LastAbortCause = INT_TO_WORD(CST_ABORT_CUT_IHM) THEN
        AbortMsgText := '[AU] Coupure volontaire IHM - relacher le bouton puis rearmer';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_CHAIN_DROP) THEN
        AbortMsgText := '[AU] Chute boucle urgence pendant test - relacher coup-de-poing puis rearmer';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_A) THEN
        AbortMsgText := '[AU] Chaine non remontee apres test A (200ms) - verifier boucle puis rearmer';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_RESTORE_B) THEN
        AbortMsgText := '[AU] Chaine non remontee apres test B (200ms) - verifier boucle puis rearmer';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_POWER_CUTOFF) THEN
        // 🩹 Décodage de la cause CST_ABORT_POWER_CUTOFF (PowerCutOff métier) en cause explicite
        // M1/M2/M3 + bit MecaA/MecaB/thermique, à partir des DUT Safety déjà en entrée.
        // Priorité : M3 (translation) puis M1 puis M2 ; MecaA > MecaB > thermique.
        IF TranslationSafety.ErrorMecaA THEN
            AbortMsgText := '[M3] MecaA (mouvement non commandé) - Reset puis réarmer';
        ELSIF TranslationSafety.ErrorMecaB THEN
            AbortMsgText := '[M3] MecaB (arrêt non confirmé) - Reset puis réarmer';
        ELSIF TranslationSafety.ErrorBrakeThermal THEN
            AbortMsgText := '[M3] Surchauffe frein - Reset puis réarmer';
        ELSIF WinchM1Safety.ErrorMecaA THEN
            AbortMsgText := '[M1] MecaA (mouvement non commandé) - Reset puis réarmer';
        ELSIF WinchM1Safety.ErrorMecaB THEN
            AbortMsgText := '[M1] MecaB (arrêt non confirmé) - Reset puis réarmer';
        ELSIF WinchM1Safety.ThermalFault THEN
            AbortMsgText := '[M1] Surchauffe moteur - Reset puis réarmer';
        ELSIF WinchM1Safety.ErrorBrakeThermal THEN
            AbortMsgText := '[M1] Surchauffe frein - Reset puis réarmer';
        ELSIF WinchM2Safety.ErrorMecaA THEN
            AbortMsgText := '[M2] MecaA (mouvement non commandé) - Reset puis réarmer';
        ELSIF WinchM2Safety.ErrorMecaB THEN
            AbortMsgText := '[M2] MecaB (arrêt non confirmé) - Reset puis réarmer';
        ELSIF WinchM2Safety.ThermalFault THEN
            AbortMsgText := '[M2] Surchauffe moteur - Reset puis réarmer';
        ELSIF WinchM2Safety.ErrorBrakeThermal THEN
            AbortMsgText := '[M2] Surchauffe frein - Reset puis réarmer';
        ELSE
            AbortMsgText := '[AU] Coupure securite metier active - lever la cause puis rearmer';
        END_IF;
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_REDUNDANCY_A) THEN
        AbortMsgText := '[AU] Defaut redondance canal A - verifier contacteur puis Reset';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_REDUNDANCY_B) THEN
        AbortMsgText := '[AU] Defaut redondance canal B - verifier contacteur puis Reset';
    ELSIF LastAbortCause = INT_TO_WORD(CST_ABORT_TIMEOUT_CONTACTOR) THEN
        AbortMsgText := '[AU] Contacteur non engage sous 2s - verifier puis rearmer';
    ELSE
        AbortMsgText := '[AU] Rearmement interrompu - verifier et rearmer';
    END_IF;
END_IF;

IF NOT EmergencyChainClosed THEN
    OperatorActionCandidate := '[PUPITRE] Boucle urgence ouverte - réarmer';
ELSIF NOT LocalIoValid OR NOT Vh0800Valid OR NOT Vh0808Valid OR NOT Vh0008ErValid OR NOT Vh0008Er1Valid THEN
    OperatorActionCandidate := '[IO] Défaut module E/S - vérifier alimentation/coupleur';
ELSIF NOT CanBusValid THEN
    OperatorActionCandidate := '[CAN] Défaut bus CANopen - vérifier câblage';
ELSIF NOT Joy1Valid THEN
    OperatorActionCandidate := '[CAN] Joystick non détecté - vérifier liaison';
ELSIF NOT EcatBusValid THEN
    OperatorActionCandidate := '[ECAT] Défaut bus EtherCAT - vérifier liaison';
ELSIF NOT EncM1Valid OR NOT EncM2Valid THEN
    OperatorActionCandidate := '[ECAT] Codeurs non détectés - vérifier liaison';
ELSIF NOT VarM3Valid THEN
    OperatorActionCandidate := '[ECAT] Variateur non détecté - vérifier liaison';
ELSIF AbortMsgActive THEN
    // 🩹 Cause du dernier abandon de séquence AU (message explicite cause+action).
    // 🐛 BUG B corrigé : placé AVANT PowerCutOffActiveAny pour que la cause racine
    // (dont CST_ABORT_POWER_CUTOFF décodée en M1/M2/M3 + MecaA/MecaB/thermique) prime sur
    // le message générique de coupure puissance. Placé aussi avant
    // RedundancyTestFailed/EmergencyArmingFailed/SafeStop pour que chaque cause montre
    // son message spécifique — le message d'abandon est la CAUSE RACINE (plus pertinente
    // que le SafeStop qui en est une conséquence) — il prime sur SafeStop/DirectionBlocked.
    OperatorActionCandidate := AbortMsgText;
ELSIF PowerCutOffActiveAny THEN
    OperatorActionCandidate := '[SÉCURITÉ] Coupure puissance active - acquitter défaut treuil/pont';
ELSIF RedundancyTestFailed THEN
    OperatorActionCandidate := '[AU] Défaut redondance contacteurs - réarmer (Reset)';
ELSIF EmergencyArmingFailed THEN
    OperatorActionCandidate := '[AU] Échec réarmement contacteur - réarmer';
ELSIF NOT PowerContactorEngaged THEN
    OperatorActionCandidate := '[PUPITRE] Réarmer AU et puissance';
ELSIF SafeStopActive THEN
    IF SyncContactorDiag.MismatchLevel >= 1 THEN
        OperatorActionCandidate := '[SYNC] Discordance contacteurs M1/M2 - Acquitter SafeStop';
    ELSE
        OperatorActionCandidate := '[PUPITRE] Acquitter SafeStop';
    END_IF;
ELSIF DirectionBlocked THEN
    IF CurrentDirection < 0 THEN
        IF WinchDescentLockedByM3 THEN
            // 🛡️ Descente verrouillée par position M3 (chariot pas à P1/Maintenance)
            OperatorActionCandidate := '[TREUIL] Descente interdite - Chariot M3 pas a P1/Maintenance';
        ELSIF LegalLimitReached THEN
            // 🛡️ Descente bloquée par limite légale atteinte
            OperatorActionCandidate := '[TREUIL] Descente interdite - Limite legale atteinte';
        ELSIF WinchM1Safety.CableLimitDescent OR WinchM2Safety.CableLimitDescent THEN
            // 🛡️ Descente bloquée par limite basse câble
            OperatorActionCandidate := '[TREUIL] Descente interdite - Limite basse cable';
        ELSIF WinchM1Safety.SlackCable OR WinchM2Safety.SlackCable THEN
            // 🛡️ Descente bloquée par détection mou de câble
            OperatorActionCandidate := '[TREUIL] Descente interdite - Mou de cable detecte';
        ELSIF WinchM1Safety.DescendPermit AND NOT WinchM2Safety.DescendPermit THEN
            // 🛡️ Descente bloquée spécifiquement par M2
            OperatorActionCandidate := '[TREUIL] Descente interdite - Treuil M2 (benne)';
        ELSIF WinchM2Safety.DescendPermit AND NOT WinchM1Safety.DescendPermit THEN
            // 🛡️ Descente bloquée spécifiquement par M1
            OperatorActionCandidate := '[TREUIL] Descente interdite - Treuil M1 (retenue)';
        ELSE
            OperatorActionCandidate := '[TREUIL] Descente interdite';
        END_IF;
    ELSIF TopLimitReached THEN
        // 🛡️ Montée bloquée par butée logicielle haute (agrégat M1/M2) — cause exposée par le safety.
        OperatorActionCandidate := '[TREUIL] Montée interdite - limite haute';
    ELSIF WinchM1Safety.ErrorMecaD OR WinchM2Safety.ErrorMecaD THEN
        // 🛡️ Montée bloquée par capteur haut (non-arrêt au capteur haut, MecaD) — cause exposée par le safety.
        OperatorActionCandidate := '[TREUIL] Montée interdite - capteur haut';
    ELSIF WinchM1Safety.AscentPermit AND NOT WinchM2Safety.AscentPermit THEN
        // 🛡️ Montée bloquée par treuil M2 (M1 autorise, M2 non) — cause exposée par le safety.
        OperatorActionCandidate := '[TREUIL] Montée interdite - treuil M2';
    ELSE
        OperatorActionCandidate := '[TREUIL] Montée interdite';
    END_IF;
ELSIF CurrentMode = E_Mode.SEMI_AUTO THEN
    // Guidance par étape du cycle (AF-07 §5.1) — ne masque jamais un défaut
    // (priorités AU/puissance/SafeStop/DirectionBlocked ci-dessus dominent).
    CASE CycleStep OF
        E_AutoCycleStep.AX0_REPOS:
            OperatorActionCandidate := '[IHM-JOY] Appuyer Start Cycle (ou homme-mort) pour initialiser';
        E_AutoCycleStep.AX1_INIT:
            IF CycleStateStr <> '' THEN
                OperatorActionCandidate := CONCAT('[INIT] ', CycleStateStr);
            ELSE
                OperatorActionCandidate := '[INIT] Verifier conditions initiales (referencement, FDC haut)';
            END_IF;
        E_AutoCycleStep.AX2_TRANSLATE_P1:
            OperatorActionCandidate := '[JOY] Pousser a droite : translation vers P1';
        E_AutoCycleStep.AX3_OPEN_BUCKET:
            OperatorActionCandidate := '[JOY] Pousser descente : ouverture benne jusqu au FDC';
        E_AutoCycleStep.AX4_DESCEND_DIVING:
            OperatorActionCandidate := '[JOY] Pousser descente : plongee palier 4';
        E_AutoCycleStep.AX5_KOBOLD_INIT:
            OperatorActionCandidate := '[JOY] Maintenir descente : init Kobold';
        E_AutoCycleStep.AX6_SEARCH_IMMERSION:
            OperatorActionCandidate := '[JOY] Maintenir descente : recherche immersion';
        E_AutoCycleStep.AX7_SEARCH_BOTTOM:
            OperatorActionCandidate := '[JOY] Maintenir descente : recherche fond (Kobold)';
        E_AutoCycleStep.AX8_BOTTOM_CONFIRMED:
            OperatorActionCandidate := '[JOY] Fond atteint : relacher puis tirer pour extraire';
        E_AutoCycleStep.AX_DIVING_RETRY:
            OperatorActionCandidate := '[JOY] Reprise plongee : remonter au FDC haut';
        E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM:
            OperatorActionCandidate := '[JOY] Tirer : montee synchronisee et retendre les cables';
        E_AutoCycleStep.AX10_CLOSE_BUCKET:
            OperatorActionCandidate := '[JOY] Tirer montee : fermeture de la benne';
        E_AutoCycleStep.AX11_CTRL_ASCENT:
            OperatorActionCandidate := '[JOY] Tirer montee : remontee de controle';
        E_AutoCycleStep.AX12_LOADED_ASCENT:
            OperatorActionCandidate := '[JOY] Tirer montee : remontee en charge';
        E_AutoCycleStep.AX13_DRAIN_PAUSE:
            OperatorActionCandidate := '[CYCLE] Egouttage en cours (attendre tempo ou bouton Passer)';
        E_AutoCycleStep.AX14_TRANSLATE_DUMP:
            OperatorActionCandidate := '[JOY] Pousser a gauche : translation vers tremie';
        E_AutoCycleStep.AX15A_DUMP_ARRIVE, E_AutoCycleStep.AX15B_DUMP_OPEN:
            OperatorActionCandidate := '[JOY] Pousser descente : vidage benne a la tremie';
        E_AutoCycleStep.AX15C_DUMP_REPOSITION:
            OperatorActionCandidate := '[JOY] Pousser descente : vidage benne a la tremie';
        E_AutoCycleStep.AX18_DONE_SYNC:
            OperatorActionCandidate := '[JOY] Cycle termine : pousser a droite vers P1';
        E_AutoCycleStep.AX_STAB:
            // Libellé de l'étape d'origine du défaut (CycleStepAtError).
            CASE CycleStepAtError OF
                E_AutoCycleStep.AX0_REPOS: StepAtErrorStr := 'X0 (preparation)';
                E_AutoCycleStep.AX1_INIT: StepAtErrorStr := 'X1 (referencement)';
                E_AutoCycleStep.AX2_TRANSLATE_P1: StepAtErrorStr := 'X2 (selection position)';
                E_AutoCycleStep.AX3_OPEN_BUCKET: StepAtErrorStr := 'X3 (ouverture benne)';
                E_AutoCycleStep.AX4_DESCEND_DIVING: StepAtErrorStr := 'AX4 (plongee palier 4)';
                E_AutoCycleStep.AX5_KOBOLD_INIT: StepAtErrorStr := 'AX5 (init Kobold)';
                E_AutoCycleStep.AX6_SEARCH_IMMERSION: StepAtErrorStr := 'AX6 (recherche immersion)';
                E_AutoCycleStep.AX7_SEARCH_BOTTOM: StepAtErrorStr := 'AX7 (recherche fond)';
                E_AutoCycleStep.AX8_BOTTOM_CONFIRMED: StepAtErrorStr := 'AX8 (fond confirme)';
                E_AutoCycleStep.AX_DIVING_RETRY: StepAtErrorStr := 'AX_DIVING_RETRY (reprise plongee)';
                E_AutoCycleStep.AX9_RAISE_OFF_BOTTOM: StepAtErrorStr := 'AX9 (montee sync - retendre cables)';
                E_AutoCycleStep.AX10_CLOSE_BUCKET: StepAtErrorStr := 'AX10 (fermeture benne)';
                E_AutoCycleStep.AX10_WAIT_ASCENT_START: StepAtErrorStr := 'AX10b (stabilisation avant montee)';
                E_AutoCycleStep.AX11_CTRL_ASCENT: StepAtErrorStr := 'AX11 (remontee controle)';
                E_AutoCycleStep.AX12_LOADED_ASCENT: StepAtErrorStr := 'AX12 (remontee chargee)';
                E_AutoCycleStep.AX13_DRAIN_PAUSE: StepAtErrorStr := 'AX13 (egouttage)';
                E_AutoCycleStep.AX14_TRANSLATE_DUMP: StepAtErrorStr := 'AX14 (translation tremie)';
                E_AutoCycleStep.AX15A_DUMP_ARRIVE: StepAtErrorStr := 'AX15a (arrivee tremie)';
                E_AutoCycleStep.AX15B_DUMP_OPEN: StepAtErrorStr := 'AX15b (vidage benne)';
                E_AutoCycleStep.AX15C_DUMP_REPOSITION: StepAtErrorStr := 'AX15c (repositionnement)';
                E_AutoCycleStep.AX18_DONE_SYNC: StepAtErrorStr := 'AX18 (cycle termine)';
                E_AutoCycleStep.AX_STAB: StepAtErrorStr := 'AX_STAB (stabilisation)';
                ELSE
                    StepAtErrorStr := '?';
            END_CASE;
            // Décodage priorisé : l'opérateur voit la grandeur fautive, pas un masque.
            // Bits cycle : 0 limite, 1 synchro, 2 vitesse, 3 IHM, 4 tempo,
            // 5 stabilisation, 6 position, 7 FDC haut, 8/9 paliers, 10 arrêt.
            IF (CycleErrorId AND 16#0001) <> 0 THEN
                CycleFaultCauseStr := 'limite legale de profondeur atteinte';
            ELSIF (CycleErrorId AND 16#0002) <> 0 THEN
                CycleFaultCauseStr := 'synchronisme M1/M2 bloquant';
            ELSIF (CycleErrorId AND 16#0004) <> 0 THEN
                CycleFaultCauseStr := 'ecart vitesse M1/M2 confirme';
            ELSIF (CycleErrorId AND 16#0008) <> 0 THEN
                CycleFaultCauseStr := 'communication IHM perdue';
            ELSIF (CycleErrorId AND 16#0010) <> 0 THEN
                CycleFaultCauseStr := 'tempo maximale etape depassee';
            ELSIF (CycleErrorId AND 16#0020) <> 0 THEN
                CycleFaultCauseStr := 'stabilisation remontee hors tolerance';
            ELSIF (CycleErrorId AND 16#0040) <> 0 THEN
                CycleFaultCauseStr := 'ecart position M1/M2 > 1,5 m (anti-telescopage)';
            ELSIF (CycleErrorId AND 16#0080) <> 0 THEN
                CycleFaultCauseStr := 'M1/M2 hors FDC haut pendant translation P1';
            ELSIF (CycleErrorId AND 16#0100) <> 0 THEN
                CycleFaultCauseStr := 'palier 5 interdit sur M1 ou M2 pendant plongee';
            ELSIF (CycleErrorId AND 16#0200) <> 0 THEN
                CycleFaultCauseStr := 'palier 4 non confirme sur M1 ou M2 en recherche Kobold';
            ELSIF (CycleErrorId AND 16#0400) <> 0 THEN
                CycleFaultCauseStr := 'arret mecanique M1/M2 non confirme avant plongee';
            ELSE
                CycleFaultCauseStr := CONCAT('cause cycle inconnue #', WORD_TO_STRING(CycleErrorId));
            END_IF;
            OperatorActionCandidate := CONCAT('[CYCLE] Defaut a ', CONCAT(StepAtErrorStr,
                                         CONCAT(' : ', CONCAT(CycleFaultCauseStr,
                                         '). Choisir Reprendre ou Abandonner.'))));
        ELSE
            OperatorActionCandidate := '[CYCLE] Cycle en cours...';
    END_CASE;
ELSIF DiveActive AND CurrentDirection < 0 THEN
    OperatorActionCandidate := '[TREUIL] Attendre fin du Dive';
ELSIF NOT BucketIsOpen AND CurrentDirection < 0 THEN
    OperatorActionCandidate := '[BENNE] Ouvrir la benne';
ELSIF TopLimitReached AND CurrentDirection > 0 THEN
    OperatorActionCandidate := '[TREUIL] Limite haute';
ELSIF NOT BucketIsClosed AND CurrentDirection > 0 THEN
    // Sécurité : benne mal fermée (branche/caillou) → montee bridee palier 1 pour eviter un choc
    // si la benne se refermait d'un coup en montant vite.
    OperatorActionCandidate := '[BENNE] Benne non fermee - montee bridee palier 1 (securite)';
ELSIF NOT DeadmanArmed THEN
    OperatorActionCandidate := '[JOYSTICK] Appuyer homme-mort au neutre';
ELSIF CurrentMode = E_Mode.DISABLE THEN
    OperatorActionCandidate := '[IHM] Sélectionner un mode';
ELSIF JoystickAtNeutral THEN
    OperatorActionCandidate := '[JOYSTICK] Armé - actionner axe';
ELSE
    OperatorActionCandidate := '[JOYSTICK] Déplacement en cours';
END_IF;

// Interlock = mouvement demandé mais permit absent : c'est une cause
// sécurité (blocage de mouvement) → affichage IMMÉDIAT, comme un défaut.
PowerOrChainFault := (NOT EmergencyChainClosed OR NOT PowerContactorEngaged OR PowerCutOffActiveAny);
HardwareModuleOrBusFault := (NOT LocalIoValid OR NOT Vh0800Valid OR NOT Vh0808Valid OR NOT Vh0008ErValid OR NOT Vh0008Er1Valid OR NOT CanBusValid OR NOT Joy1Valid OR NOT EcatBusValid OR NOT EncM1Valid OR NOT EncM2Valid OR NOT VarM3Valid);
CriticalActionActive := (PowerOrChainFault OR HardwareModuleOrBusFault OR SafeStopActive OR DirectionBlocked);

AntiFlickOperator(NewText := OperatorActionCandidate, ForceInstant := CriticalActionActive, HoldTime := CST_BannerHoldTime);
Banner.OperatorActionText := AntiFlickOperator.Text;
{endregion}

{region "§5 Bandeau alarme"}
// ═══════════════════════════════════════════════════════════════
// 5. BANDEAU D'ALARME — carrousel des défauts actifs (index n/N)
// Format (AF-07 §6) : [ORGANE] raison_brève. Un défaut à la fois,
// rotation 1→2→…→N→1, maintien AlarmHoldTime par message.
// 🧊 Distinct des 4 champs ci-dessus (AF-07 §5.2) : ce carrousel est
//    le SEUL endroit du bandeau qui publie Error/ErrorId (alarmes).
// ═══════════════════════════════════════════════════════════════
AlarmCount := 0;

// 5.0 Collecte — Défauts matériels parents (priorité absolue carrousel)
IF NOT LocalIoValid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[IO] Defaut module Local IO (DI8/DO8)'; AlarmCount := AlarmCount + 1;
END_IF;
IF NOT Vh0800Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[IO] Defaut module VH0800END (DI8)'; AlarmCount := AlarmCount + 1;
END_IF;
IF NOT Vh0808Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[IO] Defaut module VH0808ETP (DI8/DO8)'; AlarmCount := AlarmCount + 1;
END_IF;
IF NOT Vh0008ErValid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[IO] Defaut module VH0008ER (DO8 Relais)'; AlarmCount := AlarmCount + 1;
END_IF;
IF NOT Vh0008Er1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[IO] Defaut module VH0008ER_1 (DO8 Relais)'; AlarmCount := AlarmCount + 1;
END_IF;
IF NOT CanBusValid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CAN] Defaut bus CANopen'; AlarmCount := AlarmCount + 1;
END_IF;
IF CanBusValid AND NOT Joy1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CAN] Joystick JOY1 non detecte'; AlarmCount := AlarmCount + 1;
END_IF;
IF NOT EcatBusValid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[ECAT] Defaut bus EtherCAT'; AlarmCount := AlarmCount + 1;
END_IF;
IF EcatBusValid AND NOT EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] Codeur absolu COD1 non detecte (ECAT)'; AlarmCount := AlarmCount + 1;
END_IF;
IF EcatBusValid AND NOT EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M2] Codeur absolu COD2 non detecte (ECAT)'; AlarmCount := AlarmCount + 1;
END_IF;
IF EcatBusValid AND NOT VarM3Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] Variateur AC600 non detecte (ECAT)'; AlarmCount := AlarmCount + 1;
END_IF;

// 5a. Collecte — treuil M1 (ST_SafetyWinch, bits ErrorId décodés)
// 🧊 Tri bloquant/warning (AF-07 §6, décision 2026-09-01) : seuls les défauts
//    BLOQUANTS (SafeStop/PowerCutOff/interlock) sont publiés. Les warnings non
//    bloquants (mou de câble, surchauffe moteur/frein, limites basse/haute) sont
//    EXCLUS du carrousel — ils restent visibles via OperatorActionText/SpecialCondition.
IF WinchM1Safety.ErrorOperatorComm AND Joy1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:01 - perte com operateur'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorEncoder AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:02 - perte codeur'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorPhaseRotation AND Vh0800Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:05 - rotation phases'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorMecaA AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:08 - MecaA - deplacement sans commande (vitesse/derive)'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorMecaB AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:09 - MecaB - arret non confirme apres stop'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorMecaC AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:10 - MecaC - glissement pendant benne figee'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorMecaD AND LocalIoValid AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:12 - MecaD - non-arret au capteur haut'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorMecaE AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:13 - MecaE - ecart synchro M1/M2 critique'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorOppositeDir AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:15 - sens oppose'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorNoMovement AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] ErrorID:16 - discordance commande/retour/mouvement'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM1Safety.ErrorOverspeed AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M1] Survitesse treuil detectee (SafeStop)'; AlarmCount := AlarmCount + 1;
END_IF;

// 5b. Collecte — treuil M2 (mêmes bits que M1, tri bloquant/warning identique)
IF WinchM2Safety.ErrorOperatorComm AND Joy1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M2] ErrorID:01 - perte com operateur'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM2Safety.ErrorEncoder AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M2] ErrorID:02 - perte codeur'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM2Safety.ErrorPhaseRotation AND Vh0800Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M2] ErrorID:05 - rotation phases'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM2Safety.ErrorMecaA AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M2] ErrorID:08 - MecaA - deplacement sans commande (vitesse/derive)'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM2Safety.ErrorMecaB AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M2] ErrorID:09 - MecaB - arret non confirme apres stop'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM2Safety.ErrorMecaC AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M2] ErrorID:10 - MecaC - glissement pendant benne figee'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM2Safety.ErrorMecaD AND LocalIoValid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M2] ErrorID:12 - MecaD - non-arret au capteur haut'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM2Safety.ErrorMecaE AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M2] ErrorID:13 - MecaE - ecart synchro M1/M2 critique'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM2Safety.ErrorOppositeDir AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M2] ErrorID:15 - sens oppose'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM2Safety.ErrorNoMovement AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M2] ErrorID:16 - discordance commande/retour/mouvement'; AlarmCount := AlarmCount + 1;
END_IF;
IF WinchM2Safety.ErrorOverspeed AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M2] Survitesse treuil detectee (SafeStop)'; AlarmCount := AlarmCount + 1;
END_IF;

// 5c. Collecte — translation M3 (ST_SafetyTranslation, tri bloquant/warning identique)
IF TranslationSafety.ErrorOperatorComm AND Joy1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] ErrorID:01 - perte com operateur'; AlarmCount := AlarmCount + 1;
END_IF;
IF TranslationSafety.ErrorDriveComm AND VarM3Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] ErrorID:02 - perte EtherCAT'; AlarmCount := AlarmCount + 1;
END_IF;
IF TranslationSafety.ErrorPhaseRotation AND Vh0800Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] ErrorID:03 - rotation phases'; AlarmCount := AlarmCount + 1;
END_IF;
IF TranslationSafety.ErrorMecaB AND VarM3Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] ErrorID:05 - MecaB - arret non confirme apres stop'; AlarmCount := AlarmCount + 1;
END_IF;
IF TranslationSafety.ErrorMecaA AND VarM3Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] ErrorID:06 - MecaA - deplacement sans commande'; AlarmCount := AlarmCount + 1;
END_IF;
IF TranslationSafety.ErrorLimitSwitch AND Vh0808Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] ErrorID:07 - butee extreme'; AlarmCount := AlarmCount + 1;
END_IF;
IF TranslationSafety.ErrorSensorIncoherent AND Vh0808Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] ErrorID:08 - capteurs incoherents'; AlarmCount := AlarmCount + 1;
END_IF;
// 5c-bis. Defauts MOUVEMENT M3 (FB_Translation.Fault) — distincts des defauts SAFETY
//    ci-dessus. Ils n'avaient AUCUN chemin vers le carrousel d'alarmes (regression MES
//    2026-09-04 : "M3 chariot fault" invisible). Bits FB_FaultCore : 0=frein, 3=variateur
//    AC600 (latching), 6=limite extreme. + barriere finale (frein/redemarrage).
IF ((TranslationMotionErrorId AND 16#0001) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] Defaut sequence / retour frein translation'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((TranslationMotionErrorId AND 16#0008) <> 16#0000) AND VarM3Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] Defaut variateur translation AC600'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((TranslationMotionErrorId AND 16#0040) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] Limite extreme translation atteinte'; AlarmCount := AlarmCount + 1;
END_IF;
IF (TranslationFinalInterlockErrorId <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[M3] Barriere finale translation (frein / redemarrage) - Reset'; AlarmCount := AlarmCount + 1;
END_IF;

// 5d. Collecte — benne (FB_Bucket.ErrorId, bits décodés)
//    Mapping = index cause FB_Bucket (FB_FaultCore : bit i = cause i) :
//    bit0 config géométrie · bit1 écart max · bit2 timeout · bit3 glissement M1 · bit4 codeurs non référencés
IF ((BucketErrorId AND 16#0001) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[BENNE] ErrorID:01 - configuration geometrie invalide'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((BucketErrorId AND 16#0002) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[BENNE] ErrorID:02 - depassement ecart max autorise'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((BucketErrorId AND 16#0004) <> 16#0000) AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[BENNE] ErrorID:03 - timeout commande deplacement'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((BucketErrorId AND 16#0008) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[BENNE] ErrorID:04 - glissement treuil M1'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((BucketErrorId AND 16#0010) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[BENNE] ErrorID:05 - codeurs treuils non references'; AlarmCount := AlarmCount + 1;
END_IF;

// 5e. Collecte — synchro M1/M2 (FB_WinchSync.ErrorId)
IF ((SyncErrorId AND 16#0001) <> 16#0000) AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[SYNC] ErrorID:01 - ecart M1/M2'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((SyncErrorId AND 16#0002) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[SYNC] ErrorID:02 - incoherence commande'; AlarmCount := AlarmCount + 1;
END_IF;
// Discordance contacteurs M1/M2 decodee (FB_SyncContactor PRG_06 §2quinquies) : quel contacteur + niveau.
IF (SyncContactorDiag.MismatchLevel >= 1) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    IF    SyncContactorDiag.RelayFwdMismatch THEN BannerSyncContactorWhich := 'relais montee';
    ELSIF SyncContactorDiag.RelayRevMismatch THEN BannerSyncContactorWhich := 'relais descente';
    ELSIF SyncContactorDiag.Step1Mismatch   THEN BannerSyncContactorWhich := 'palier 1';
    ELSIF SyncContactorDiag.Step2Mismatch   THEN BannerSyncContactorWhich := 'palier 2';
    ELSIF SyncContactorDiag.Step3Mismatch   THEN BannerSyncContactorWhich := 'palier 3';
    ELSIF SyncContactorDiag.Step4Mismatch   THEN BannerSyncContactorWhich := 'palier 4';
    ELSE  BannerSyncContactorWhich := '';
    END_IF;
    IF SyncContactorDiag.MismatchLevel >= 2 THEN
        AlarmArray[AlarmCount] := CONCAT('[SYNC] discordance M1/M2 persistante -> coupure : ', BannerSyncContactorWhich);
    ELSE
        AlarmArray[AlarmCount] := CONCAT('[SYNC] discordance contacteurs M1/M2 -> arret : ', BannerSyncContactorWhich);
    END_IF;
    AlarmCount := AlarmCount + 1;
END_IF;

// 5f. Collecte — plongée / extraction (FB_DiveSearch / FB_ExtractionAssist)
IF ((DiveErrorId AND 16#0001) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:01 - timeout immersion'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((DiveErrorId AND 16#0002) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:02 - timeout fond'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((DiveErrorId AND 16#0004) <> 16#0000) AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:03 - limite basse atteinte'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((DiveErrorId AND 16#0008) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:04 - contact fond perdu'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((DiveErrorId AND 16#0010) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:05 - perte tension cable'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((DiveErrorId AND 16#0020) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:06 - anomalie vitesse'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((DiveErrorId AND 16#0040) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[DIVE] ErrorID:07 - config invalide'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((ExtractionErrorId AND 16#0001) <> 16#0000) AND LocalIoValid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[EXTRACTION] ErrorID:01 - fond'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((ExtractionErrorId AND 16#0002) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[EXTRACTION] ErrorID:02 - fermeture'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((ExtractionErrorId AND 16#0004) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[EXTRACTION] ErrorID:03 - controle'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((ExtractionErrorId AND 16#0008) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[EXTRACTION] ErrorID:04 - config'; AlarmCount := AlarmCount + 1;
END_IF;

// 5g. Collecte — AU / armement (FB_Safety_EmergencyManagement.Diag.ErrorId)
IF ((EmergencyErrorId AND 16#0001) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[AU] ErrorID:01 - redondance contacteurs'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((EmergencyErrorId AND 16#0002) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[AU] ErrorID:02 - echec confirmation armement'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((EmergencyErrorId AND 16#0008) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[AU] ErrorID:04 - echec autotest demarrage'; AlarmCount := AlarmCount + 1;
END_IF;

// 5h. Collecte — cycle semi-auto (FB_CycleSemiAuto.ErrorId)
IF ((CycleErrorId AND 16#0001) <> 16#0000) AND EncM1Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CYCLE] ErrorID:01 - limite legale atteinte'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((CycleErrorId AND 16#0002) <> 16#0000) AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CYCLE] ErrorID:02 - defaut synchro treuils'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((CycleErrorId AND 16#0008) <> 16#0000) AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CYCLE] ErrorID:04 - ecart codeurs remontee'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((CycleErrorId AND 16#0010) <> 16#0000) AND EncM1Valid AND EncM2Valid AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CYCLE] ErrorID:05 - ecart vitesse confirme'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((CycleErrorId AND 16#0020) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CYCLE] ErrorID:06 - perte communication IHM'; AlarmCount := AlarmCount + 1;
END_IF;
IF ((CycleErrorId AND 16#0040) <> 16#0000) AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[CYCLE] ErrorID:07 - timeout etape'; AlarmCount := AlarmCount + 1;
END_IF;

// 5i. Collecte [HISTO] — défauts latched passés (LatchedId AND NOT ErrorId)
// 🕘 Marqueur [HISTO] (AF-07 §6, décision 2026-09-01) : un défaut laté dont la cause a
//    disparu (bit LatchedId=1 ET bit ErrorId=0) reste affiché préfixé [HISTO] tant qu'il
//    n'est pas acquitté (Reset). M1/M2/M3 uniquement (vue latched exposée dans les DUT
//    safety). Les warnings (mou de câble, surchauffe) sont inclus ici : ce sont des défauts
//    passés à acquitter, distincts du carrousel actif (bloquants seuls).
HistoM1 := WinchM1Safety.LatchedId AND (NOT WinchM1Safety.ErrorId);
HistoM2 := WinchM2Safety.LatchedId AND (NOT WinchM2Safety.ErrorId);
HistoM3 := TranslationSafety.LatchedId AND (NOT TranslationSafety.ErrorId);

// ── M1 [HISTO] ──
IF (HistoM1 AND 16#0001) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:01 - perte com operateur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0002) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:02 - perte codeur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0004) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:03 - surchauffe moteur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0008) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:04 - mou de cable'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0010) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:05 - rotation phases'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0080) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:08 - MecaA - deplacement sans commande (vitesse/derive)'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0100) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:09 - MecaB - arret non confirme apres stop'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0200) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:10 - MecaC - glissement pendant benne figee'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0400) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:11 - surchauffe frein'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#0800) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:12 - MecaD - non-arret au capteur haut'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#1000) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:13 - MecaE - ecart synchro M1/M2 critique'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#4000) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:15 - sens oppose'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM1 AND 16#8000) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M1] ErrorID:16 - absence mouvement'; AlarmCount := AlarmCount + 1;
END_IF;

// ── M2 [HISTO] ──
IF (HistoM2 AND 16#0001) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:01 - perte com operateur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0002) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:02 - perte codeur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0004) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:03 - surchauffe moteur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0008) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:04 - mou de cable'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0010) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:05 - rotation phases'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0080) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:08 - MecaA - deplacement sans commande (vitesse/derive)'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0100) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:09 - MecaB - arret non confirme apres stop'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0200) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:10 - MecaC - glissement pendant benne figee'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0400) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:11 - surchauffe frein'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#0800) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:12 - MecaD - non-arret au capteur haut'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#1000) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:13 - MecaE - ecart synchro M1/M2 critique'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#4000) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:15 - sens oppose'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM2 AND 16#8000) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M2] ErrorID:16 - absence mouvement'; AlarmCount := AlarmCount + 1;
END_IF;

// ── M3 [HISTO] ──
IF (HistoM3 AND 16#0001) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:01 - perte com operateur'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0002) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:02 - perte EtherCAT'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0004) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:03 - rotation phases'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0008) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:04 - surchauffe frein'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0010) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:05 - MecaB - arret non confirme apres stop'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0020) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:06 - MecaA - deplacement sans commande'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0040) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:07 - butee extreme'; AlarmCount := AlarmCount + 1;
END_IF;
IF (HistoM3 AND 16#0080) <> 16#0000 AND (AlarmCount < CST_NbMaxAlarmes) THEN
    AlarmArray[AlarmCount] := '[HISTO] [M3] ErrorID:08 - capteurs incoherents'; AlarmCount := AlarmCount + 1;
END_IF;

// 5j. Rotation carrousel — un message à la fois, maintien AlarmHoldTime
// Publication du tableau complet instantane dans le DUT IHM
FOR i := AlarmCount TO (CST_NbMaxAlarmes - 1) DO
    AlarmArray[i] := '';
END_FOR;
Banner.AlarmBanner.AlarmArray := AlarmArray;

IF AlarmCount = 0 THEN
    AlarmIndex := 0;
    Banner.AlarmBanner.HasAlarm := FALSE;
    Banner.AlarmBanner.Text  := '';
    Banner.AlarmBanner.Index := 0;
    Banner.AlarmBanner.Count := 0;
    TonAlarmBanner(IN := FALSE);
ELSE
    // Index reborné si le nombre de messages a diminué depuis le dernier scan.
    IF AlarmIndex >= AlarmCount THEN
        AlarmIndex := 0;
    END_IF;
    Banner.AlarmBanner.HasAlarm := TRUE;
    TonAlarmBanner(IN := TRUE, PT := AlarmHoldTime);
    IF TonAlarmBanner.Q THEN
        AlarmIndex := (AlarmIndex + 1) MOD AlarmCount;
        TonAlarmBanner(IN := FALSE);
    END_IF;
    // Index n/N prefixe directement dans le texte (ex. '1/2 [M1] perte codeur'),
    // en plus des champs Index/Count numeriques pour un usage IHM programmatique.
    Banner.AlarmBanner.Text := CONCAT(INT_TO_STRING(AlarmIndex + 1),
                                CONCAT('/',
                                CONCAT(INT_TO_STRING(AlarmCount),
                                CONCAT(' ', AlarmArray[AlarmIndex]))));
    Banner.AlarmBanner.Index := AlarmIndex + 1;
    Banner.AlarmBanner.Count := AlarmCount;
END_IF;
{endregion}

IF Hmi <> Prev THEN
    RetainVal := Hmi;
ELSE
    Hmi := RetainVal;
END_IF;
Prev := Hmi;

{region "§1 Reset et qualification"}
CycleTime(DefaultValueS := 0.010); ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN Data.DeltaStartDelay_Ms:=0; Data.DeltaBrakeReleaseTime_Ms:=0; Data.DeltaBrakeApplyTime_Ms:=0; Data.DeltaStopDistance_Mm:=0; Data.DeltaStopTime_Ms:=0; Data.MaxSyncDeviation_M:=0.0; END_IF;
Comparable := M1CommandActive AND M2CommandActive AND (M1Direction = M2Direction) AND (M1Direction <> 0);
CommandTon(IN := Comparable, PT := UDINT_TO_TIME(Config.MinimumCommandTime_Ms));
Qualified := CommandTon.Q AND (M1Speed_Mps >= Config.MinimumSpeed_Mps) AND (M2Speed_Mps >= Config.MinimumSpeed_Mps);
MotionTimer(IN := Comparable, PT := T#1h);
StopTimer(IN := Stopping, PT := T#1h);
IF NOT Comparable THEN StartCapturedM1:=FALSE; StartCapturedM2:=FALSE; ReleaseMsM1:=0; ReleaseMsM2:=0; ApplyMsM1:=0; ApplyMsM2:=0; END_IF;
IF Comparable AND (M1Speed_Mps >= Config.MinimumSpeed_Mps) AND NOT StartCapturedM1 THEN StartMsM1:=TIME_TO_UDINT(MotionTimer.ET); StartCapturedM1:=TRUE; END_IF;
IF Comparable AND (M2Speed_Mps >= Config.MinimumSpeed_Mps) AND NOT StartCapturedM2 THEN StartMsM2:=TIME_TO_UDINT(MotionTimer.ET); StartCapturedM2:=TRUE; END_IF;
{endregion}

{region "§2 Mesure symétrie"}
IF Qualified THEN
    IF M1BrakeCmd AND M1BrakeApplied THEN ReleaseMsM1 := ReleaseMsM1 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF M2BrakeCmd AND M2BrakeApplied THEN ReleaseMsM2 := ReleaseMsM2 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF NOT M1BrakeCmd AND NOT M1BrakeApplied THEN ApplyMsM1 := ApplyMsM1 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF NOT M2BrakeCmd AND NOT M2BrakeApplied THEN ApplyMsM2 := ApplyMsM2 + REAL_TO_UDINT(CycleTime.CycleTimeS * 1000.0); END_IF;
    IF SyncDeviation_M > Data.MaxSyncDeviation_M THEN Data.MaxSyncDeviation_M := SyncDeviation_M; END_IF;
END_IF;
IF PreviousQualified AND NOT Comparable THEN Stopping:=TRUE; StopCapturedM1:=FALSE; StopCapturedM2:=FALSE; StopStartM1_M:=M1Position_M; StopStartM2_M:=M2Position_M; END_IF;
IF Stopping THEN
    IF (M1Speed_Mps < Config.MinimumSpeed_Mps) AND NOT StopCapturedM1 THEN StopMsM1:=TIME_TO_UDINT(StopTimer.ET); StopCapturedM1:=TRUE; END_IF;
    IF (M2Speed_Mps < Config.MinimumSpeed_Mps) AND NOT StopCapturedM2 THEN StopMsM2:=TIME_TO_UDINT(StopTimer.ET); StopCapturedM2:=TRUE; END_IF;
    IF StopCapturedM1 AND StopCapturedM2 THEN
        Data.DeltaStartDelay_Ms := DINT_TO_UDINT(ABS(UDINT_TO_DINT(StartMsM1) - UDINT_TO_DINT(StartMsM2)));
        Data.DeltaBrakeReleaseTime_Ms := DINT_TO_UDINT(ABS(UDINT_TO_DINT(ReleaseMsM1) - UDINT_TO_DINT(ReleaseMsM2)));
        Data.DeltaBrakeApplyTime_Ms := DINT_TO_UDINT(ABS(UDINT_TO_DINT(ApplyMsM1) - UDINT_TO_DINT(ApplyMsM2)));
        Data.DeltaStopDistance_Mm := REAL_TO_UDINT(ABS(ABS(M1Position_M - StopStartM1_M) - ABS(M2Position_M - StopStartM2_M)) * 1000.0);
        Data.DeltaStopTime_Ms := DINT_TO_UDINT(ABS(UDINT_TO_DINT(StopMsM1) - UDINT_TO_DINT(StopMsM2))); Stopping := FALSE; SymmetryValid := TRUE;
    END_IF;
END_IF;
{endregion}

{region "§3 Sortie"}
SymmetryOk := SymmetryValid AND (Data.DeltaStartDelay_Ms<=Config.DeltaStartDelay_Ms) AND (Data.DeltaBrakeReleaseTime_Ms<=Config.DeltaBrakeReleaseTime_Ms) AND (Data.DeltaBrakeApplyTime_Ms<=Config.DeltaBrakeApplyTime_Ms) AND (Data.DeltaStopDistance_Mm<=Config.DeltaStopDistance_Mm) AND (Data.DeltaStopTime_Ms<=Config.DeltaStopTime_Ms);
PreviousQualified := Qualified;
{endregion}

{region "§1 Reset (front, toujours effectif)"}
// Front Reset : efface tous les latches. Jamais conditionné, agit même Enable=FALSE (§9).
Ready := Enable;
ResetEdge(CLK := Reset);
IF ResetEdge.Q THEN
    FOR i := 0 TO 15 DO Latch[i] := FALSE; END_FOR;
END_IF;
{endregion}

{region "§2 Vue LIVE — Error / ErrorId"}
// Bitfield des causes présentes MAINTENANT. Retombe seule à 0 quand les causes disparaissent.
// Non évaluée si Enable=FALSE (pas de lecture de cause hors autorisation).
Fault.ErrorId := 0;
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active THEN
            Fault.ErrorId := Fault.ErrorId OR SHL(WORD#1, INT_TO_DWORD(i));
        END_IF;
    END_FOR;
END_IF;
Fault.Error := (Fault.ErrorId <> 0);
{endregion}

{region "§3 Armement des latches (causes à acquitter)"}
// Une cause Active ET Latching arme son bit ; le bit reste jusqu'au front Reset (§1),
// même si la cause disparaît. Réapparition => ré-armement (ré-alarme).
IF Enable THEN
    FOR i := 0 TO 15 DO
        IF Causes[i].Active AND Causes[i].Latching THEN
            Latch[i] := TRUE;
        END_IF;
    END_FOR;
END_IF;
{endregion}

{region "§4 Vue LATCHÉE — Latched / LatchedId"}
// Toujours publiée, y compris Enable=FALSE : un défaut non acquitté reste visible.
Fault.LatchedId := 0;
FOR i := 0 TO 15 DO
    IF Latch[i] THEN
        Fault.LatchedId := Fault.LatchedId OR SHL(WORD#1, INT_TO_DWORD(i));
    END_IF;
END_FOR;
Fault.Latched := (Fault.LatchedId <> 0);
{endregion}

{region "§1 Lissage anti-clignotement"}
// Défaut critique : affichage immédiat, le TON est remis à zéro (aucune latence).
IF ForceInstant THEN
    Text := NewText;
    TonHold(IN := FALSE);
ELSE
    // Warning / état : le texte ne change qu'après maintien min (HoldTime).
    // Un signal qui oscille plus vite que HoldTime → texte stable.
    TonHold(IN := (NewText <> Text), PT := HoldTime);
    IF TonHold.Q THEN
        Text := NewText;
    END_IF;
END_IF;
{endregion}

{region "§1 Acquisition temps"}
// 1. ACQUISITION DU TEMPS SYSTÈME
TimeCurrent := TIME();
{endregion}

{region "§2 Initialisation"}
// 2. INITIALISATION UNIQUE AU PREMIER CYCLE
IF NOT InitDone THEN
    TimeLast := TimeCurrent;
    InitDone := TRUE;
    CycleTimeS := DefaultValueS;
    RETURN;
END_IF;
{endregion}

{region "§3 Calcul delta"}
// 3. CALCUL DU DELTA EN MILLISECONDES
DeltaTimeMs := TIME_TO_UDINT(TimeCurrent - TimeLast);
{endregion}

{region "§4 Conversion, secours et bornage"}
// 4. CONVERSION EN SECONDES, AVEC DOUBLE BORNAGE DU DELTA
//
// TIME() est un compteur systeme 32 bits en millisecondes depuis le demarrage de
// l'automate. Il n'est PAS absolu : il reboucle a 0 tous les 2^32 ms (~49,7 jours).
// La soustraction TimeCurrent - TimeLast est modulo 2^32 : au passage du rebouclage,
// tant que l'ecart reel entre deux scans reste < 49,7 j (toujours vrai a 10 ms),
// DeltaTimeMs reste correct. Le rebouclage seul n'est donc pas le risque principal.
//
// Le vrai risque est un DeltaTimeMs REELLEMENT > CST_MaxCycleDeltaMs : reprise apres
// un online-change, sortie d'un point d'arret / pas-a-pas debug, ou fenetre du
// rebouclage TIME(). Le chien de garde tache (200 ms, sensibilite 1) borne deja les
// gels en fonctionnement ; ce plafond couvre les cas hors surveillance.
// Un dt aberrant publie tel quel donnerait un CycleTimeS enorme, propage en un seul
// scan dans les rampes de vitesse et les integrateurs de position/frein -> saut
// physique. Fail-safe : hors de la plage nominale (0 < dt <= plafond), on publie la
// valeur de secours DefaultValueS au lieu de l'artefact. Pas de redemarrage auto.
//
// Borne basse dt = 0 (anti-zero, ex. premier appel du scan) et borne haute
// dt > CST_MaxCycleDeltaMs (anti-artefact) partagent la meme branche de secours.
IF (DeltaTimeMs > 0) AND (DeltaTimeMs <= CST_MaxCycleDeltaMs) THEN
    CycleTimeS := UDINT_TO_REAL(DeltaTimeMs) / 1000.0;
ELSE
    CycleTimeS := DefaultValueS;
END_IF;
{endregion}

{region "§5 Archivage"}
// 5. ARCHIVAGE POUR LE PROCHAIN CYCLE
TimeLast := TimeCurrent;
{endregion}
